    setTimeout(function(){if(PV&&PV.gyro&&!PV.ori){toast('هذا الجهاز لا يدعم حساس الحركة. استخدم الجوال أو التابلت.');pvToggleGyro();if(PV.vr)pvToggleVR();}},1800);
