  s+=psyL(x0+L*0.7,y0+D*0.5,x1-2,y0+D*0.5,'',.45);
  s+=psyHandle(x0+L*0.3-6,y1-6,5,false)+psyHandle(x0+L*0.7+2,y0+D*0.25,5,false);
