    var pts=[[-hw,-hd],[hw,-hd],[hw,hd],[-hw,hd],[-hw,-hd]].map(function(q){return new THREE.Vector3(cx+q[0]*c-q[1]*s,CY+q[0]*s+q[1]*c,0.8);});
