  sc.left=-R*1.3;sc.right=R*1.3;sc.top=R*1.3;sc.bottom=-R*1.3;sc.near=1;sc.far=R*9;sc.updateProjectionMatrix();
  G.fill.position.set(cx+R*(1.5*cyw+1.2*syw),cy+R*(-1.5*syw+1.2*cyw),cz+R);G.fill.target.position.set(cx,cy,cz);
  p3gStyle(G);
