    '<div class="pp-cls">'+CLRS.map(function(c){return '<button type="button" class="pp-c'+(c[1]===cur?' on':'')+'" style="background:'+c[1]+'" title="'+esc(c[0])+'" aria-label="'+esc(c[0])+'" data-qc="'+c[1]+'"></button>';}).join('')+
    '<label class="pp-cc" title="لون مخصص">＋<input type="color" value="'+cur+'" data-qcin="1"></label></div>'+
    '<div class="pp-clf"><span>'+esc(clrName(cur)||'')+'</span><button type="button" data-q="creset">اللون الأصلي</button></div>';
