/* ================= مجسم ثلاثي الأبعاد تفاعلي (Canvas بدون مكتبات خارجية) ================= */
var FVFIN=[['خشب فاتح',[226,190,130]],['بلوط',[200,156,98]],['جوزي',[118,76,50]],['أبيض',[240,238,233]],['رمادي',[152,158,164]],['أسود',[52,50,53]],['بيج',[218,200,170]],['أزرق',[96,128,160]]];
