    fvB(a,x+1.2,yy,z+1,0.8,tl,th,C.wi);
    fvB(a,x+wd-2,yy,z+1,0.8,tl,th,C.wi);
    fvB(a,x+1.2,yy+tl-0.8,z+1,wd-2.4,0.8,th,C.wi);
