  if(d.ups&&d.ups!=='none')rows.push(['تنجيد السرير',UPSL[d.ups]+(fvHex(d.upc)?' — لون القماش '+sw(d.upc):'')]);
  if(d.hbd&&d.hbd!=='none')rows.push(['شكل تنجيدة رأس السرير',(HBDL[d.hbd]||'')+((d.hbd==='vert'||d.hbd==='horiz'||d.hbd==='grid')?' — عدد '+(d.hbn||3):'')]);
