  if(d.dt)rows.push(['نوع أبواب الدولاب',DTL[d.dt]||'']);
  if(d.dsm&&d.dsm!=='mid'&&d.dt!=='slide'){var dsx=dsDesc(d,(d.dsl&&d.dsl.length)?d.dsl.length:fdef(FT[1],d,num(d.l)).doors);if(dsx)rows.push(['اتجاه فتح الأبواب',dsx]);}
