  if(c==='jobs'||c==='scopes'||c==='costs'){var o=orders.filter(function(x){return x.id===id;})[0];return o?(o.orderNo||id)+(o.custName?' — '+o.custName:''):id;}
  return r.name||r.code||r.no||r.title||id;
