function nvxTables(){
  var now=new Date().toISOString(),t={};
  t.orders=orders.map(function(o){var r={};Object.keys(o).forEach(function(k){if(k!=='lines'&&k!=='imgs'&&typeof o[k]!=='object')r[k]=o[k];});r.updated_at=now;return r;});
  t.order_lines=[];orders.forEach(function(o){(o.lines||[]).forEach(function(l,i){var r={id:o.id+':'+i,order_id:o.id,idx:i};Object.keys(l).forEach(function(k){if(k!=='parts'&&k!=='img'&&typeof l[k]!=='object')r[k]=l[k];});t.order_lines.push(r);
    (l.parts||[]).forEach(function(pt,pi){t.order_line_parts=t.order_line_parts||[];t.order_line_parts.push({id:o.id+':'+i+':'+pi,line_id:o.id+':'+i,name:pt.name,qty:pt.qty,size:pt.size||'',color:pt.color||'',service:!!pt.svc});});});});
  t.materials=materials.map(function(m){var r={};Object.keys(m).forEach(function(k){if(k!=='img'&&typeof m[k]!=='object')r[k]=m[k];});return r;});
  t.boms=boms.map(function(b){return {id:b.id,code:b.code||'',name:b.name||'',tpl:b.tpl||''};});
  t.bom_components=[];boms.forEach(function(b){(b.comps||[]).forEach(function(c,i){t.bom_components.push({id:b.id+':'+i,bom_id:b.id,material_id:c.mat,qty:c.qty,waste_pct:c.waste||0,section:c.sec||''});});});
  t.purchase_requests=prs.map(function(p){return {id:p.id,no:p.no,date:p.date,status:p.status,supplier:p.supplier||'',applied:!!p.applied,order_ids:(p.orders||[]).join(',')};});
  t.purchase_lines=[];prs.forEach(function(p){(p.lines||[]).forEach(function(l,i){t.purchase_lines.push({id:p.id+':'+i,pr_id:p.id,material_id:l.mat,qty:l.qty,price:l.price||0});});});
  t.departments=depts.map(function(d){return {id:d.id,name:d.name,head:d.head||''};});
  t.workers=nvwWorkers().map(function(w){return {id:w.id,name:w.name,department_id:w.dept||'',phone:w.phone||'',active:w.active!==false};});
  t.job_stages=[];t.stage_stops=[];
  Object.keys(jobs).forEach(function(oid){var j=jobs[oid];(j.lines||[]).forEach(function(lj,i){
    var put=function(u,pi){(u&&u.stages||[]).forEach(function(s,k){var id=oid+':'+i+':'+(pi===''?'-':pi)+':'+k;
      t.job_stages.push({id:id,order_id:oid,line_idx:i,part_idx:pi===''?null:pi,seq:k,name:s.name,state:s.state,department_id:nvwDeptOf(s)||'',worker_id:s.wk||'',owner:s.owner||'',planned:s.plan||'',done_date:s.done||'',started_at:s.st||'',ended_at:s.en||'',qty_required:s.rq==null?null:s.rq,qty_done:s.dq==null?null:s.dq,waste:s.ws==null?null:s.ws,stop_reason:s.stop?s.stop.r:'',note:s.note||'',photos:(s.ph||[]).length});
      (s.stops||[]).forEach(function(x,n){t.stage_stops.push({id:id+':'+n,stage_id:id,reason:x.r,from:x.f,to:x.t});});});};
    if(lj.pj)lj.pj.forEach(function(u,pi){put(u,pi);});else put(lj,'');});});
  t.material_issues=[];Object.keys(jobs).forEach(function(oid){var j=jobs[oid];(j.pis||[]).forEach(function(x){x.items.forEach(function(it,i){t.material_issues.push({id:x.id+':'+i,order_id:oid,kind:x.kind,date:x.date,material_id:it.mat,qty:it.qty,note:x.note||'',user:x.u||''});});});
    if(j.issued&&!j.issued.partial)(j.issued.items||[]).forEach(function(it,i){t.material_issues.push({id:oid+':full:'+i,order_id:oid,kind:'صرف كامل',date:j.issued.date,material_id:it.mat,qty:it.qty,note:'',user:''});});});
  t.qc_checks=[];t.qc_defects=[];Object.keys(jobs).forEach(function(oid){var q=jobs[oid].qc;if(!q)return;q.items.forEach(function(x,i){t.qc_checks.push({id:oid+':'+i,order_id:oid,round:q.round,item:x.t,result:x.r,note:x.note||''});});
    q.defects.forEach(function(d){t.qc_defects.push({id:d.id,order_id:oid,desc:d.desc,severity:d.sev,status:d.st,line_idx:d.l===''?null:d.l,rework_stage:d.rw?d.rw.st:'',date:d.date,user:d.by||''});});});
  t.stock_moves=NVS.moves.map(function(e){return {id:e.id,at:new Date(e.t).toISOString(),material_id:e.mat,qty:e.q,balance:e.bal,type:e.type,ref:e.ref||'',user:e.u||''};});
  t.audit_log=NVG.audit.map(function(e,i){return {id:e.t+':'+i,at:new Date(e.t).toISOString(),user:e.u||'',source:e.s||'',entity:e.c,record_id:e.k,action:e.a==='+'?'insert':e.a==='-'?'delete':'update',label:e.n||'',changes:JSON.stringify(e.d||[])};});
  return {kind:'niveen-tables',v:1,exported_at:now,note:'جداول منفصلة بمعرّفات ثابتة للترحيل لاحقًا إلى Firebase أو Supabase. لا تُستورد إلى التطبيق؛ للاستعادة استخدم «النسخة الكاملة».',tables:t,counts:Object.keys(t).reduce(function(a,k){a[k]=t[k].length;return a;},{})};
}
