      if(o.status===STATUS[4]&&!nvdlComplete(o)&&dd.prevSt){o.status=dd.prevSt;delete o.dlvAt;if(typeof NVREP==='object')NVREP.prev[o.id]=o.status;msg+=' — عاد الطلب إلى «'+o.status+'» (التجميد محفوظ في السجل)';if(dd.frozen){(dd.frozenH=dd.frozenH||[]).push(dd.frozen);delete dd.frozen;}}
