var NVKP_NEW={pur:'المشتريات وأوامر الشراء',sup:'أداء الموردين',er:'البلاغات والإجراءات التصحيحية',stg:'أداء المراحل والأقسام',inv:'المخزون والأرصدة',fcost:'التكلفة الكاملة والانحراف'};
