          if(gl){box('باب زجاج','glass',x0,x0+dw,y0,y1,frZ+0.6,frZ+1.0,{cut:false,lock:false,grp:id});H0.glass.push(R1(dw)+' × '+R1(dh));}
          else box('باب','front',x0,x0+dw,y0,y1,frZ,frZ1,{eb:front4(dw,dh),grp:id});
          var hx=hingeL?x0+dw-3:x0+3,hy=Math.max(y0+12,Math.min(y1-12,105));
