        var fh=y1-y0,bw=wi-2.6,bz=inset?Db-t:Db,sd=slideLen((inset?bd-t:bd)-2),bh=Math.max(8,Math.min(20,fh-5)),id2='g'+(++gid),by0=y0+2.5,by1=by0+bh,bx0=mx-bw/2;
