  /* دمج نتيجة فرعية بإزاحة وإعادة ترقيم المجموعات */
  function merge(dst,src,dx,dy,dz,pre){
    var ids={};src.G.forEach(function(g){var c=JSON.parse(JSON.stringify(g));c.id=pre+g.id;ids[g.id]=c.id;c.px+=dx;c.py+=dy;c.pz+=dz;dst.G.push(c);});
    src.P.forEach(function(p){var c=JSON.parse(JSON.stringify(p));c.cx+=dx;c.cy+=dy;c.cz+=dz;if(c.grp)c.grp=ids[c.grp];c.id=dst.P.length+1;dst.P.push(c);});
    src.hw.forEach(function(h){addHw(dst.hw,h.k,h.name,h.qty,h.unit,h.spec,h.alt);});
    (src.warn||[]).forEach(function(w){dst.warn.push(w);});
  }
  function addHw(hw,k,name,qty,unit,spec,alt){if(!(qty>0))return;for(var i=0;i<hw.length;i++)if(hw[i].name===name){hw[i].qty=R1(hw[i].qty+qty);if(alt&&hw[i].alt)for(var a in alt)hw[i].alt[a]=Math.round(((hw[i].alt[a]||0)+alt[a])*10000)/10000;return;}var o={k:k,name:name,qty:R1(qty),unit:unit||'عدد',spec:spec||''};if(alt)o.alt=JSON.parse(JSON.stringify(alt));hw.push(o);}
