/* ---------------- بوف / دكة ---------------- */
function genPouf(s){
  var W=cl(s.W,30,250),D=cl(s.D,30,120),H=cl(s.H,25,70),t=cl(s.t,1.2,2.5),lh=s.legs?cl(s.legH,4,25):0,cT=cl(s.foamT,3,15),wst=cl(s.waste,0,100),fw=cl(s.fabW,50,320);
  var out={P:[],G:[],hw:[],warn:[]},box=N.mkBox(out),hb=H-lh-cT,lid=!!s.storage;
  if(hb<10)out.warn.push('ارتفاع الصندوق أقل من 10 سم — قلّل سُمك الإسفنج أو ارتفاع الأرجل.');
  var sT=(lid||!(s.gv>=2))?lh+hb:lh+hb-t; /* V54: الجلسة فوق الجوانب في التصاميم الجديدة */
  box('جنب أمامي','body',0,W,lh,sT,0,t,{});box('جنب خلفي','body',0,W,lh,sT,D-t,D,{});
  box('جنب','body',0,t,lh,sT,t,D-t,{});box('جنب','body',W-t,W,lh,sT,t,D-t,{});
  box('قاعدة','inner',t,W-t,lh,lh+t,t,D-t,{});box(lid?'غطاء التخزين':'لوح الجلسة','body',0,W,lh+hb-(lid?0:t),lh+hb+(lid?t:0),0,D,{});
  if(lid){addHw(out.hw,'hinge','مفصلة غطاء صندوق',2);addHw(out.hw,'hinge','ذراع رافع للغطاء (ستاي)',2);}
  box('إسفنج وكسوة الجلسة','fabric',0,W,lh+hb+(lid?t:0),H,0,D,{cut:false,lock:false});box('كسوة الجوانب','fabric',-0.4,W+0.4,lh,lh+hb,-0.4,D+0.4,{cut:false,lock:false});
  addHw(out.hw,'foam','إسفنج جلسة '+R1(W)+' × '+R1(D)+' × '+R1(cT)+' سم',1,'لوح');
  var side=2*(W+D)*hb/10000;addHw(out.hw,'foam','إسفنج تغليف 1 سم للجوانب',Math.round(side*100)/100,'م²');
  var top=(W+2*cT+12)*(D+2*cT+12)/10000,sides=2*(W+D+8)*(hb+12)/10000;addHw(out.hw,'fabric','قماش تنجيد عرض '+fw+' سم (مساحة '+Math.round((top+sides)*100)/100+' م² + هدر '+wst+'%)',fabM(top+sides,fw,wst),'م.ط');
  if(s.tuft){var nb=Math.max(1,Math.floor(W/15))*Math.max(1,Math.floor(D/15));addHw(out.hw,'uph','زر كابتونيه مغلّف',nb);}
  addHw(out.hw,'uph','دبابيس تنجيد',1,'علبة');
  if(lh){[[3,3],[W-3,3],[3,D-3],[W-3,D-3]].forEach(function(p){box('رجل','fixed',p[0]-2,p[0]+2,0,lh,p[1]-2,p[1]+2,{cut:false,lock:false,shape:'cylY'});});addHw(out.hw,'leg','رجل بوف ارتفاع '+R1(lh)+' سم',4);}
  else addHw(out.hw,'leg','لباد قاعدة',4);
  addHw(out.hw,'cam','برغي خشب + غراء (نقطة تجميع)',16);
  return finish(out.P,out.G,out.hw,W,H,D,[W/2,D/2],false,out.warn);
}
N.register('pouf',{name:'بوف / دكة',
  defaults:function(){return {kind:'pouf',name:'دكة',W:120,D:45,H:46,t:1.8,legs:true,legH:10,foamT:8,storage:false,tuft:false,fabW:140,waste:15,col:''};},
  gen:genPouf,
  fields:[['W','العرض','cm',30,250],['D','العمق','cm',30,120],['H','الارتفاع','cm',25,70],['foamT','سُمك إسفنج الجلسة','cm',3,15],['legs','على أرجل','chk'],['legH','ارتفاع الأرجل','cm',4,25],
    ['storage','صندوق تخزين بغطاء','chk'],['tuft','كابتونيه (أزرار)','chk'],['t','سُمك ألواح الصندوق','sel',[[1.2,'12 مم'],[1.6,'16 مم'],[1.8,'18 مم']]],['fabW','عرض رول القماش (سم)','n',50,320],['waste','نسبة الهدر التي تعتمدها %','n',0,100]],
  fromDesign:function(sp){var d=sp.d||{};return {name:sp.name||'بوف',W:Math.round(sp.L),D:Math.round(sp.W),H:Math.round(sp.H),legs:d.base==='legs',storage:!!+d.store,tuft:!!+d.tuft};}});

/* ---------------- باب داخلي ---------------- */
function genDoor(s){
  var W=cl(s.W,60,140),H=cl(s.H,180,300),wd=cl(s.wallD,8,40),T=cl(s.leafT,3.5,5),jt=cl(s.jambT,1.8,4),aw=cl(s.archW,5,12),at=1.2,gap=0.3,out={P:[],G:[],hw:[],warn:[]},box=N.mkBox(out);
  var lw=W-2*jt-2*gap,lh=H-jt-gap-1,style=s.style||'flat',zc=wd/2;
  /* الحلق */
  box('حلق جانبي','body',0,jt,0,H,0,wd,{eb:[H]});box('حلق جانبي','body',W-jt,W,0,H,0,wd,{eb:[H]});box('حلق علوي','body',jt,W-jt,H-jt,H,0,wd,{eb:[W-2*jt]});
  /* الكشفات للجهتين */
  [[-at,0],[wd,wd+at]].forEach(function(z){box('كشفة جانبية','body',-aw+jt,jt,0,H+aw-jt,z[0],z[1],{eb:[H+aw,H+aw]});box('كشفة جانبية','body',W-jt,W+aw-jt,0,H+aw-jt,z[0],z[1],{eb:[H+aw,H+aw]});box('كشفة علوية','body',-aw+jt,W+aw-jt,H,H+aw-jt,z[0],z[1],{eb:[W+2*aw,W+2*aw]});});
  /* الضلفة: إطار خشب صلب + حشوة + وجهان */
  var sk=0.6,x0=jt+gap,y0=1;
  box('وجه الضلفة (HDF)','front',x0,x0+lw,y0,y0+lh,zc-T/2,zc-T/2+sk,{});box('وجه الضلفة (HDF)','front',x0,x0+lw,y0,y0+lh,zc+T/2-sk,zc+T/2,{});
  box('إطار الضلفة وحشوتها','inner',x0,x0+lw,y0,y0+lh,zc-T/2+sk,zc+T/2-sk,{cut:false,lock:false});
  addHw(out.hw,'solid','قائم إطار ضلفة خشب صلب 3.5×'+R1(T-2*sk)+' سم بطول '+R1(lh)+' سم',2);addHw(out.hw,'solid','عارضة إطار ضلفة خشب صلب 3.5×'+R1(T-2*sk)+' سم بطول '+R1(lw-7)+' سم',3);
  addHw(out.hw,'other','حشوة كرتون خلية (هانيكومب)',Math.round(lw*lh/10000*100)/100,'م²');
  addHw(out.hw,'edge','شريط حافة للضلفة سمك '+R1(T*10)+' مم',Math.ceil(2*(lw+lh)/100*10)/10,'م.ط');
  if(style==='p2'||style==='p4'||style==='gh'||style==='gv')out.warn.push('تفاصيل '+({p2:'الحشوتين',p4:'الحشوات الأربع',gh:'الخطوط الأفقية',gv:'الخطوط العمودية'})[style]+' تُفرَز على وجه الضلفة بالـCNC بعد الكبس.');
  if(style==='gs'||style==='gf'){var gw=style==='gf'?lw-20:10,gh2=style==='gf'?lh-20:lh-40;addHw(out.hw,'glass','زجاج '+(s.glass==='clear'?'شفاف':s.glass==='smoke'?'مدخّن':'مصنفر')+' '+R1(gw)+'×'+R1(gh2)+' سم سمك 5 مم',1);addHw(out.hw,'other','برواز تثبيت الزجاج',Math.ceil(2*(gw+gh2)*2/100*10)/10,'م.ط');}
  var nh=H<=210?3:4;addHw(out.hw,'hinge','مفصلة باب 4 بوصة (بلية)',nh);
  addHw(out.hw,'lock','كالون باب '+(s.lock==='bath'?'حمام (مقفل من الداخل)':'غرف بمفتاح'),1);
  addHw(out.hw,'handle',s.handle==='knob'?'مقبض باب دائري (طقم)':s.handle==='pull'?'مسكة طولية للباب (طقم)':'مقبض باب ذراع (طقم)',1);
  addHw(out.hw,'other','مطاط عازل للحلق',Math.ceil((2*H+W)/100*10)/10,'م.ط');addHw(out.hw,'fix','فوم تثبيت الحلق',1,'علبة');addHw(out.hw,'fix','وتد/برغي تثبيت الحلق',8);
  if(lw>100)out.warn.push('ضلفة أعرض من 100 سم — يُنصح بضلفتين.');
  return finish(out.P,out.G,out.hw,W,H,wd,[W/2,wd/2],false,out.warn);
}
N.register('door',{name:'باب داخلي',
  defaults:function(){return {kind:'door',name:'باب داخلي',W:90,H:210,wallD:15,leafT:4,jambT:2.5,archW:7,style:'flat',glass:'frost',handle:'lever',lock:'room',t:1.8,col:''};},
  gen:genDoor,
  fields:[['W','عرض الفتحة (خارج الحلق)','cm',60,140],['H','ارتفاع الفتحة','cm',180,300],['wallD','سُمك الجدار (عمق الحلق)','cm',8,40],['leafT','سُمك الضلفة','sel',[[3.5,'35 مم'],[4,'40 مم'],[4.5,'45 مم']]],
    ['jambT','سُمك الحلق','sel',[[1.8,'18 مم'],[2.5,'25 مم'],[3,'30 مم']]],['archW','عرض الكشفة','cm',5,12],['style','شكل الضلفة','sel',[['flat','سادة'],['p2','حشوتان'],['p4','أربع حشوات'],['gh','خطوط أفقية'],['gv','خطوط عمودية'],['gs','شريط زجاج'],['gf','زجاج كامل بإطار']]],
    ['glass','الزجاج','sel',[['frost','مصنفر'],['clear','شفاف'],['smoke','مدخّن']]],['handle','المقبض','sel',[['lever','ذراع'],['knob','دائري'],['pull','مسكة طولية']]],['lock','الكالون','sel',[['room','غرف بمفتاح'],['bath','حمام']]]],
  fromDesign:function(sp){var d=sp.d||{};return {name:sp.name||'باب داخلي',W:Math.round(sp.L),H:Math.round(sp.H),wallD:Math.max(8,Math.round(sp.W)),style:d.style==='arch'||d.style==='p6'?'p4':(d.style||'flat'),glass:d.glass||'frost',handle:d.handle==='none'?'lever':(d.handle||'lever'),col:/^#[0-9a-f]{6}$/i.test(d.doorc||'')?d.doorc:''};}});

/* ---------------- ستارة ---------------- */
var CT_FULL={wave:2.2,pleat:2.5,flat:1.5,roman:1.15,roller:1};
function genCurtain(s){
  var W=cl(s.W,40,1500),H=cl(s.H,40,500),st=s.style||'wave',np=st==='roman'||st==='roller'?1:(s.panels==='1'?1:2),full=cl(s.full||CT_FULL[st],1,3.5),rw=cl(s.rollW,90,330),rail=s.rail!==false,wst=cl(s.waste,0,50);
  var out={P:[],G:[],hw:[],warn:[]},box=N.mkBox(out),hem=15+10,side=2*5*np;
  /* عرض القماش المطلوب = عرض السكة × الكثافة + ثنيات الجوانب */
  var fabW=W*full+side,m,how;
  if(st==='roller'){m=(H+30)/100;how='رول: ارتفاع '+R1(H+30)+' سم بعرض '+R1(W)+' سم';if(W>rw)out.warn.push('عرض الرول '+R1(W)+' سم أكبر من عرض القماش '+R1(rw)+' سم — يحتاج قماش أعرض.');}
  else if(rail&&H+hem<=rw){m=fabW/100;how='بالعرض (القماش بارتفاع '+R1(rw)+' سم يغطي الطول '+R1(H)+' سم)';}
  else{var drops=Math.ceil(fabW/rw);m=drops*(H+hem)/100;how=drops+' شُقّة × '+R1(H+hem)+' سم';}
  m=Math.ceil(m*(1+wst/100)*10)/10;
  addHw(out.hw,'fabric','قماش ستارة '+({wave:'ويف',pleat:'كسرات',flat:'سادة',roman:'رومانية',roller:'رول'})[st]+' — '+how+' (كثافة ×'+full+(wst?' + هدر '+wst+'%':'')+')',m,'م.ط');
  if(s.lining)addHw(out.hw,'fabric','بطانة بلاك أوت — نفس كمية القماش',m,'م.ط');
  if(s.sheer&&st!=='roller'&&st!=='roman'){var sm=Math.ceil((W*2.5+side)/100*(1+wst/100)*10)/10;addHw(out.hw,'fabric','قماش شيفون (طبقة ثانية) بكثافة ×2.5',sm,'م.ط');}
  var tl=Math.ceil((W+10)/10)/10;
  if(st==='roller'){addHw(out.hw,'track','آلية رول (ماسورة + سلسلة + حوامل) عرض '+R1(W)+' سم',1);}
  else if(st==='roman'){addHw(out.hw,'track','آلية رومانية (سكة + حبال + بكرات) عرض '+R1(W)+' سم',1);addHw(out.hw,'other','عصي/قضبان طي رومانية',Math.max(3,Math.round(H/30)),'عدد');}
  else{var lay=s.sheer?2:1;addHw(out.hw,'track',(s.track==='rod'?'عمود ستارة مع أطراف':'سكة ستارة سقفية')+(lay>1?' مزدوجة':''),tl,'م.ط');
    var gl=Math.ceil(W*full/(st==='wave'?8:st==='pleat'?10:12))+2*np;addHw(out.hw,'roller','عربات/حلقات سكة',gl*lay);addHw(out.hw,'other','شريط رأس الستارة ('+({wave:'ويف',pleat:'كسرات',flat:'عادي'})[st]+')',Math.ceil(fabW/100*10)/10*lay,'م.ط');
    addHw(out.hw,'fix','حامل سكة سقفي/جداري',(Math.ceil(W/80)+1)*1);addHw(out.hw,'other','نهاية سكة (ستوب)',2*np);addHw(out.hw,'other','خطافات/مشابك',gl*lay);}
  /* شكل للعرض فقط */
  if(st==='roller'||st==='roman')box('قماش الستارة','fabric',0,W,H*0.15,H-5,4,5,{cut:false,lock:false});
  else{var cov=W*(1-0.5*cl(s.open,0,90)/100);if(np===2){box('ضلفة ستارة','fabric',0,cov/2,1,H-4,3,8,{cut:false,lock:false});box('ضلفة ستارة','fabric',W-cov/2,W,1,H-4,3,8,{cut:false,lock:false});}else box('ضلفة ستارة','fabric',W-cov,W,1,H-4,3,8,{cut:false,lock:false});}
  box('السكة','fixed',0,W,H-4,H,4,7,{cut:false,lock:false});
  return finish(out.P,out.G,out.hw,W,H,10,[W/2,5],false,out.warn);
}
N.register('curtain',{name:'ستارة',
  defaults:function(){return {kind:'curtain',name:'ستارة',W:240,H:260,style:'wave',panels:'2',full:2.2,rollW:280,rail:true,lining:false,sheer:true,track:'track',waste:5,open:25,t:1.8,col:''};},
  gen:genCurtain,
  fields:[['W','عرض السكة','cm',40,1500],['H','طول الستارة (السقوط)','cm',40,500],['style','النوع','sel',[['wave','ويف'],['pleat','كسرات'],['flat','سادة'],['roman','رومانية'],['roller','رول']]],['panels','الضلف','sel',[['2','ضلفتان'],['1','ضلفة واحدة']]],
    ['full','الكثافة (ضعف العرض)','n',1,3.5],['rollW','عرض/ارتفاع رول القماش (سم)','n',90,330],['rail','القماش بالعرض (Railroad) عند الإمكان','chk'],['lining','بطانة بلاك أوت','chk'],['sheer','طبقة شيفون','chk'],
    ['track','التعليق','sel',[['track','سكة سقفية'],['rod','عمود بأطراف']]],['waste','نسبة الهدر %','n',0,50]],
  fromDesign:function(sp){var d=sp.d||{},st=d.style||'wave';return {name:sp.name||'ستارة',W:Math.round(sp.L),H:Math.round(sp.H),style:st==='double'?'wave':st,panels:d.panels==='1'?'1':'2',full:CT_FULL[st==='double'?'wave':st]||2.2,sheer:st==='double',track:d.rod==='rod'?'rod':'track',open:+d.open||25};}});
