  if((len-(n-1)*tz)/n<60)return {err:'القسم صغير على هذا العدد من الأجزاء'};
  var items=z.items;z.dir=dir;z.items=[];z.kids=[];z.sz=[];
  for(var i=0;i<n;i++){z.kids.push({id:nid(s,'z'),dir:null,kids:[],sz:[],items:[]});z.sz.push(sizes&&sizes[i]>0?+sizes[i]:null);}
