      var f={id:nid(s,'f'),k:k,bind:{zones:zones==='all'&&groups.length===1?'all':G[0].slice(),i:i,n:m,target:zones==='all'?'all':zones.slice(),set:set},style:o.style||'flat',handle:o.handle||'',hinge:hinge,track:k==='slide'?i%2:0};
      if(o.hinge&&m===1&&groups.length===1)f.hinge=o.hinge;
