/* ---------------- الواجهات الهندسية الثلاث من نفس البيانات ---------------- */
/* front: x-y (من الأمام)، side: z-y (من اليمين: العمق أفقيًا)، top: x-z (من الأعلى). كل شكل يحمل مصدره للتحديد */
function views(spec,opt){
  opt=opt||{};var R=gen(spec),out={front:[],side:[],top:[],W:spec.W,H:spec.H,D:spec.D,warn:R.warn,layout:R.layout};
  var cx0=spec.W/2,cz0=spec.D/2,cut=opt.cutX!=null?+opt.cutX:spec.W/2,cutY=opt.cutY!=null?+opt.cutY:spec.H/2;out.cutX=cut;out.cutY=cutY;
  R.panels.forEach(function(p){
    if(opt.noFronts&&/^front:/.test(p.src||''))return;
    var x0=p.cx*10+cx0-p.sx*5,x1=x0+p.sx*10,y0=p.cy*10-p.sy*5,y1=y0+p.sy*10,z0=p.cz*10+cz0-p.sz*5,z1=z0+p.sz*10;
    var b={src:p.src,role:p.role,name:p.name,shape:p.shape||''};
    out.front.push(Object.assign({x:x0,y:y0,w:x1-x0,h:y1-y0,d:z1},b));
    /* الجانبي = قطاع عند x=cut: القطع التي يقطعها المستوى، والجنب الأيسر خلفية (الجنب الأيمن بين المشاهد والقطاع فلا يُرسم) */
    var inCut=x0<=cut+0.01&&x1>=cut-0.01;
    if(inCut||p.name==='جنب أيسر')out.side.push(Object.assign({x:spec.D-z1,y:y0,w:z1-z0,h:y1-y0,d:inCut?1e6+x1:x1,cut:inCut},b));
    /* العلوي = مقطع أفقي عند y=cutY والنظر لأسفل: ما فوق المستوى يُزال، وما يقطعه المستوى بارز، وما تحته يظهر خلفه */
    if(y0<=cutY+0.01){var hc=y1>=cutY-0.01;out.top.push(Object.assign({x:x0,y:z0,w:x1-x0,h:z1-z0,d:hc?1e6+y1:y1,cut:hc},b));}
  });
  out.front.sort(function(a,b){return a.d-b.d;});out.side.sort(function(a,b){return a.d-b.d;});out.top.sort(function(a,b){return a.d-b.d;});
  return out;
}

/* ---------------- قوالب بداية اختيارية (تُعدَّل بالكامل بعد الإنشاء) ---------------- */
function preset(name,W,H,D,o){
  var s=blank(W,H,D,o);
  if(name==='empty')return s;
  if(name==='wardrobe'){
    var n=Math.max(2,Math.round(W/600));OP.split(s,s.root.id,'v',n);
    var ks=s.root.kids;
    OP.addItem(s,ks[0].id,{k:'rail',y:layout(s).zones[ks[0].id].y1-layout(s).zones[ks[0].id].y0-120});
    if(ks[1]){var L=layout(s),h=L.zones[ks[1].id].y1-L.zones[ks[1].id].y0;OP.addItem(s,ks[1].id,{k:'drw',y:0,hs:[180,180,180],ext:false});OP.shelvesEven(s,ks[1].id,0);
      [700,1050,1400].forEach(function(y){if(y<h-s.t)OP.addItem(s,ks[1].id,{k:'shelf',y:y,fix:false});});}
    for(var i=2;i<ks.length;i++)OP.shelvesEven(s,ks[i].id,4);
    OP.doors(s,'all',Math.max(2,Math.round(W/500)),'swing');
    return s;
  }
  if(name==='open')return (OP.shelvesEven(s,s.root.id,4),s);
  return s;
}
