E.dims=function(o){o=o||selected;if(!o)return null;
  if(o.userData.kind==='group'){var b=wbox(o),s=new THREE.Vector3();b.getSize(s);return [s.x,s.y,s.z];}
  var d=o.userData.dims||[0,0,0];return [Math.abs(d[0]*o.scale.x),Math.abs(d[1]*o.scale.y),Math.abs(d[2]*o.scale.z)];};
E.setDims=function(w,h,d){
  var o=selected;if(!o)return;
  var u=o.userData;
  if(u.kind==='group'){toast('غيّر أبعاد العناصر داخل المجموعة — افتحها للتعديل');return;}
  if(u.prim&&(u.prim.k==='ext'||u.prim.k==='bool')){toast(u.prim.k==='ext'?'لتغيير سُمك الشكل المبثوق استخدم الدفع/السحب على وجه البثق':'العملية البوليانية: فكّها لتعديل أبعاد مكوّناتها');return;}
  if(u.kind==='mfg'){
    var sp=JSON.parse(JSON.stringify(u.mfg));
    if(sp.kind==='bed'){toast('مقاس السرير يُحدَّد من مقاس المرتبة في تبويب «الخصائص»');return;}
    sp.W=Math.max(30,Math.round(w*1000)/10);sp.H=Math.max(25,Math.round(h*1000)/10);sp.D=Math.max(20,Math.round(d*1000)/10);
    E.setSpec(sp,'تغيير أبعاد '+o.name);return;
  }
  var pr=JSON.parse(JSON.stringify(u.prim)),sx=Math.abs(o.scale.x)||1,sy=Math.abs(o.scale.y)||1,sz=Math.abs(o.scale.z)||1,mn=0.001;
  if(pr.k==='box'){pr.w=Math.max(mn,w/sx);pr.h=Math.max(mn,h/sy);pr.d=Math.max(mn,d/sz);}
  else if(pr.k==='cyl'){pr.r=Math.max(mn,w/sx/2);pr.h=Math.max(mn,h/sy);}
  else if(pr.k==='sphere'){pr.r=Math.max(mn,w/sx/2);}
  else if(pr.k==='plane'){pr.w=Math.max(mn,w/sx);pr.d=Math.max(mn,d/sz);}
  else{var od=primDims(pr);o.scale.set((o.scale.x<0?-1:1)*w/od[0],(o.scale.y<0?-1:1)*h/od[1],(o.scale.z<0?-1:1)*d/od[2]);syncSel();E.commit('تغيير أبعاد '+o.name);return;}
  replaceSel(build(Object.assign(ser(o),{prim:pr})),'تغيير أبعاد '+o.name);
};
