function lightsRebuild(){
  if(!scene)return;
  if(!lightGrp){lightGrp=new THREE.Group();lightGrp.name='أضواء المشهد';scene.add(lightGrp);}
  lightGrp.children.slice().forEach(function(c){lightGrp.remove(c);if(c.isLight&&c.dispose)c.dispose();disposeObj(c);});
  var n=0,skip=0,orphan=0;
  if((P&&P.lights||[]).some(function(L){return L.att;})&&root)root.updateMatrixWorld(true);
  (P&&P.lights||[]).forEach(function(L){
    if(L.on===false)return;var col=(L.c&&/^#[0-9a-f]{6}$/i.test(L.c))?new THREE.Color(L.c):kcol(L.K||3000),p=L.p||[0,2.4,0];
    function addLight(l){if(n>=LMAX){skip++;return false;}lightGrp.add(l);n++;return true;}
    if(L.att){if(!attLight(L,col,addLight))orphan++;return;}
    if(L.t==='point'){var pl=new THREE.PointLight(col,MAT.cd(L.lm,'point'),0,2);pl.position.set(p[0],p[1],p[2]);if(addLight(pl))lightGrp.add(mark(col,p,L.id));}
    else if(L.t==='spot'){var ha=Math.max(2,Math.min(160,+L.ang||40))*Math.PI/360,sl=new THREE.SpotLight(col,MAT.cd(L.lm,'spot',ha),0,ha,L.pen==null?0.35:+L.pen,2),a=L.aim||[p[0],0,p[2]];
      sl.position.set(p[0],p[1],p[2]);sl.target.position.set(a[0],a[1],a[2]);sl.castShadow=!!(L.sh&&S.shadows);if(sl.shadow&&sl.shadow.mapSize)sl.shadow.mapSize.set(1024,1024);
      if(addLight(sl)){lightGrp.add(sl.target);lightGrp.add(mark(col,p,L.id));}}
    else if(L.t==='strip'){
      var len=Math.max(0.05,+L.len||1),ax=L.ax==='z'?2:0,cnt=Math.max(1,Math.min(4,Math.round(len/0.5))),lm=(+L.lmm||300)*len/cnt;
      var bar=new THREE.Mesh(new THREE.BoxGeometry(ax===0?len:0.012,0.006,ax===0?0.012:len),new THREE.MeshBasicMaterial({color:col}));bar.position.set(p[0],p[1],p[2]);bar.userData.ledbar=L.id;lightGrp.add(bar);
      for(var i=0;i<cnt;i++){var off=(i+0.5)/cnt*len-len/2,q=[p[0]+(ax===0?off:0),p[1],p[2]+(ax===2?off:0)],h2=60*Math.PI/180;
        var s2=new THREE.SpotLight(col,MAT.cd(lm,'spot',h2),0,h2,0.8,2);s2.position.set(q[0],q[1]-0.004,q[2]);s2.target.position.set(q[0],q[1]-1,q[2]);if(addLight(s2))lightGrp.add(s2.target);}
    }
  });
  lightCnt=n;lightOrphans=orphan;marks(true);req();
  if(skip)toast('بعض الأضواء لم تُعرض: الحد الأقصى '+LMAX+' مصادر ضوء ديناميكية للحفاظ على أداء الهاتف');
  return n;
}
