/* حفظ كاميرا بموضع صريح (زوايا الغرفة التلقائية) */
E.camAdd=function(c,silent){if(!P)return null;var r={id:'K'+NV.uid(),name:String(c.name||'كاميرا'),p:c.p.map(rnd),t:c.t.map(rnd),fov:c.fov||55};P.cams=(P.cams||[]).concat([r]);if(!silent)E.commit('حفظ '+r.name);NV.emit('cams');return r.id;};
E.camGo=function(id){
  var c=(P.cams||[]).filter(function(x){return x.id===id;})[0];if(!c||!E.ready){toast('الكاميرا غير موجودة');return false;}
  if(S.layout!=='3d'&&S.layout!=='split'&&S.layout!=='cad3d')E.layout('3d');
  use3(false);cam3p.fov=c.fov||45;cam3p.position.set(c.p[0],c.p[1],c.p[2]);ctl3.target.set(c.t[0],c.t[1],c.t[2]);cam3p.up.set(0,1,0);cam3p.lookAt(ctl3.target);cam3p.updateProjectionMatrix();
  ctl3.update();req();NV.emit('view3','cam');NV.emit('lens',Math.round(MAT.mm(cam3p.fov)));return true;
};
E.camUpdate=function(id){var i=(P.cams||[]).map(function(x){return x.id;}).indexOf(id);if(i<0||!E.ready)return false;var r=camRec(P.cams[i].name);r.id=id;P.cams[i]=r;E.commit('تحديث '+r.name);NV.emit('cams');return true;};
E.camDel=function(id){var c=(P.cams||[]).filter(function(x){return x.id===id;})[0];if(!c)return false;P.cams=P.cams.filter(function(x){return x!==c;});E.commit('حذف '+c.name);NV.emit('cams');return true;};
