  tc.visible=st0.tc;selBox.visible=st0.sb;selBoxes.forEach(function(h,i){h.visible=st0.bx[i];});grid.visible=st0.gr;axes.visible=st0.ax;mGroup.visible=st0.mg;floor.visible=st0.fl;scene.background=st0.bg;marks(true);
