E.rects=function(){return rects;};
E.resize=layoutPanes;

/* ================= V15: استوديو الغرف ================= */
var ROOMM={};
function buildRoom(spec){
  var RM=NV.ROOM,G=RM.geom(spec),k=0.001,g=new THREE.Group(),mats={};
  function mat(role){if(mats[role])return mats[role];var m;
    if(role==='wall')m=mkMat(spec.wl.c||'#ece8e1',0.92,0);else if(role==='frame')m=mkMat('#d9d4cb',0.6,0.02);else if(role==='door')m=mkMat(spec.dc||'#a37b52',0.6,0.02);
    else if(role==='glass'&&realOn())m=glassPhys('#eef6f8',0.03,0.35);
    else if(role==='glass'){m=mkMat('#cfe6f2',0.05,0.9);m.transparent=true;m.opacity=0.35;}else if(role==='sillb')m=mkMat('#e9e4da',0.4,0.02);
    else if(role==='floor'){var lm=spec.fl.lib&&libDef(spec.fl.lib)?libMat(spec.fl.lib):null;m=lm||mkMat(spec.fl.c||'#b9a586',0.8,0);}
    else m=mkMat(spec.cl.c||'#f7f6f3',0.95,0);return (mats[role]=m);}
  G.boxes.forEach(function(b){var m=new THREE.Mesh(new THREE.BoxGeometry(b.sx*k,b.sy*k,b.sz*k),mat(b.role));m.position.set(b.cx*k,b.cy*k,b.cz*k);m.rotation.y=b.ry;
    m.userData.role='r_'+b.role;m.userData.src=b.src;m.userData.nin=b.nin;m.userData.wall=b.wall;m.userData.cw=[b.cx*k,b.cz*k];m.castShadow=b.role==='wall';m.receiveShadow=true;g.add(m);});
  var poly=spec.pts.map(function(p){return [p[0]*k,-p[1]*k];});
  var fm=dataMesh(NV.G3.extrude(poly,[],0.02),mat('floor'));fm.rotation.x=-Math.PI/2;fm.position.y=-0.019;fm.userData.role='r_floor';fm.receiveShadow=true;g.add(fm);
  if(fm.material.userData&&fm.material.userData.tex)ensureUV(fm,fm.material.userData.rot);
  var cm=dataMesh(NV.G3.extrude(poly,[],0.02),mat('ceil'));cm.rotation.x=-Math.PI/2;cm.position.y=spec.H*k;cm.userData.role='r_ceil';cm.userData.ceil=true;g.add(cm);
  var b0=RM.bounds(spec);g.userData.dims=[(b0.x1-b0.x0)*k,spec.H*k,(b0.z1-b0.z0)*k];
  return g;
}
/* إخفاء الجدران بين الكاميرا والغرفة (عرض مقطوع) — أثناء التجول تظهر كل الجدران والسقف */
var cutOn=true;
function roomCut(cam,persp){
  objects.forEach(function(o){if(o.userData.kind!=='room'||!o.visible)return;var sp=o.userData.room,show=sp.cl&&sp.cl.show;
    var hid={};o.traverse(function(x){if(!x.isMesh||!x.userData.nin||x.userData.wall==null)return;var c=x.userData.cw,n=x.userData.nin;
      var back=persp&&cutOn&&!walk&&((cam.position.x-c[0])*n[0]+(cam.position.z-c[1])*n[1])<-0.05;if(back)hid[x.userData.wall]=1;});
    o.traverse(function(x){if(!x.isMesh)return;if(x.userData.ceil){x.visible=!!walk||show==='always';return;}if(x.userData.wall!=null)x.visible=!hid[x.userData.wall];});
  });
}
E.roomCut=function(on){if(on!=null){cutOn=!!on;req();}return cutOn;};
function roomObj(){return objects.filter(function(o){return o.userData.kind==='room';})[0]||null;}
E.roomObj=roomObj;
E.room=function(){var o=roomObj();return o?JSON.parse(JSON.stringify(o.userData.room)):null;};
E.addRoom=function(spec){
  if(!E.ready)return null;if(roomObj()){toast('في المشروع غرفة بالفعل — عدّلها من تبويب «الغرفة»');return null;}
  var o=addObj(build({kind:'room',room:NV.ROOM.norm(JSON.parse(JSON.stringify(spec))),name:spec.name,locked:true}),false);o.position.set(0,0,0);
  E.commit('إنشاء غرفة «'+(spec.name||'غرفة')+'»');var b=NV.ROOM.bounds(spec);roomView(b,spec);return o;
};
E.setRoom=function(spec,label){
  var o=roomObj();if(!o)return false;var r=ser(o);r.room=NV.ROOM.norm(JSON.parse(JSON.stringify(spec)));r.name=spec.name||r.name;
  var n=build(r);replaceObj(o,n);if(selected===o){selected=n;syncSel();}req();E.commit(label||'تعديل الغرفة');return true;
};
function roomView(b,spec){var cx=(b.x0+b.x1)/2000,cz=(b.z0+b.z1)/2000,sz=Math.max(b.x1-b.x0,b.z1-b.z0)/1000;use3(false);
  cam3p.position.set(cx+sz*0.9,spec.H/1000*1.9,cz+sz*1.2);ctl3.target.set(cx,0.9,cz);cam3p.lookAt(ctl3.target);cam3p.updateProjectionMatrix();req();}
/* قطع الأثاث للتحليل (ملم): المركز والأبعاد المحلية والدوران */
E.roomItems=function(){
  return objects.filter(function(o){return o.userData.kind!=='room'&&o.visible;}).map(function(o){
    var d=o.userData.dims,w,dd,h,x=o.position.x,z=o.position.z,ry=o.rotation.y;
    var sc=o.scale,k=o.userData.kind;
    if(k==='mfg'&&d){w=d[0];h=d[1];dd=d[2];}
    else if((k==='fvp'||k==='model')&&d&&o.parent===root){w=d[0]*Math.abs(sc.x);h=d[1]*Math.abs(sc.y);dd=d[2]*Math.abs(sc.z);}
    else{var bb=new THREE.Box3().setFromObject(o);w=bb.max.x-bb.min.x;h=bb.max.y-bb.min.y;dd=bb.max.z-bb.min.z;x=(bb.max.x+bb.min.x)/2;z=(bb.max.z+bb.min.z)/2;ry=0;}
    var ds=k==='model'&&(Math.abs(sc.x-1)>1e-3||Math.abs(sc.y-1)>1e-3||Math.abs(sc.z-1)>1e-3);
    return {id:o.userData.id,name:o.name,kind:k,x:x*1000,z:z*1000,w:w*1000,d:dd*1000,h:h*1000,ry:ry,link:o.userData.link||null,
      disp:ds?{sx:sc.x,sy:sc.y,sz:sc.z,real:d?[d[0]*1000,d[1]*1000,d[2]*1000]:null}:null};});
};
/* V22: مقاس العرض — يغيّر حجم ظهور المجسم/الشكل فقط (scale)، والمقاس الحقيقي يبقى مسجّلًا؛ قطع التصنيع والمصممين تُغيَّر أبعادها الحقيقية من أدواتها */
E.setDisplaySize=function(id,w,h,d,uniform,label){
  var o=E.byId(id);if(!o)return false;var k=o.userData.kind;
  if(k==='mfg'){toast('قطع التصنيع لا تُحجَّم — غيّر أبعادها الحقيقية من تبويب «الأبعاد»');return false;}
  if(k==='fvp'){toast('غيّر مقاس هذا التصميم من قسم «المصمم» في الخصائص — هو مقاسه الحقيقي');return false;}
  if(k!=='model'){toast('مقاس العرض للمجسمات الجاهزة فقط — الأشكال تُغيَّر أبعادها من الخصائص');return false;}
  var r=o.userData.dims;if(!r||!(r[0]>0&&r[1]>0&&r[2]>0)){toast('المقاس الحقيقي غير معروف بعد — انتظر تحميل المجسم');return false;}
  var t=[w,h,d].map(function(v){return v>0?v/1000:null;});
  if(!t[0]&&!t[1]&&!t[2])return false;
  var f=[t[0]?t[0]/r[0]:null,t[1]?t[1]/r[1]:null,t[2]?t[2]/r[2]:null];
  if(uniform){var u=f.filter(function(v){return v;});var m=Math.min.apply(null,u);f=[m,m,m];}
  else f=f.map(function(v){return v||1;});
  if(f.some(function(v){return !(v>0.01&&v<100);})){toast('نسبة غير منطقية');return false;}
  o.scale.set(f[0]*Math.sign(o.scale.x||1),f[1],f[2]);if(selected===o)syncSel();req();E.commit(label||('مقاس عرض «'+o.name+'»'));return true;
};
E.resetScale=function(id){var o=E.byId(id);if(!o)return false;o.scale.set(1,1,1);if(selected===o)syncSel();req();E.commit('إرجاع «'+o.name+'» إلى مقاسه الحقيقي');return true;};
/* V22: وضع القطعة في أول مكان فارغ في الغرفة (بجانب الجدار، بلا تداخل ولا اعتراض باب/نافذة) */
