    walk={p:cam3p.position.clone(),t:ctl3.target.clone(),fov:cam3p.fov,pan:ctl3.enablePan,zm:ctl3.enableZoom,min:ctl3.minDistance,max:ctl3.maxDistance};
    var eye=Math.min(1.6,sp.H/1000-0.2);cam3p.fov=70;cam3p.position.set(cx,eye,cz+0.05);ctl3.target.set(cx,eye,cz);ctl3.enablePan=false;ctl3.enableZoom=false;ctl3.minDistance=0.01;ctl3.maxDistance=0.2;
