  if(!walk)return false;cam3p.position.copy(walk.p);ctl3.target.copy(walk.t);cam3p.fov=walk.fov;ctl3.enablePan=walk.pan;ctl3.enableZoom=walk.zm;ctl3.minDistance=walk.min;ctl3.maxDistance=walk.max;
