E.glb=function(){
  if(!objects.length)return Promise.reject(new Error('empty'));
  return import('three/addons/exporters/GLTFExporter.js').then(function(mod){
    return new Promise(function(res,rej){
      var ex=new mod.GLTFExporter(),vis=objects.filter(function(o){return o.visible;});
      ex.parse(vis,function(r){res(new Blob([r],{type:'model/gltf-binary'}));},function(err){rej(err);},{binary:true,onlyVisible:true});
    });
  });
};

/* ---------------- قائمة القطع ---------------- */
E.cutData=function(){
  var md=cutDataManual();if(md)return md;
  function col(arr,o){if(!o.visible)return;if(o.userData.kind==='mfg')arr.push(o);else if(o.userData.kind==='group')o.children.filter(isEnt).forEach(function(c){col(arr,c);});}
  var list=[];if(selected&&hasMfg(selected))col(list,selected);else objects.forEach(function(o){col(list,o);});
  if(!list.length)return null;
  var cls=[],warn=[];
  list.forEach(function(o){var r=NVM.gen(o.userData.mfg);cls.push({cl:NVM.cutList(r),hw:r.hw});r.warn.forEach(function(w){warn.push((list.length>1?o.name+': ':'')+w);});});
  var m=NVM.mergeCuts(cls);m.warn=warn;m.names=list.map(function(o){return o.name;});m.single=list.length===1;return m;
};

/* V17: عند وجود تعديلات يدوية تُبنى قائمة القطع المختصرة من القطع بعد التعديل (نفس صيغة cutData) */
function cutDataManual(){
  var list=mfgList(false);if(!list.some(function(o){return o.userData.cutx;}))return null;
  var L=E.mfgParts(false);if(!L)return null;var cls=[],warn=[];
  L.forEach(function(x){var map={},rows=[];x.b.parts.forEach(function(p){var Lc=NVM.R1(p.L/10),Wc=NVM.R1(p.W/10),k=p.name+'|'+Lc+'|'+Wc+'|'+p.T+'|'+(p.lock?1:0),r=map[k];
      var eb=0;['+u','-u'].forEach(function(e){if(p.eb[e])eb+=p.W/10;});['+v','-v'].forEach(function(e){if(p.eb[e])eb+=p.L/10;});
      if(!r){r=map[k]={name:p.name,L:Lc,W:Wc,t:p.T,q:0,lock:!!p.lock,eb:eb};rows.push(r);}r.q++;});
    cls.push({cl:{rows:rows},hw:x.hw});var o=E.byId(x.id);NVM.gen(x.spec).warn.forEach(function(w){warn.push((L.length>1?x.name+': ':'')+w);});(x.b.notes||[]).forEach(function(w){if(/يدويًا/.test(w))warn.push(w);});});
  var m=NVM.mergeCuts(cls);m.warn=warn;m.names=L.map(function(x){return x.name;});m.single=L.length===1;m.manual=true;return m;
}
/* ---------------- المشروع: حفظ، فتح، سجل ---------------- */
function loadScene(json){
  var d;try{d=typeof json==='string'?JSON.parse(json):json;}catch(e){toast('ملف المشروع تالف');return false;}
  P.layers=(d.layers&&d.layers.length)?d.layers:defLayers();P.active=d.active||'L0';
  P.layers.forEach(function(l){if(l.lw==null)l.lw=0.25;});
  P.defs=d.defs||{};P.mats=d.mats||{};P.mfgr=d.mfgr||{};P.cost=d.cost||{};P.nest=d.nest||{};P.lights=Array.isArray(d.lights)?d.lights:[];P.lightEff=+d.lightEff||0;P.cams=Array.isArray(d.cams)?d.cams:[];P.env=d.env||{};
  if(NV.CAD)NV.CAD.load(d.cad||[]);
  if(!E.ready){raw=(d.objects||[]).slice();NV.emit('scene');return true;}
  var keep=multi.map(function(o){return o.userData.id;}),keepCtx=ctx&&ctx.userData.id;
  tc.detach();objects.slice().forEach(function(o){root.remove(o);disposeObj(o);});objects=[];selected=null;multi=[];ctx=null;pp=null;
  var bad=0;(d.objects||[]).forEach(function(r){try{var o=build(r);root.add(o);objects.push(o);applyVis(o);}catch(e){bad++;}});
  lightsRebuild();applyLight();  /* V76: يعيد الخلفية أيضًا عند التراجع/الفتح (كانت تبقى خلفية الحالة السابقة) */
  moversDirty=true;if(keepCtx)ctx=E.byId(keepCtx);multi=keep.map(E.byId).filter(function(o){return o&&o.parent===container();});selected=multi[0]||null;syncSel();req();NV.emit('scene');NV.emit('ctx',ctx);
  if(bad)toast('تعذّر بناء '+bad+' عنصر من المشروع');
  return true;
}
/* V72: مهام قبل كل حفظ في السجل (مثل تحديث المجسمات المرتبطة بالرسم 2D) — داخل نفس خطوة التراجع */
var PRE=[];E.onPreCommit=function(f){PRE.push(f);};
E.commit=function(label){
  if(!P)return;
  PRE.forEach(function(f){try{f(label);}catch(e){try{console.error(e);}catch(x){}}});
  var snap=serScene();
  if(P.lock){var cur=NV.History.current();if(cur&&NV.PROD.designPart(cur.snap)!==NV.PROD.designPart(snap)){loadScene(cur.snap);toast('التصميم مقفل بعد الاعتماد — من «الطلب والإنتاج» افتح قفل التعديل أولًا (سيُطلب إصدار جديد واعتماده)');NV.emit('locked');return;}}
  if(NV.History.commit(label,snap)){P.dirty=true;if((P.lights||[]).some(function(L){return L.att;}))lightsRebuild();NV.emit('scene');saveSoon();if(P.link)pushLink();}
};
function projData(){var d=JSON.parse(serScene()),used={};function use(sc){Object.keys((sc&&sc.mats)||{}).forEach(function(k){var t=sc.mats[k].tex;if(t&&t.img&&P.assets&&P.assets[t.img])used[t.img]=P.assets[t.img];});}use(d);(P.versions||[]).forEach(function(v){use(v.scene);});
  var o={id:P.id,name:P.name,created:P.created,app:'NIVEEN Studio',fmt:1,ver:NV.version,scene:d,assets:used,thumb:P.thumb||''};
  if(P.link)o.link=P.link;if(P.versions&&P.versions.length)o.versions=P.versions;if(P.prod)o.prod=P.prod;if(P.lock)o.lock=true;if(P.scope)o.scope=P.scope;try{o.wf=E.wfStatus().k;}catch(e){}return o;}
function saveSoon(){
  if(!S.autosave){NV.emit('saved',{state:'dirty'});return;}
  clearTimeout(saveT);NV.emit('saved',{state:'pending'});saveT=setTimeout(function(){E.saveNow(true);},700);
}
E.saveNow=function(auto){
  if(!P)return Promise.resolve();
  clearTimeout(saveT);
  if(!auto||!P.thumb||Date.now()-(P.thumbT||0)>60000){try{var t=E.shot('image/jpeg',1,220);if(t){P.thumb=t;P.thumbT=Date.now();}}catch(e){}}
  return NV.Store.put(projData()).then(function(){
    P.dirty=false;NV.Store.meta('current',P.id);NV.emit('saved',{state:'ok',t:Date.now(),mode:NV.Store.mode});
  },function(e){NV.emit('saved',{state:'err'});toast('تعذّر حفظ المشروع على هذا الجهاز — صدّر نسخة احتياطية JSON');});
};
E.project=function(){return P?{id:P.id,name:P.name,created:P.created,dirty:!!P.dirty}:null;};
function openData(d){
  P={id:d.id||NV.uid(),name:d.name||'مشروع',created:d.created||Date.now(),layers:defLayers(),active:'L0',defs:{},mats:{},lights:[],cams:[],env:{},assets:(d.assets&&typeof d.assets==='object')?d.assets:{},thumb:d.thumb||'',
    link:(d.link&&d.link.oid)?d.link:null,versions:Array.isArray(d.versions)?d.versions:[],prod:(d.prod&&Array.isArray(d.prod.stages))?d.prod:null,lock:!!d.lock,scope:(d.scope&&typeof d.scope==='object')?d.scope:null};
  if(E.ready)E.measClear();loadScene(d.scene||{objects:[]});
  NV.History.reset('فتح المشروع',serScene());
  NV.Store.meta('current',P.id);
  if(E.ready){E.view3('persp');if(S.layout==='2d'||S.layout==='split')E.view2(view2);}
  NV.emit('project',E.project());
}
E.newProject=function(name){
  if(P&&S.autosave)E.saveNow(true);
  openData({id:NV.uid(),name:name||'مشروع جديد',created:Date.now(),scene:{objects:[]}});
  E.saveNow(true);
};
E.openProject=function(id){
  return NV.Store.get(id).then(function(d){
    if(!d){toast('المشروع غير موجود');return;}
    if(P&&P.id!==id&&S.autosave)E.saveNow(true);
    openData(d);toast('فُتح المشروع «'+d.name+'»');
  });
};
E.saveAs=function(name){
  var d=projData();d.id=NV.uid();d.name=name||(P.name+' - نسخة');d.created=Date.now();
  openData(d);return E.saveNow(false).then(function(){toast('حُفظ باسم «'+d.name+'»');});
};
E.rename=function(name){if(!P||!name)return;P.name=name;NV.emit('project',E.project());E.saveNow(true);};
E.delProject=function(id){
  if(P&&id===P.id){toast('لا يمكن حذف المشروع المفتوح — افتح مشروعًا آخر أولًا');return Promise.resolve(false);}
  return NV.Store.del(id).then(function(){return true;});
};
E.exportJSON=function(){return JSON.stringify(projData(),null,1);};
E.importJSON=function(text){
  var d;try{d=JSON.parse(text);}catch(e){toast('الملف ليس JSON صالحًا');return false;}
  if(!d||!d.scene||!Array.isArray(d.scene.objects)){toast('هذا الملف ليس مشروع استوديو NIVEEN');return false;}
  if(!E.project()){toast('انتظر حتى يجهز الاستوديو');return false;}
  d.id=NV.uid();d.name=(d.name||'مشروع مستورد');d.created=Date.now();
  if(P&&S.autosave)E.saveNow(true);
  openData(d);E.saveNow(false);toast('استُورد المشروع «'+d.name+'» ('+d.scene.objects.length+' مجسم، '+((d.scene.cad||[]).length)+' عنصر رسم)');return true;
};
function lockBlocks(st){if(!P||!P.lock||!st)return false;var cur=serScene();if(NV.PROD.designPart(cur)!==NV.PROD.designPart(st.snap)){toast('التصميم مقفل بعد الاعتماد — لا يمكن التراجع إلى تصميم مختلف');return true;}return false;}
E.undo=function(){if(P&&P.lock){var h=NV.History.list(),c=h.filter(function(x){return x.cur;})[0];if(c&&c.i>0){var pv=NV.History.undo();if(lockBlocks(pv)){NV.History.redo();return;}NV.History.redo();}}var st=NV.History.undo();if(!st){toast('لا يوجد ما يُتراجع عنه');return;}loadScene(st.snap);P.dirty=true;saveSoon();};
E.redo=function(){if(P&&P.lock){var nx=NV.History.redo();if(nx){var bad=lockBlocks(nx);NV.History.undo();if(bad)return;}}var st=NV.History.redo();if(!st){toast('لا يوجد ما يُعاد');return;}loadScene(st.snap);P.dirty=true;saveSoon();};
E.jump=function(i){if(P&&P.lock){var h=NV.History.list(),ci=(h.filter(function(x){return x.cur;})[0]||{}).i,tg=NV.History.jump(i);var bad=lockBlocks(tg);NV.History.jump(ci);if(bad)return;}var st=NV.History.jump(i);if(st){loadScene(st.snap);P.dirty=true;saveSoon();}};

/* ================= V12: الربط بالطلب، الإصدارات والاعتماد، متابعة الإنتاج =================
   كلها على مستوى المشروع خارج سجل التراجع: التراجع لا يمحو اعتمادًا ولا تسجيل إنتاج.
   الإصدار = لقطة كاملة من المشهد + بصمة التصميم + ملخص. الاعتماد يطابق المشروع مع الإصدار ثم يقفل التصميم.
   الإنتاج يتبع الإصدار المعتمد فقط، وقطعه تُبنى من لقطة الإصدار نفسها (NV.PROD.parts) لا من المشهد الحالي. */
var PR=NV.PROD;
function who(){var b=window.NVBridge;try{return (b&&b.user&&b.user())||'';}catch(e){return '';}}
function curScene(){return JSON.parse(serScene());}
function verBy(n){return P?(P.versions||[]).filter(function(v){return v.n===n;})[0]||null:null;}
function apprVer(){return P?(P.versions||[]).filter(function(v){return v.st==='approved';})[0]||null:null;}
function persist(){if(!P)return Promise.resolve();P.dirty=true;return E.saveNow(true);}
function prodStarted(){return !!(P&&P.prod&&Object.keys(P.prod.parts).some(function(k){return P.prod.parts[k].s>0;}));}
var prodCache={k:'',L:null};
function prodList(){
  var v=P&&P.prod?verBy(P.prod.ver):null;if(!v)return null;var k=P.id+':'+v.n+':'+v.hash;
  if(prodCache.k!==k){var L=null;try{L=PR.flat(PR.parts(v.scene,NVM,MFG));}catch(e){L=null;}prodCache={k:k,L:L};}
  return prodCache.L;
}
/* --- الربط بالطلب --- */
var plT=0;
/* V25: بصمة التصميم (القطع والخامات والقواعد والرسومات + الإضاءة) — لمعرفة أن اختيارات العميل المحفوظة ما زالت مطابقة */
E.designHash=function(){if(!P)return '';try{return NV.ROOM.hashOf({d:NV.PROD.designPart(serScene()),l:P.lights||[]});}catch(e){return '';}};
function linkRec(){
  var a=apprVer(),last=(P.versions||[]).slice(-1)[0],pg=null,st=null;
  if(P.prod){try{st=E.prodState();pg=st?st.prog.pct:null;}catch(e){}}
  var w=E.wfStatus();
  return {pid:P.id,pname:P.name,ver:last?last.n:0,vst:last?last.st:'',appr:a?{n:a.n,t:a.at||a.t,by:a.aby||''}:null,lock:!!P.lock,prod:pg,wf:w.k,wfn:w.n,iname:P.link&&P.link.iname||'',dh:E.designHash(),t:Date.now()};
}
function bridgeLink(oid,rec,ik){var b=window.NVBridge;if(!b)return false;try{if(ik){return b.itemSet?b.itemSet(oid,ik,rec):false;}return b.linkSet?b.linkSet(oid,rec):false;}catch(e){return false;}}
function pushLink(now){if(!P||!P.link)return;clearTimeout(plT);var f=function(){if(P&&P.link)bridgeLink(P.link.oid,linkRec(),P.link.ik);};if(now)f();else plT=setTimeout(f,400);}
E.link=function(){return P&&P.link?JSON.parse(JSON.stringify(P.link)):null;};
E.linkOrder=function(){var b=window.NVBridge;if(!P||!P.link||!b||!b.orderGet)return null;try{return b.orderGet(P.link.oid);}catch(e){return null;}};
E.setLink=function(o){
  if(!P)return false;var old=P.link;
  if(o){if(!o.oid){toast('اختر طلبًا');return false;}P.link={oid:o.oid,no:String(o.no||''),cust:String(o.cust||''),t:Date.now()};if(o.ik){P.link.ik=String(o.ik);P.link.iname=String(o.iname||'');}}
  else P.link=null;
  if(old&&(!P.link||old.oid!==P.link.oid||(old.ik||'')!==(P.link.ik||'')))bridgeLink(old.oid,null,old.ik);
  pushLink(true);NV.emit('link',E.link());persist();return true;
};
/* V19: مشروع لكل بند من مراجعة النطاق */
E.findByItem=function(oid,ik){return NV.Store.list().then(function(a){return a.filter(function(p){return p.link&&p.link.oid===oid&&p.link.ik===ik;});});};
E.setScope=function(rec){if(!P)return false;P.scope=rec?JSON.parse(JSON.stringify(rec)):null;NV.emit('scope',P.scope);persist();return true;};
E.scope=function(){return P&&P.scope?JSON.parse(JSON.stringify(P.scope)):null;};
E.markBase=function(){if(!P||!P.scope)return false;P.scope.base=PR.hash(serScene());persist();return true;};
E.wfStatus=function(){
  if(!P)return {k:'wait',n:PR.WF.wait};var sc=JSON.parse(serScene());
  var k=PR.wf({empty:!(sc.objects||[]).length&&!(sc.cad||[]).length,versions:P.versions||[],cur:PR.hash(sc),lock:!!P.lock,base:P.scope&&P.scope.base});
  return {k:k,n:PR.WF[k]};
};
E.findByOrder=function(oid){return NV.Store.list().then(function(a){return a.filter(function(p){return p.link&&p.link.oid===oid;});});};
/* --- الإصدارات --- */
E.versions=function(){
  return P?(P.versions||[]).map(function(v){return {n:v.n,t:v.t,by:v.by||'',note:v.note||'',st:v.st,stn:PR.VST[v.st]||v.st,hash:v.hash,thumb:v.thumb||'',sum:v.sum,at:v.at||0,aby:v.aby||'',snote:v.snote||'',stt:v.stt||0,sby:v.sby||''};}):[];
};
/* V41: لقطة تكلفة الإصدار عند اعتماده للتصنيع — أسعار يوم الاعتماد تبقى ثابتة للمقارنة */
function costSnap(R){
  return {t:Date.now(),inc:R.incomplete||0,sums:JSON.parse(JSON.stringify(R.sums)),
    lines:R.lines.filter(function(l){return l.status==='ok';}).map(function(l){return {k:l.key,n:l.name,m:l.matLabel||'',q:l.qty,u:l.matUnit||'',p:l.price,tt:l.total};})};
}
E.apprCost=function(){var a=apprVer();return a?{n:a.n,at:a.at||0,cost:a.cost||null}:null;};
E.freezeCost=function(){var a=apprVer();if(!a)return false;var R=E.cost(true);if(!R||!R.bridge)return false;a.cost=costSnap(R);a.cost.late=1;NV.emit('versions');persist();return true;};
E.verState=function(){
  if(!P)return null;var a=apprVer(),h=PR.hash(serScene()),last=(P.versions||[]).slice(-1)[0];
  return {approved:a?a.n:null,changed:a?a.hash!==h:false,sinceLast:last?last.hash!==h:true,locked:!!P.lock,count:(P.versions||[]).length,last:last?last.n:0,lastSt:last?last.st:'',prod:!!P.prod,prodStarted:prodStarted()};
};
E.verSave=function(note){
  if(!P)return null;var sc=curScene(),h=PR.hash(sc),last=(P.versions||[]).slice(-1)[0];
  if(last&&last.hash===h){toast('لا تغييرات في التصميم منذ الإصدار '+last.n);return null;}
  if(!sc.objects.length&&!(sc.cad||[]).length){toast('المشروع فارغ — لا يوجد ما يُحفظ كإصدار');return null;}
  var n=last?last.n+1:1,th='',sum;
  try{if(E.ready)th=E.shot('image/jpeg',1,220)||'';}catch(e){}
  try{sum=PR.summary(sc,NVM,MFG);}catch(e){toast('تعذّر تلخيص الإصدار: '+(e&&e.message||e));return null;}
  P.versions=(P.versions||[]).concat([{n:n,t:Date.now(),by:who(),note:String(note||'').slice(0,300),st:'draft',hash:h,scene:sc,thumb:th,sum:sum}]);
  NV.emit('versions');pushLink(true);persist();return n;
};
E.verStatus=function(n,st,o){
  o=o||{};if(!P)return false;var v=verBy(n);if(!v){toast('الإصدار غير موجود');return false;}
  if(!PR.VST[st]||st==='superseded'){toast('حالة غير صالحة');return false;}
  if(v.st===st&&!o.note)return true;
  /* V19: الاعتماد للتصنيع (الهندسي) منفصل عن اعتماد العميل: يلزم اعتماد العميل أولًا أو سبب داخلي مكتوب */
  if(st==='approved'&&v.st!=='capproved'&&v.st!=='superseded'&&!(o.internal&&String(o.internal).trim())){toast('اعتماد العميل للإصدار '+n+' مطلوب قبل الاعتماد للتصنيع');return {err:'need-capp'};}
  if(st==='capproved'){v.capp={t:Date.now(),by:who(),note:String(o.note||'').slice(0,300)};}
  if(st==='approved'&&o.internal)v.internal=String(o.internal).slice(0,300);
  if(st==='approved'&&o.checks)v.checks=o.checks;
  if(v.st==='superseded'&&st!=='approved'){toast('إصدار مستبدل — لا تتغير حالته إلا باعتماده من جديد');return false;}
  var res={ok:true};
  if(v.st==='approved'&&st!=='approved'){
    if(P.prod&&P.prod.ver===n&&prodStarted()){toast('بدأ الإنتاج على هذا الإصدار — لا يمكن إلغاء اعتماده');return false;}
    if(P.prod&&P.prod.ver===n)P.prod=null;
    P.lock=false;
  }
  if(st==='approved'&&v.st!=='approved'){
    var a=apprVer();
    if(a&&P.prod&&P.prod.ver===a.n&&prodStarted()&&!o.rebase)return {need:'rebase',from:a.n};
    if(P.prod&&P.prod.ver!==n){
      var ov=verBy(P.prod.ver),oldL=ov?PR.flat(PR.parts(ov.scene,NVM,MFG)):[],newL=PR.flat(PR.parts(v.scene,NVM,MFG));
      var rb=PR.rebase(P.prod,oldL,newL,n);P.prod=rb.prod;res.kept=rb.kept;res.reset=rb.reset;
    }
    if(a)a.st='superseded';
    if(PR.hash(serScene())!==v.hash){P.lock=false;loadScene(JSON.parse(JSON.stringify(v.scene)));E.commit('مطابقة المشروع مع الإصدار '+n+' عند اعتماده');}
    v.at=Date.now();v.aby=who();P.lock=true;
    try{var CR=E.cost(true);if(CR&&CR.bridge)v.cost=costSnap(CR);}catch(e){}
  }
  v.st=st;v.stt=Date.now();v.sby=who();if(o.note!=null)v.snote=String(o.note).slice(0,300);
  NV.emit('versions');NV.emit('prod');pushLink(true);persist();return res;
};
E.verRestore=function(n){
  if(!P)return false;var v=verBy(n);if(!v){toast('الإصدار غير موجود');return false;}
  if(P.lock){toast('التصميم مقفل بعد الاعتماد — افتح القفل أولًا');return false;}
  loadScene(JSON.parse(JSON.stringify(v.scene)));E.commit('استعادة الإصدار '+n);return true;
};
E.verDel=function(n){
  if(!P)return false;var v=verBy(n);if(!v)return false;
  if(v.st==='approved'||v.st==='superseded'||(P.prod&&(P.prod.ver===n||P.prod.prev===n))){toast('لا يُحذف إصدار معتمد أو مرتبط بالإنتاج — يبقى في السجل');return false;}
  P.versions=P.versions.filter(function(x){return x.n!==n;});NV.emit('versions');pushLink(true);persist();return true;
};
E.verScene=function(n){var v=verBy(n);return v?JSON.parse(JSON.stringify(v.scene)):null;};
E.verCompare=function(a,b){
  var va=verBy(a),sb;if(!va)return null;
  if(b==='cur'){try{sb=PR.summary(curScene(),NVM,MFG);}catch(e){return null;}}else{var vb=verBy(b);if(!vb)return null;sb=vb.sum;}
  return PR.diff(va.sum,sb);
};
E.unlock=function(){if(!P||!P.lock)return false;P.lock=false;NV.emit('versions');pushLink(true);persist();return true;};
E.relock=function(){
  if(!P)return false;var a=apprVer();if(!a){toast('لا يوجد إصدار معتمد');return false;}
  if(a.hash!==PR.hash(serScene())){toast('التصميم الحالي يختلف عن الإصدار المعتمد '+a.n+' — احفظ إصدارًا جديدًا واعتمده، أو استعد الإصدار المعتمد');return false;}
  P.lock=true;NV.emit('versions');pushLink(true);persist();return true;
};
/* --- الإنتاج --- */
