function mk(t,o,dim){o.t=t;o.id=NV.uid();if(!o.layer)o.layer=curLayer(dim);return o;}
function addE(arr){(Array.isArray(arr)?arr:[arr]).forEach(function(e){if(!e.id)e.id=NV.uid();if(!e.layer)e.layer=curLayer(e.t==='dim');ents.push(e);});req();}
