function rnd(o){return JSON.parse(JSON.stringify(o,function(k,v){return typeof v==='number'?rr(v):v;}));}
CAD.ser=function(){return ents.map(rnd);};
CAD.load=function(a){ents=Array.isArray(a)?JSON.parse(JSON.stringify(a)):[];sel=sel.filter(function(id){return !!byId(id);});if(tool&&tool.st&&tool.st.ent&&!byId(tool.st.ent.id))endTool();req();NV.emit('cadsel');};
