  for(var i=0;i<m;i++){var a=P.pts[i],b=P.pts[(i+1)%n],r=segClosest(p,a,b),d=dist(p,r.p);if(d<best){best=d;bt=cum[i]+r.t*(cum[i+1]-cum[i]);}}
  return bt;
