  if(w==='pt'){cursor=resolve(raw,e.pointerType!=='mouse');}
  else{cursor=raw;snapHit=null;}
  NV.emit('cadcoords',{x:cursor[0],y:cursor[1]});
  if(e.pointerType==='mouse'&&w!=='pt'){var h=pickAt(raw,false);hoverId=h?h.id:null;}else hoverId=null;
  if(tool&&tool.n==='win'&&tool.st.pts.length)tool.d.preview(tool.st,cursor);
