CAD.bboxAll=function(){var b=[Infinity,Infinity,-Infinity,-Infinity];ents.forEach(function(e){if(!visibleE(e))return;var q=bbox(e);b[0]=Math.min(b[0],q[0]);b[1]=Math.min(b[1],q[1]);b[2]=Math.max(b[2],q[2]);b[3]=Math.max(b[3],q[3]);});return isFinite(b[0])?b:null;};
