function LA(){return hasL('L2')?'L2':G.curLayer();}
function LD(){return S.cadDimLayer&&hasL('L3')?'L3':G.curLayer();}
function rect(x0,y0,x1,y1,o){if(Math.abs(x1-x0)<1e-6||Math.abs(y1-y0)<1e-6)return null;var r={t:'pline',pts:[[x0,y0],[x1,y0],[x1,y1],[x0,y1]],closed:true};for(var q in o)r[q]=o[q];return r;}
