function dim(kk,a,b,p){return {t:'dim',k:kk,a:a,b:b,p:p,h:G.dimH(),layer:LD()};}
function txt(p,s,h,o){var r={t:'text',p:p,s:s,h:h,rot:0};for(var q in o)r[q]=o[q];return r;}
function origin(){var b=CAD.bboxAll();return b?[b[2]+0.8,b[1]+0.6]:[0,0];}
