/* -------- واجهة أمامية من المواصفات البارامترية -------- */
function elevation(spec,o,opt){
  opt=opt||{};var r=NVM.gen(spec),P=r.panels,W=r.dims.W*k,out=[],ox=o[0],oy=o[1],bed=spec.kind==='bed',cab=spec.kind==='cab';
  /* V70: «بدون الأبواب» — تُحذف الأبواب والقلابات وأبواب السحاب (لا واجهات الأدراج) فيظهر التقسيم الداخلي */
  if(opt.noDoors){var DG={};r.groups.forEach(function(g){if(g.k==='door'||g.k==='sdoor'||g.k==='flap'||g.k==='lift')DG[g.id]=1;});
    P=P.filter(function(p){if(p.grp&&DG[p.grp])return false;if(cab&&/^front:/.test(p.src||'')&&!p.grp)return false;return true;});}
  var X=function(x){return ox+x*k+W/2;},Y=function(y){return oy+y*k;};
  var R=function(p){return [X(p.cx-p.sx/2),Y(p.cy-p.sy/2),X(p.cx+p.sx/2),Y(p.cy+p.sy/2)];};
  var fronts=P.filter(function(p){return p.role==='front';});
  var covered=function(p){return fronts.some(function(f){return Math.abs(p.cx-f.cx)<f.sx/2&&Math.abs(p.cy-f.cy)<f.sy/2;});};
  P.forEach(function(p){
    var q=R(p);
    if(p.role==='back')return;
    if(p.role==='body'){push(out,rect(q[0],q[1],q[2],q[3],{layer:LF(),lw:0.35}));return;}
    if(p.role==='front'){push(out,rect(q[0],q[1],q[2],q[3],{layer:LF(),lw:0.35}));return;}
    if(p.role==='mattress'){push(out,rect(q[0],q[1],q[2],q[3],{layer:LA(),lt:'dash'}));return;}
    if(p.role==='glass'){push(out,rect(q[0],q[1],q[2],q[3],{layer:LF()}));var w=q[2]-q[0],h=q[3]-q[1];out.push(line([q[0]+w*0.2,q[3]-h*0.15],[q[0]+w*0.35,q[3]-h*0.3],{layer:LA()}),line([q[0]+w*0.25,q[3]-h*0.3],[q[0]+w*0.45,q[3]-h*0.5],{layer:LA()}));return;}
    if(p.role==='fixed'){if(p.grp||!covered(p))push(out,rect(q[0],q[1],q[2],q[3],{layer:LF(),lw:0.18}));return;}
    if(p.role==='inner'){if(p.grp)return;if(!covered(p))push(out,rect(q[0],q[1],q[2],q[3],{layer:LF(),lw:0.25}));else if(S.cadGenHidden)push(out,rect(q[0],q[1],q[2],q[3],{layer:LA(),lt:'hidden',lw:0.13}));}
    if(p.role==='fabric'||p.role==='top'||p.role==='appliance'){push(out,rect(q[0],q[1],q[2],q[3],{layer:p.role==='appliance'?LA():LF(),lw:p.role==='appliance'?0.13:0.3}));}
  });
  var Hc=(bed||cab||spec.kind==='kitchen')?r.dims.H*k:(spec.H*k),off=G.dimH()*3; /* V70: التصميم الحر بالملم — الارتفاع من القطع المولدة */
  var divs=P.filter(function(p){return p.name==='فاصل';}).map(function(p){return X(p.cx);}).sort(function(a,b){return a-b;});
  if(divs.length){var bnd=[ox].concat(divs,[ox+W]);for(var i=0;i<bnd.length-1;i++)out.push(dim('h',[bnd[i],oy],[bnd[i+1],oy],[0,oy-off]));}
  out.push(dim('h',[ox,oy],[ox+W,oy],[0,oy-off*(divs.length?2:1)]));
  out.push(dim('v',[ox,oy],[ox,oy+Hc],[ox-off,0]));
  if(!bed&&!cab&&spec.ph>0)out.push(dim('v',[ox+W,oy],[ox+W,oy+spec.ph*k],[ox+W+off,0]));
  if(cab&&spec.base&&spec.base.h>0)out.push(dim('v',[ox+W,oy],[ox+W,oy+spec.base.h/10*k],[ox+W+off,0]));
  if(bed)out.push(dim('v',[ox+W,oy],[ox+W,oy+spec.fh*k],[ox+W+off,0]));
  out.push(txt([ox,oy-off*(divs.length?3:2)-G.dimH()*1.5],(spec.name||NVM.KINDS[spec.kind])+(opt.noDoors?' — التقسيم الداخلي (بدون الأبواب)':' — واجهة أمامية'),G.dimH()*1.6,{layer:LD()}));
  return out;
}
/* -------- قطاع جانبي عند منتصف وحدة -------- */
function section(spec,o,mi){
  var r=NVM.gen(spec),P=r.panels,D=r.dims.D*k,H=r.dims.H*k,out=[],ox=o[0],oy=o[1],bed=spec.kind==='bed',Wc=r.dims.W;
  var Z=function(z){return ox+z*k+D/2;},Y=function(y){return oy+y*k;},cut;
  if(bed){cut=null;}
  else{
    var divs=P.filter(function(p){return p.name==='فاصل';}).map(function(p){return p.cx;}).sort(function(a,b){return a-b;});
    var bnd=[-Wc/2].concat(divs,[Wc/2]);mi=Math.max(0,Math.min(bnd.length-2,mi||0));cut=(bnd[mi]+bnd[mi+1])/2;
  }
  var hor=[];
  P.forEach(function(p){
    var inCut=cut==null||Math.abs(p.cx-cut)<=p.sx/2+1e-6;if(!inCut)return;
    if(p.role==='glass'||p.role==='fixed'&&p.shape==='cyl'){}
    var q=[Z(p.cz-p.sz/2),Y(p.cy-p.sy/2),Z(p.cz+p.sz/2),Y(p.cy+p.sy/2)];
    var ly=p.role==='mattress'?LA():LF(),lt=p.role==='mattress'?'dash':null,lw=(p.role==='body'||p.role==='inner'||p.role==='front'||p.role==='back')?0.5:0.25;
    var e=rect(q[0],q[1],q[2],q[3],{layer:ly,lw:lw});if(e){if(lt)e.lt=lt;out.push(e);}
    if(!bed&&p.sy<=3.1&&p.sz>10&&p.role!=='front')hor.push(Y(p.cy+p.sy/2));
  });
  if(!bed){var side=P.filter(function(p){return p.name==='جنب أيمن';})[0];if(side)push(out,rect(Z(side.cz-side.sz/2),Y(0),Z(side.cz+side.sz/2),Y(side.cy+side.sy/2),{layer:LA(),lw:0.13}));}
  var off=G.dimH()*3;
  out.push(dim('h',[ox,oy],[ox+D,oy],[0,oy-off]));
  out.push(dim('v',[ox,oy],[ox,oy+H],[ox-off,0]));
  hor.sort(function(a,b){return a-b;});var lv=[oy];hor.forEach(function(y){if(y-lv[lv.length-1]>0.005)lv.push(y);});
  for(var i=0;i<lv.length-1;i++)out.push(dim('v',[ox+D,lv[i]],[ox+D,lv[i+1]],[ox+D+off,0]));
  out.push(txt([ox,oy-off*2-G.dimH()*1.5],(spec.name||NVM.KINDS[spec.kind])+(bed?' — منظر جانبي':' — قطاع جانبي (الوحدة '+((mi||0)+1)+')'),G.dimH()*1.6,{layer:LD()}));
  return out;
}
/* -------- مخطط مطبخ (مسقط أفقي) -------- */
function kitchen(o,f){
  var A=f.A,B=f.B,d=f.d,wt=f.wt,uw=f.uw,out=[],ox=o[0],oy=o[1],LF2=LF();
  var P=function(x,y){return [ox+x,oy+y];};
  out.push({t:'pline',pts:[P(-wt,d),P(A,d),P(A,d+wt),P(-wt,d+wt)],closed:true,layer:LA(),lw:0.5});
  if(B>0)out.push({t:'pline',pts:[P(-wt,d),P(0,d),P(0,d-B),P(-wt,d-B)],closed:true,layer:LA(),lw:0.5});
  out.push({t:'pline',pts:B>0?[P(0,d),P(A,d),P(A,0),P(d,0),P(d,d-B),P(0,d-B)]:[P(0,d),P(A,d),P(A,0),P(0,0)],closed:true,layer:LF2,lw:0.35});
  var x0=B>0?d:0;for(var x=x0+uw;x<A-0.05;x+=uw)out.push(line(P(x,0),P(x,d),{layer:LF2}));
  if(B>0){out.push(line(P(0,0),P(d,0),{layer:LF2}));for(var y=-uw;y>-(B-d)+0.05;y-=uw)out.push(line(P(0,y),P(d,y),{layer:LF2}));}
  if(f.upper){var ud=0.35;out.push({t:'pline',pts:[P(B>0?0:0,d),P(A,d),P(A,d-ud),P(0,d-ud)],closed:true,layer:LA(),lt:'dash',lw:0.18});if(B>0)out.push({t:'pline',pts:[P(0,d),P(ud,d),P(ud,d-B),P(0,d-B)],closed:true,layer:LA(),lt:'dash',lw:0.18});}
  var sx=f.sink>0?f.sink:Math.max(x0+0.45,A*0.5);
  out.push({t:'pline',pts:[P(sx-0.4,d-0.05),P(sx+0.4,d-0.05),P(sx+0.4,d-0.5),P(sx-0.4,d-0.5)],closed:true,layer:LF2});
  out.push({t:'circle',c:P(sx,d-0.27),r:0.025,layer:LF2});
  var hx=B>0?null:Math.min(A-0.35,sx+1.1),hb=B>0?[d/2,(d-B)/2+0.1]:null;
  var hc=hb?P(hb[0],hb[1]):P(hx,d-0.3);
  if(hc){out.push({t:'pline',pts:[[hc[0]-0.29,hc[1]-0.26],[hc[0]+0.29,hc[1]-0.26],[hc[0]+0.29,hc[1]+0.26],[hc[0]-0.29,hc[1]+0.26]],closed:true,layer:LF2});
    [[-0.13,-0.11],[0.13,-0.11],[-0.13,0.11],[0.13,0.11]].forEach(function(q){out.push({t:'circle',c:[hc[0]+q[0],hc[1]+q[1]],r:q[0]<0?0.07:0.055,layer:LF2});});}
  var off=G.dimH()*3;
  out.push(dim('h',P(0,d+wt),P(A,d+wt),[0,oy+d+wt+off]));
  out.push(dim('v',P(A,0),P(A,d),[ox+A+off,0]));
  if(B>0)out.push(dim('v',P(-wt,d),P(-wt,d-B),[ox-wt-off,0]));
  var cuts=[x0];for(var x2=x0+uw;x2<A-0.05;x2+=uw)cuts.push(x2);cuts.push(A);if(B>0)cuts.unshift(0);
  for(var i=0;i<cuts.length-1;i++)out.push(dim('h',P(cuts[i],0),P(cuts[i+1],0),[0,oy-off]));
  out.push(txt(P(0,-off*2-G.dimH()*1.5),'مخطط مطبخ — '+(B>0?'شكل L':'خط مستقيم'),G.dimH()*1.6,{layer:LD()}));
  return out;
}
/* -------- غرفة بأبعاد حقيقية مع باب ونافذة -------- */
function room(o,f){
  var L=f.L,Wd=f.W,t=f.t,out=[],ox=o[0],oy=o[1];
  var sides={b:{S:[0,0],u:[1,0],n:[0,1],len:L},r:{S:[L,0],u:[0,1],n:[-1,0],len:Wd},t:{S:[L,Wd],u:[-1,0],n:[0,-1],len:L},l:{S:[0,Wd],u:[0,-1],n:[1,0],len:Wd}};
  var ops={b:[],r:[],t:[],l:[]};
  if(f.dw>0)ops[f.dside].push({o:f.doff,w:f.dw,k:'door'});
  if(f.ww>0)ops[f.wside].push({o:f.woff,w:f.ww,k:'win'});
  var bad='';
  Object.keys(sides).forEach(function(key){
    var s=sides[key],S0=G.add([ox,oy],s.S),pt=function(a,dn){return G.add(G.add(S0,G.mul(s.u,a)),G.mul(s.n,dn));};
    var iv=ops[key].slice().sort(function(a,b){return a.o-b.o;});
    iv.forEach(function(q){if(q.o<0||q.o+q.w>s.len)bad='فتحة تتجاوز طول الجدار';});
    var segs=function(a0,a1,dn){var cur=a0,res=[];iv.forEach(function(q){if(q.o>cur)res.push([cur,Math.min(q.o,a1)]);cur=Math.max(cur,q.o+q.w);});if(cur<a1)res.push([cur,a1]);res.forEach(function(r){if(r[1]-r[0]>1e-6)out.push(line(pt(r[0],dn),pt(r[1],dn),{layer:LA(),lw:0.5}));});};
    segs(0,s.len,0);segs(-t,s.len+t,-t);
    iv.forEach(function(q){
      out.push(line(pt(q.o,0),pt(q.o,-t),{layer:LA(),lw:0.5}),line(pt(q.o+q.w,0),pt(q.o+q.w,-t),{layer:LA(),lw:0.5}));
      if(q.k==='door'){var hg=pt(q.o,0),leaf=G.add(hg,G.mul(s.n,q.w));out.push(line(hg,leaf,{layer:LF(),lw:0.35}));
        var au=Math.atan2(s.u[1],s.u[0]),an=Math.atan2(s.n[1],s.n[0]),c=G.crs(s.u,s.n)>0;out.push({t:'arc',c:hg,r:q.w,a0:G.na(c?au:an),a1:G.na(c?an:au),layer:LF(),lt:'dash',lw:0.18});}
      else{[t/3,2*t/3].forEach(function(dn){out.push(line(pt(q.o,-dn),pt(q.o+q.w,-dn),{layer:LF(),lw:0.18}));});}
    });
  });
  var off=G.dimH()*3;
  out.push(dim('h',[ox,oy],[ox+L,oy],[0,oy-t-off]));
  out.push(dim('v',[ox+L,oy],[ox+L,oy+Wd],[ox+L+t+off,0]));
  out.push(txt([ox,oy-t-off*2-G.dimH()*1.5],'غرفة '+U.to(L)+' × '+U.to(Wd)+' '+U.name()+' (أبعاد داخلية)',G.dimH()*1.6,{layer:LD()}));
  if(bad)toast(bad);
  return out;
}

/* -------- V75: المخططات المعمارية من غرفة المشروع نفسها (أي شكل): مسقط بالجدران والفتحات والأثاث والأبعاد + واجهة لكل جدار --------
   الغرفة بالملليمتر (x يمين، z للأمام) ← الرسم بالمتر (y للأعلى = عكس z). لا يغيّر الغرفة ولا الأثاث. */
function roomDwg(o,opt){
  var RM=NV.ROOM,sp=E.room();if(!sp)return null;opt=opt||{};
  var Gm=RM.geom(sp),b=RM.bounds(sp),t=sp.wt,its=E.roomItems(),A=RM.analyze(sp,its),out=[],h=Math.max(G.dimH(),Math.max(b.x1-b.x0,b.z1-b.z0)/1000/60),hm=h*1000,dim=function(k,a,c,q){var d={t:'dim',k:k,a:a,b:c,p:q,h:h,layer:LD()};return d;};  /* حجم النص والأبعاد يتبع حجم الغرفة حتى يُقرأ */
  var P=function(q){return [o[0]+(q[0]-b.x0+t)/1000,o[1]+(b.z1+t-q[1])/1000];};
  var tc=function(c,s,hh,ly){var w=String(s).length*hh*0.55;return txt([c[0]-w/2,c[1]-hh/2],s,hh,{layer:ly});};
  /* الجدران (الأجزاء بكامل الارتفاع = ما يقطعه المسقط) */
  Gm.boxes.forEach(function(q){if(q.role==='wall'&&q.cy-q.sy/2<1&&q.cy+q.sy/2>Gm.H-1)push(out,{t:'pline',pts:RM.foot({x:q.cx,z:q.cz,w:q.sx,d:q.sz,ry:q.ry}).map(P),closed:true,layer:LA(),lw:0.5});});
  sp.ops.forEach(function(q){var w=Gm.walls.filter(function(x){return x.i===q.wall;})[0];if(!w)return;
    var W=function(u,v){return P(RM.wpt(w,u,v));},a=q.off,e=q.off+q.w;
    out.push(line(W(a,0),W(a,-t),{layer:LA(),lw:0.5}),line(W(e,0),W(e,-t),{layer:LA(),lw:0.5}));
    if(q.k==='window'){[t/3,2*t/3].forEach(function(v){out.push(line(W(a,-v),W(e,-v),{layer:LF(),lw:0.18}));});out.push(line(W(a,0),W(e,0),{layer:LF(),lw:0.18}),line(W(a,-t),W(e,-t),{layer:LF(),lw:0.18}));}
    else if(q.k==='door'){var inn=q.swing==='in'?1:-1,hu=q.hinge==='R'?e:a,fu=q.hinge==='R'?a:e,hp=W(hu,0),tip=W(hu,inn*q.w),fp=W(fu,0);
      out.push(line(hp,tip,{layer:LF(),lw:0.35}));var ac=Math.atan2(fp[1]-hp[1],fp[0]-hp[0]),ao=Math.atan2(tip[1]-hp[1],tip[0]-hp[0]),d=G.na(ao-ac);
      out.push({t:'arc',c:hp,r:q.w/1000,a0:G.na(d<PI?ac:ao),a1:G.na(d<PI?ao:ac),layer:LF(),lt:'dash',lw:0.18});}});
  /* الأثاث: البصمة + خط الواجهة + الاسم */
  its.forEach(function(it){var F=RM.foot(it).map(P),c=P([it.x,it.z]);push(out,{t:'pline',pts:F,closed:true,layer:LF(),lw:0.35});out.push(line(F[2],F[3],{layer:LF(),lw:0.18,lt:'dash'}));
    if(opt.names!==false)out.push(tc(c,String(it.name).slice(0,24),Math.min(h*0.9,Math.min(it.w,it.d)/1000/3),LD()));});
  /* طول كل جدار من الداخل + رقمه */
  Gm.walls.forEach(function(w){out.push({t:'dim',k:'al',a:P(w.a),b:P(w.b),p:P(RM.wpt(w,w.len/2,-t-hm*2.5)),h:h,layer:LD()});out.push(tc(P(RM.wpt(w,w.len/2,-t-hm*5)),'ج'+(w.i+1),h*1.2,LD()));});
  var y0=o[1]-h*4;out.push(txt([o[0],y0],sp.name+' — مسقط · '+RM.areaM2(sp)+' م² · ارتفاع '+U.to(sp.H/1000)+' '+U.name(),h*1.6,{layer:LD()}));
  /* واجهات الجدران من الداخل: الجدار، الفتحات، والقطع الملاصقة له (≤ 150 مم) */
  var nE=0;if(opt.elev!==false){var x=o[0],yb=y0-h*8-sp.H/1000;
    Gm.walls.forEach(function(w){var L=w.len/1000,H=sp.H/1000,rt=[w.nin[1],-w.nin[0]],fl=w.dir[0]*rt[0]+w.dir[1]*rt[1]<0,X=function(u){return x+(fl?w.len-u:u)/1000;},Y=function(v){return yb+v/1000;};
      out.push(rect(x,yb,x+L,yb+H,{layer:LA(),lw:0.5}));
      sp.ops.filter(function(q){return q.wall===w.i;}).forEach(function(q){var s0=q.k==='window'?q.sill:0;push(out,rect(X(q.off),Y(s0),X(q.off+q.w),Y(Math.min(sp.H,s0+q.h)),{layer:LF(),lw:0.35}));
        if(q.k==='door'){var hx=q.hinge==='R'?q.off+q.w:q.off,fx=q.hinge==='R'?q.off:q.off+q.w;out.push(line([X(fx),Y(0)],[X(hx),Y(q.h/2)],{layer:LF(),lw:0.18,lt:'dash'}),line([X(hx),Y(q.h/2)],[X(fx),Y(q.h)],{layer:LF(),lw:0.18,lt:'dash'}));}});
      its.forEach(function(it){var r=A.items[it.id];if(!r||!r.near||r.near.wall!==w.i||r.near.d>150)return;var us=RM.foot(it).map(function(p){return (p[0]-w.a[0])*w.dir[0]+(p[1]-w.a[1])*w.dir[1];}),u0=Math.max(0,Math.min.apply(null,us)),u1=Math.min(w.len,Math.max.apply(null,us));
        if(u1-u0<1)return;var a0=Math.min(X(u0),X(u1)),a1=Math.max(X(u0),X(u1));push(out,rect(a0,Y(0),a1,Y(Math.min(sp.H,it.h)),{layer:LF(),lw:0.35}));
        if(opt.names!==false)out.push(tc([(a0+a1)/2,Y(it.h/2)],String(it.name).slice(0,24),Math.min(h*0.9,(a1-a0)/4),LD()));
        out.push(dim('h',[a0,Y(it.h)],[a1,Y(it.h)],[0,Y(it.h)+h*1.5]));});
      out.push(dim('h',[x,yb],[x+L,yb],[0,yb-h*2.5]),dim('v',[x+L,yb],[x+L,yb+H],[x+L+h*2.5,0]));
      out.push(txt([x,yb-h*5.5],'واجهة الجدار ج'+(w.i+1)+' (من الداخل)',h*1.3,{layer:LD()}));
      x+=L+h*10;nE++;});}
  return {ents:out,walls:Gm.walls.length,elev:nE,items:its.length};
}
CAD.roomDrawings=function(opt){if(!E.room()){toast('لا توجد غرفة في المشروع — أنشئها من قائمة «الغرف»');return null;}
  var r=roomDwg(origin(),opt);if(!r)return null;CAD.addEnts(r.ents,'مخططات الغرفة',true);toast('رُسم مسقط الغرفة'+(r.elev?' و'+r.elev+' واجهات جدران':'')+' — '+r.items+' قطعة أثاث');return r;};

