var KN={wardrobe:'دولاب',dresser:'تسريحة',tv:'طاولة تلفزيون',shoe:'جزامة',night:'كومدينو',bed:'سرير',desk:'مكتب',shelf:'مكتبة',kitchen:'وحدات مطبخ',sofa:'كنبة'};
