  obj(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+n3(pw)+' '+n3(ph)+'] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >>'+(nImg?' /XObject << '+xo+' >>':'')+' >> >>');
