function toPDF(es,o){
  var b=ext(es);if(!b)return {err:'لا يوجد ما يُصدَّر'};
  var pap=PAPER[o.paper]||PAPER.A4,land=o.orient==='land',PWmm=land?pap[1]:pap[0],PHmm=land?pap[0]:pap[1],mm=72/25.4,M=10,TB=o.title?24:0;
  var aw=PWmm-2*M,ah=PHmm-2*M-TB-4,dw=(b[2]-b[0])*1000,dh=(b[3]-b[1])*1000,N;
  var need=Math.max(dw/aw,dh/ah);
  if(o.scale==='fit'){N=SCALES.filter(function(s){return s>=need;})[0]||Math.ceil(need);}
  else{N=+o.scale;if(need>N+1e-9)return {err:'الرسم أكبر من الورقة بمقياس 1:'+N+' — جرّب 1:'+(SCALES.filter(function(s){return s>=need;})[0]||Math.ceil(need))+' أو ورقة أكبر'};}
  var kp=mm/N*1000,ox=(M+(aw-dw/N)/2)*mm,oy=(M+TB+4+(ah-dh/N)/2)*mm;
  var X=function(x){return n3(ox+(x-b[0])*kp);},Y=function(y){return n3(oy+(y-b[1])*kp);};
  var c=[],imgs=[],F=flat(es),lastCol='',lastLw=-1,lastDash='';
  function setS(p){var col=hexRGB(colOf(p.s,o.mono)).join(' '),lw=n3(Math.max(0.1,p.s.lw)*mm),da=DASH[p.s.lt]?'['+DASH[p.s.lt].map(function(v){return n3(v*mm*Math.max(1,p.s.lw*4));}).join(' ')+'] 0 d':'[] 0 d';
    if(col!==lastCol){c.push(col+' RG '+col+' rg');lastCol=col;}if(lw!==lastLw){c.push(lw+' w');lastLw=lw;}if(da!==lastDash){c.push(da);lastDash=da;}}
  c.push('1 J 1 j');
  F.forEach(function(p){
    if(p.k==='tx')return;setS(p);
    if(p.k==='pl'){c.push(p.pts.map(function(q,i){return X(q[0])+' '+Y(q[1])+(i?' l':' m');}).join(' ')+(p.cl?' h':'')+' S');}
    else if(p.k==='tri'){c.push(X(p.pts[0][0])+' '+Y(p.pts[0][1])+' m '+X(p.pts[1][0])+' '+Y(p.pts[1][1])+' l '+X(p.pts[2][0])+' '+Y(p.pts[2][1])+' l h f');}
    else if(p.k==='ci'||p.k==='ar'){var bz=p.k==='ci'?bezArc(p.c,p.r,0,2*PI):bezArc(p.c,p.r,p.a0,G.ccw(p.a0,p.a1));
      c.push(bz.map(function(s,i){return (i?'':X(s[0][0])+' '+Y(s[0][1])+' m ')+X(s[1][0])+' '+Y(s[1][1])+' '+X(s[2][0])+' '+Y(s[2][1])+' '+X(s[3][0])+' '+Y(s[3][1])+' c';}).join(' ')+(p.k==='ci'?' h':'')+' S');}
  });
  F.forEach(function(p){
    if(p.k!=='tx')return;
    var size=Math.max(3.5,p.h*kp),rot=p.rot||0,co=Math.cos(rot),si=Math.sin(rot),col=hexRGB(colOf(p.s,o.mono)).join(' '),x=+X(p.p[0]),y=+Y(p.p[1]);
    if(ascii(p.str)){var tw=p.str.length*size*0.52,dx=p.c?-tw/2:0;c.push('BT /F1 '+n3(size)+' Tf '+col+' rg '+n3(co)+' '+n3(si)+' '+n3(-si)+' '+n3(co)+' '+n3(x+dx*co)+' '+n3(y+dx*si)+' Tm '+pstr(p.str)+' Tj ET');}
    else{var im=textImage(p.str,size,o.mono?'#000':colOf(p.s,false)),id=imgs.length;imgs.push(im);var dx2=p.c?-im.wPt/2:0,bx=x+dx2*co+im.base*si,by=y+dx2*si-im.base*co;
      c.push('q '+n3(im.wPt*co)+' '+n3(im.wPt*si)+' '+n3(-im.hPt*si)+' '+n3(im.hPt*co)+' '+n3(bx)+' '+n3(by)+' cm /Im'+id+' Do Q');}
  });
  /* إطار وجدول عنوان */
  c.push('0 0 0 RG 0 0 0 rg 0.6 w [] 0 d');c.push(n3(M*mm)+' '+n3(M*mm)+' '+n3((PWmm-2*M)*mm)+' '+n3((PHmm-2*M)*mm)+' re S');
  if(o.title){
    var tx=(PWmm-M-110)*mm,ty=M*mm,tw2=110*mm,th2=TB*mm;c.push(n3(tx)+' '+n3(ty)+' '+n3(tw2)+' '+n3(th2)+' re S');
    c.push(n3(tx)+' '+n3(ty+th2/2)+' m '+n3(tx+tw2)+' '+n3(ty+th2/2)+' l S');c.push(n3(tx+tw2*0.62)+' '+n3(ty)+' m '+n3(tx+tw2*0.62)+' '+n3(ty+th2/2)+' l S');
    var info=['Scale 1:'+N,'Units: '+(S.units==='mm'?'mm':S.units==='cm'?'cm':'m'),new Date().toISOString().slice(0,10),'NIVEEN DESIGN STUDIO'];
    c.push('BT /F1 8 Tf '+n3(tx+tw2*0.64)+' '+n3(ty+3.5*mm)+' Td '+pstr(info[0]+'   '+info[2])+' Tj ET');
    c.push('BT /F1 7 Tf '+n3(tx+3*mm)+' '+n3(ty+3.5*mm)+' Td '+pstr(info[3]+' - '+info[1])+' Tj ET');
    var pn=(E.project&&E.project()?E.project().name:'')||'',ttl=o.ttl||'';
    [[pn,tx+tw2-3*mm,ty+th2*0.7,11],[ttl,tx+tw2-3*mm,ty+th2*0.53,8]].forEach(function(q){if(!q[0])return;
      if(ascii(q[0])){var w0=q[0].length*q[3]*0.52;c.push('BT /F1 '+q[3]+' Tf '+n3(q[1]-w0)+' '+n3(q[2])+' Td '+pstr(q[0])+' Tj ET');}
      else{var im2=textImage(q[0],q[3],'#000'),id2=imgs.length;imgs.push(im2);c.push('q '+n3(im2.wPt)+' 0 0 '+n3(im2.hPt)+' '+n3(q[1]-im2.wPt)+' '+n3(q[2]-im2.base)+' cm /Im'+id2+' Do Q');}});
  }
  return {bytes:buildPDF(PWmm*mm,PHmm*mm,c.join('\n'),imgs),N:N};
}

/* ======================= DXF R12 ======================= */
var ACI=[[1,[255,0,0]],[2,[255,255,0]],[3,[0,255,0]],[4,[0,255,255]],[5,[0,0,255]],[6,[255,0,255]],[7,[255,255,255]],[8,[128,128,128]],[9,[192,192,192]],[30,[255,127,0]],[40,[255,191,0]],[52,[204,153,0]],[34,[153,76,0]],[150,[0,127,255]],[110,[0,255,127]]];
