      cur.vis=true;if(cur.nb)cur.nb.vis=true;
      if(cur.entry){do{cur=cur.next;poly.push([cur.x,cur.y]);}while(!cur.inter);}
      else{do{cur=cur.prev;poly.push([cur.x,cur.y]);}while(!cur.inter);}
