/* ---------- شريط الحالة ---------- */
var lkT=0;
function statLink(){
  clearTimeout(lkT);lkT=setTimeout(function(){
    var b=$('#nvsLink');if(!b||!E.project())return;var l=E.link(),s=E.verState();
    var t=l?('📋 '+(l.no||'طلب')+(l.iname?' · '+l.iname:'')):'📋 بلا طلب';try{var w=E.wfStatus();t+=' · '+w.n;}catch(e){}
    if(s&&s.count){t+=' · إ'+s.last;if(s.approved)t+=' ✓'+s.approved;if(s.locked)t+=' 🔒';else if(s.changed)t+=' ⚠';}
    var st=E.prodState&&E.prodState();if(st)t+=' · '+st.prog.pct+'%';
    b.textContent=t;b.classList.toggle('warn',!!(s&&s.changed&&!s.locked));
    b.title=(l?'مرتبط بالطلب '+l.no+' — '+l.cust:'غير مرتبط بطلب')+(s&&s.approved?' · الإصدار المعتمد '+s.approved+(s.locked?' (مقفل)':s.changed?' (التصميم الحالي يختلف عنه)':''):'');
  },120);
}
['project','versions','link','prod','scene','locked'].forEach(function(ev){NV.on(ev,statLink);});

/* ---------- الربط بطلب ---------- */
function linkDlg(){
  var b=br(),l=E.link();
  if(!b||!b.orders){pop('ربط المشروع بطلب','<div class="nvs-warn bad">الاستوديو يعمل خارج تطبيق الطلبات — الربط غير متاح هنا.</div>');return;}
  var cur='';
  if(l){var o=E.linkOrder();
    cur=o?'<div class="nvs-card"><b>'+esc(o.no)+'</b> — '+esc(o.cust)+'<br><small>التسليم: '+esc(o.delivery||'—')+' · المرحلة: '+esc(o.status)+' · الاعتماد: '+esc(o.approval)+'</small>'+
      (o.lines.length?'<ul class="nvs-ol">'+o.lines.map(function(x){return '<li>'+esc(x.name||x.code)+(x.qty?' × '+x.qty:'')+'</li>';}).join('')+'</ul>':'')+
      '<div class="nvs-acts"><button type="button" class="nvs-btn" data-m12="unlink">فك الربط</button></div></div>'
      :'<div class="nvs-warn bad">الطلب المرتبط ('+esc(l.no)+') لم يعد موجودًا في التطبيق. اربط المشروع بطلب آخر أو فك الربط.<div class="nvs-acts"><button type="button" class="nvs-btn" data-m12="unlink">فك الربط</button></div></div>';}
  var os=b.orders();
  pop('ربط المشروع بطلب',(cur||'<p class="nvs-note">المشروع غير مرتبط بطلب. الربط يُظهر حالة التصميم ونسبة الإنتاج في بطاقة الطلب، ويُطبع رقم الطلب ورمزه على بطاقة متابعة الإنتاج.</p>')+
    (os.length?'<input id="nvlQ" placeholder="بحث برقم الطلب أو اسم العميل" style="width:100%;margin:6px 0">'+
      '<div class="nvs-olist" id="nvlL">'+os.map(function(o){return '<button type="button" class="nvs-orow'+(l&&l.oid===o.id?' on':'')+'" data-m12="link" data-oid="'+esc(o.id)+'" data-k="'+esc((o.no+' '+o.cust).toLowerCase())+'"><b>'+esc(o.no)+'</b><span>'+esc(o.cust)+'</span>'+(l&&l.oid===o.id?'<em>مرتبط</em>':'')+'</button>';}).join('')+'</div>'
      :'<div class="nvs-warn">لا توجد طلبات قائمة (غير ملغاة) في التطبيق.</div>'));
  var q=$('#nvlQ');if(q)q.addEventListener('input',function(){var v=q.value.trim().toLowerCase();$$('#nvlL .nvs-orow').forEach(function(r){r.style.display=!v||r.dataset.k.indexOf(v)>-1?'':'none';});});
}

/* ---------- الإصدارات والاعتماد ---------- */
function sumTxt(s){if(!s)return '';return s.pieces.length+' قطعة أثاث · '+s.parts+' لوح'+(s.cad?' · '+s.cad+' عنصر رسم':'');}
function diffHtml(d,ta,tb){
  if(!d)return '<div class="nvs-warn bad">تعذّرت المقارنة</div>';
  if(d.same)return '<p class="nvs-note">✓ لا فرق في القطع والأبعاد بين '+ta+' و'+tb+(d.objs[0]!==d.objs[1]||d.cad[0]!==d.cad[1]?' (اختلاف في عناصر غير تصنيعية: مجسمات '+d.objs[0]+'←'+d.objs[1]+'، رسم '+d.cad[0]+'←'+d.cad[1]+')':'')+'.</p>';
  var h='<div class="nvs-card"><b>'+ta+' ← '+tb+'</b><ul class="nvs-ol">';
  d.added.forEach(function(n){h+='<li>＋ أُضيف: '+esc(n)+'</li>';});
  d.removed.forEach(function(n){h+='<li>− حُذف: '+esc(n)+'</li>';});
  d.changed.forEach(function(c){h+='<li>✎ '+esc(c.name)+': '+esc(c.what.join('، '))+'</li>';});
  if(d.parts[0]!==d.parts[1])h+='<li>عدد الألواح: '+d.parts[0]+' ← '+d.parts[1]+'</li>';
  d.area.forEach(function(a){h+='<li>مساحة ألواح '+a.t+' مم: '+a.from+' ← '+a.to+' م²</li>';});
  return h+'</ul></div>';
}
function verDlg(){
  var s=E.verState(),V=E.versions().slice().reverse(),l=E.link();
  var wf=E.wfStatus(),head0='<div class="nvs-card fl-wf">حالة التصميم: '+(NV.FLOW?NV.FLOW.chip(wf.k):esc(wf.n))+'<div class="fl-steps">'+PRD.WFO.map(function(k){return '<span class="'+(k===wf.k?'on':'')+'">'+esc(PRD.WF[k])+'</span>';}).join('')+'</div><small class="nvs-mu">اعتماد العميل للنطاق في «مراجعة النطاق» شيء، واعتماد العميل للتصميم شيء، والاعتماد للتصنيع (هندسي) خطوة ثالثة بفحوص.</small>'+(l&&l.ik?'<div class="nvs-acts"><button type="button" class="nvs-btn sm" data-cmd="prod.scope">بيانات البند</button><button type="button" class="nvs-btn sm" data-cmd="prod.order">كل تصاميم الطلب</button></div>':'')+'</div>';
  var head=head0+'<div class="nvs-card">'+(l?'الطلب: <b>'+esc(l.no)+'</b> — '+esc(l.cust)+(l.iname?' · البند: <b>'+esc(l.iname)+'</b>':''):'غير مرتبط بطلب <button type="button" class="nvs-btn sm" data-cmd="prod.link">ربط…</button>')+'<br>'+
    (s.approved?'الإصدار المعتمد: <b>'+s.approved+'</b> '+(s.locked?'🔒 التصميم مقفل':(s.changed?'<span class="nvs-bad">⚠ التصميم الحالي يختلف عن المعتمد — احفظ إصدارًا جديدًا واعتمده أو استعد المعتمد</span>':'(القفل مفتوح)')):'لا يوجد إصدار معتمد بعد')+
    (s.approved?'<div class="nvs-acts"><button type="button" class="nvs-btn" data-cmd="prod.lock">'+(s.locked?'فتح قفل التعديل':'قفل التصميم')+'</button>'+(window.NVMO&&l&&l.ik!=null?window.NVMO.studioBtn(l):'')+'</div>':'')+'</div>';
  var save=s.locked?'':'<div class="nvs-card"><label class="nvs-f"><span>ملاحظة الإصدار</span><input id="nvvN" placeholder="مثال: تكبير الدولاب إلى 260 سم"></label><div class="nvs-acts"><button type="button" class="nvs-btn pri" data-m12="vsave"'+(s.count&&!s.sinceLast?' disabled':'')+'>حفظ التصميم الحالي كإصدار '+(s.last+1)+'</button></div>'+(s.count&&!s.sinceLast?'<small class="nvs-mu">لا تغييرات منذ الإصدار '+s.last+'.</small>':'')+'</div>';
  var list=V.length?V.map(function(v){
    var act=[],nx=PRD.NEXT[v.st]||[];
    if(nx.indexOf('review')>-1)act.push('<button type="button" class="nvs-btn sm" data-m12="vrev" data-n="'+v.n+'">طلب مراجعة داخلية</button>');
    if(nx.indexOf('sent')>-1)act.push('<button type="button" class="nvs-btn sm" data-m12="vsent" data-n="'+v.n+'">أُرسل للعميل</button>');
    if(nx.indexOf('capproved')>-1)act.push('<button type="button" class="nvs-btn sm pri" data-m12="vcapp" data-n="'+v.n+'">اعتمده العميل</button>');
    if(nx.indexOf('approved')>-1)act.push('<button type="button" class="nvs-btn sm pri" data-m12="vappr" data-n="'+v.n+'">اعتماد للتصنيع</button>');
    if(v.st!=='approved'&&v.st!=='superseded'&&nx.indexOf('approved')<0)act.push('<button type="button" class="nvs-btn sm" data-m12="vint" data-n="'+v.n+'" title="لأعمال داخلية بدون عميل — يُطلب سبب">اعتماد للتصنيع بدون عميل…</button>');
    if(nx.indexOf('rejected')>-1)act.push('<button type="button" class="nvs-btn sm" data-m12="vrej" data-n="'+v.n+'">يحتاج إلى تعديل</button>');
    act.push('<button type="button" class="nvs-btn sm" data-m12="vcmp" data-n="'+v.n+'">مقارنة بالحالي</button>');
    if(v.n>1)act.push('<button type="button" class="nvs-btn sm" data-m12="vcmpp" data-n="'+v.n+'">مقارنة بالسابق</button>');
    if(!s.locked)act.push('<button type="button" class="nvs-btn sm" data-m12="vrest" data-n="'+v.n+'">استعادة</button>');
    if(v.st==='draft'||v.st==='sent'||v.st==='rejected')act.push('<button type="button" class="nvs-btn sm red" data-m12="vdel" data-n="'+v.n+'">حذف</button>');
    return '<div class="nvs-ver">'+(v.thumb?'<img src="'+v.thumb+'" alt="">':'<div class="nvs-vth">إ'+v.n+'</div>')+
      '<div class="nvs-vb"><b>الإصدار '+v.n+'</b> '+vchip(v.st)+'<br><small>'+dt(v.t)+(v.by?' · '+esc(v.by):'')+' · '+esc(sumTxt(v.sum))+'</small>'+
      (v.note?'<div>'+esc(v.note)+'</div>':'')+
      (v.capp?'<small>اعتمده العميل '+dt(v.capp.t)+(v.capp.by?' — سجّله '+esc(v.capp.by):'')+(v.capp.note?' · '+esc(v.capp.note):'')+'</small><br>':'')+
      (v.st==='approved'||v.st==='superseded'?'<small>اعتُمد للتصنيع '+dt(v.at)+(v.aby?' — '+esc(v.aby):'')+(v.internal?' · بدون عميل: '+esc(v.internal):'')+'</small>':'')+
      (v.snote?'<div class="nvs-mu">ملاحظة الحالة: '+esc(v.snote)+'</div>':'')+
      '<div class="nvs-acts">'+act.join('')+'</div></div></div>';
  }).join(''):'<p class="nvs-note">لا توجد إصدارات. احفظ التصميم كإصدار ثم أرسله للعميل واعتمده — الاعتماد يقفل التصميم ويفتح متابعة الإنتاج.</p>';
  pop('الإصدارات والاعتماد',head+save+'<div id="nvvC"></div>'+list);
}
function approve(n,internal){
  var s=E.verState(),v=E.versions().filter(function(x){return x.n===n;})[0];if(!v)return;
  if(PRD.hash(E.serScene())!==v.hash&&!confirm('التصميم الحالي يختلف عن الإصدار '+n+'. عند اعتماده سيُطابَق المشروع مع الإصدار '+n+' ويُقفل (التعديلات الحالية تبقى في السجل). هل تتابع؟'))return;
  /* V19: فحوص قبل الاعتماد للتصنيع — على التصميم الحالي بعد مطابقته مع الإصدار */
  if(PRD.hash(E.serScene())!==v.hash){toast('استعد الإصدار '+n+' أولًا («استعادة») ثم اعتمده — الفحوص تُجرى على التصميم نفسه');return;}
  var ck=NV.FLOW?NV.FLOW.mfgCheck():{blocking:[],warn:[]};
  if(ck.blocking.length){pop('لا يمكن الاعتماد للتصنيع','<div class="nvs-warn bad">أخطاء تمنع الاعتماد:<ul class="nvs-ol">'+ck.blocking.slice(0,30).map(function(t){return '<li>'+esc(t)+'</li>';}).join('')+'</ul></div><div class="nvs-acts"><button type="button" class="nvs-btn" data-cmd="mfg.cnc">تقرير ملفات التصنيع</button><button type="button" class="nvs-btn" data-cmd="mfg.list">قائمة القطع</button></div>');return;}
  if(ck.warn.length&&!confirm('تنبيهات تحتاج مراجعة قبل التصنيع:\n• '+ck.warn.slice(0,8).join('\n• ')+'\n\nاعتماد الإصدار '+n+' للتصنيع مع ذلك؟'))return;
  var opt={checks:{t:Date.now(),warn:ck.warn.length}};if(internal)opt.internal=internal;
  var r=E.verStatus(n,'approved',opt);
  if(r&&r.err==='need-capp')return;
  if(r&&r.need==='rebase'){
    if(!confirm('بدأ الإنتاج على الإصدار '+r.from+'. اعتماد الإصدار '+n+' ينقل المتابعة إليه: القطع غير المتغيرة (نفس الرقم والاسم والأبعاد) تحتفظ بحالتها، والقطع المتغيرة تبدأ من جديد. هل تتابع؟'))return;
    opt.rebase=true;r=E.verStatus(n,'approved',opt);
  }
  if(r&&r.ok){toast('اعتُمد الإصدار '+n+' وقُفل التصميم'+(r.kept!=null?' — احتفظت '+r.kept+' قطعة بحالتها'+(r.reset&&r.reset.length?' وأُعيدت '+r.reset.length+' إلى البداية':''):''));verDlg();}
}
function m12Act(a,b){
  var n=b&&b.dataset.n?+b.dataset.n:0;
  if(a==='link'){var o=br().orderGet(b.dataset.oid);if(!o){toast('الطلب غير موجود');return;}E.setLink({oid:o.id,no:o.no,cust:o.cust});toast('رُبط المشروع بالطلب '+o.no);linkDlg();return;}
  if(a==='unlink'){if(confirm('فك ربط المشروع بالطلب؟ (لا يُحذف شيء من الطلب أو المشروع)')){E.setLink(null);toast('فُك الربط');linkDlg();}return;}
  if(a==='vsave'){var v=E.verSave(($('#nvvN')||{}).value||'');if(v){toast('حُفظ الإصدار '+v);verDlg();}return;}
  if(a==='vsent'){if(E.verStatus(n,'sent'))verDlg();return;}
  if(a==='vrej'){var note=prompt('سبب الرفض / ملاحظات العميل:','');if(note===null)return;if(E.verStatus(n,'rejected',{note:note}))verDlg();return;}
  if(a==='vappr'){approve(n);return;}
  if(a==='vint'){var why=prompt('سبب الاعتماد للتصنيع بدون اعتماد العميل (مثال: عمل داخلي للمعرض):','');if(!why||!why.trim()){if(why!==null)toast('السبب مطلوب');return;}approve(n,why.trim());return;}
  if(a==='vrev'){if(E.verStatus(n,'review'))verDlg();return;}
  if(a==='vcapp'){var nt=prompt('ملاحظة اعتماد العميل (اختياري — مثال: وافق عبر واتساب):','');if(nt===null)return;if(E.verStatus(n,'capproved',{note:nt}))verDlg();return;}
  if(a==='vcmp'){$('#nvvC').innerHTML=diffHtml(E.verCompare(n,'cur'),'الإصدار '+n,'التصميم الحالي');return;}
  if(a==='vcmpp'){var vs=E.versions().filter(function(x){return x.n<n;}),pv=vs[vs.length-1];if(!pv)return;$('#nvvC').innerHTML=diffHtml(E.verCompare(pv.n,n),'الإصدار '+pv.n,'الإصدار '+n);return;}
  if(a==='vrest'){if(!confirm('استبدال التصميم الحالي بالإصدار '+n+'؟ (يمكن التراجع)'))return;if(E.verRestore(n)){toast('استُعيد الإصدار '+n);verDlg();}return;}
  if(a==='vdel'){if(!confirm('حذف الإصدار '+n+' نهائيًا؟'))return;if(E.verDel(n)){toast('حُذف الإصدار '+n);verDlg();}return;}
  if(a==='pstart'){var st=($('#nvpS')||{}).value;if(E.prodStart(st?st.split('\n'):null)){toast('بدأت متابعة الإنتاج');prodDlg();}return;}
  if(a==='pnext'){
    if(b.dataset.src==='scan'){
      if($('#nvqW')&&!$('#nvqW').value){toast('اختر العامل الذي يسجّل أولًا');$('#nvqW').focus();return;}
      var px=E.prodState().parts.filter(function(p){return p.id===b.dataset.id;})[0],lx=px&&px.last;
      if(!b.dataset.ok&&lx&&lx[1]>lx[0]&&Date.now()-lx[2]<DUPMS){b.dataset.ok='1';b.textContent='تأكيد: مرحلة جديدة فعلًا ✓';
        var wn=document.createElement('div');wn.className='nvs-warn bad nvs-dup';wn.textContent='سُجّلت هذه القطعة قبل '+Math.max(1,Math.round((Date.now()-lx[2])/1000))+' ثانية («'+(E.prodState().stages[lx[1]-1]||'')+'»'+(lx[3]?' — '+lx[3]:'')+'). إن كان المسح مكررًا فلا تضغط مرة أخرى.';b.closest('.nvs-card').insertBefore(wn,b.closest('.nvs-acts'));return;}
    }
    if(E.prodMark(b.dataset.id,null,curWorker()))prodRefresh(b.dataset.id);return;}
  if(a==='pback'){var x=E.prodState().parts.filter(function(p){return p.id===b.dataset.id;})[0];if(x&&x.s>0&&E.prodMark(x.id,x.s-1,curWorker()))prodRefresh(x.id);return;}
  if(a==='ppiece'){var to=+($('#nvpP'+b.dataset.k)||{}).value;var c=E.prodMarkPiece(b.dataset.pid,to);toast(c?'سُجّلت المرحلة لـ '+c+' قطعة':'كل القطع وصلت هذه المرحلة مسبقًا');prodDlg();return;}
  if(a==='preset'){if(confirm('حذف كل تسجيلات الإنتاج لهذا المشروع؟ لا يمكن التراجع.')&&confirm('تأكيد نهائي: إعادة ضبط متابعة الإنتاج؟')){E.prodReset();toast('أُعيد ضبط متابعة الإنتاج');prodDlg();}return;}
  if(a==='sstage'){var t=($('#nvsgS')||{}).value||'';if(E.prodStages(t.split('\n'))){toast('حُفظت المراحل');stagesDlg();}return;}
  if(a==='scango'){scanHandle(($('#nvqM')||{}).value||'');return;}
  if(a==='scancam'){camStart();return;}
  if(a==='scanopen'){stopCam();closePop();E.openProject(b.dataset.pid).then(function(){setTimeout(function(){scanDlg(b.dataset.code||'');},300);});return;}
  if(a==='scanorder'){stopCam();openOrderProj(b.dataset.oid);return;}
}

/* ---------- متابعة الإنتاج ---------- */
function bar(p){return '<div class="nvs-pbar"><i style="width:'+Math.max(0,Math.min(100,p))+'%"></i><em>'+p+'%</em></div>';}
function stTxt(st,p){var n=st.stages.length;if(p.s>=n)return '✓ منتهية';return (p.s?'✓ '+st.stages[p.s-1]+' · ':'')+'التالية: '+st.stages[p.s];}
function partRow(st,p){
  var n=st.stages.length;
  return '<div class="nvs-prow" data-pid="'+esc(p.id)+'" data-k="'+esc((p.id+' '+p.name+' '+p.piece).toLowerCase())+'"><div><b>'+esc(p.id)+'</b> '+esc(p.name)+' <small class="nvs-mu">'+p.L+'×'+p.W+'×'+p.T+'</small><br><small>'+esc(stTxt(st,p))+(p.last?' · '+dt(p.last[2])+(p.last[3]?' '+esc(p.last[3]):''):'')+'</small></div>'+
    '<div class="nvs-pst">'+st.stages.map(function(s,i){return '<i class="'+(i<p.s?'on':'')+'" title="'+esc(s)+'"></i>';}).join('')+'</div>'+
    '<div class="nvs-acts"><button type="button" class="nvs-btn sm" data-m12="pback" data-id="'+esc(p.id)+'"'+(p.s?'':' disabled')+' aria-label="تراجع">↶</button><button type="button" class="nvs-btn sm pri" data-m12="pnext" data-id="'+esc(p.id)+'"'+(p.s>=n?' disabled':'')+'>'+(p.s>=n?'منتهية':esc(st.stages[p.s])+' ✓')+'</button></div></div>';
}
function prodDlg(){
  var s=E.verState(),st=E.prodState();
  if(!s.approved){pop('متابعة الإنتاج','<div class="nvs-warn">الإنتاج يتبع الإصدار المعتمد فقط. احفظ التصميم كإصدار واعتمده أولًا.</div><div class="nvs-acts"><button type="button" class="nvs-btn pri" data-cmd="prod.versions">الإصدارات والاعتماد…</button></div>');return;}
  if(!st){
    pop('متابعة الإنتاج','<p class="nvs-note">ستُتابَع قطع الإصدار المعتمد '+s.approved+' قطعةً قطعة بأرقامها المطبوعة على الملصقات والرسومات. عدّل المراحل (مرحلة في كل سطر) قبل البدء:</p>'+
      '<textarea id="nvpS" rows="6" style="width:100%">'+esc(PRD.STAGES.join('\n'))+'</textarea><div class="nvs-acts"><button type="button" class="nvs-btn pri" data-m12="pstart">بدء متابعة الإنتاج</button></div>');return;}
  var pg=st.prog,pcs=Object.keys(pg.pieces);
  var h='<div class="nvs-card">الإصدار '+st.ver+(E.link()?' · الطلب '+esc(E.link().no):'')+' · '+pg.parts+' قطعة · منتهية '+pg.full+bar(pg.pct)+
    '<div class="nvs-sts">'+st.stages.map(function(x,i){return '<span>'+esc(x)+': <b>'+pg.perStage[i]+'</b>/'+pg.parts+'</span>';}).join('')+'</div>'+
    (s.changed?'<div class="nvs-warn">التصميم الحالي يختلف عن الإصدار المعتمد — المتابعة على الإصدار '+st.ver+'.</div>':'')+
    '<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-cmd="prod.scan">📷 مسح QR</button><button type="button" class="nvs-btn" data-cmd="prod.traveler">بطاقة المتابعة</button><button type="button" class="nvs-btn" data-cmd="prod.stages">المراحل</button><button type="button" class="nvs-btn red" data-m12="preset">إعادة ضبط</button></div></div>';
  h+=pcs.map(function(k,ki){var g=pg.pieces[k];
    return '<details class="nvs-pgrp"><summary><b>'+esc(g.name)+'</b> · منتهية '+g.full+' من '+g.parts+bar(g.pct)+'</summary>'+
      '<div class="nvs-acts"><select id="nvpP'+ki+'">'+st.stages.map(function(x,i){return '<option value="'+(i+1)+'">حتى: '+esc(x)+'</option>';}).join('')+'</select><button type="button" class="nvs-btn sm" data-m12="ppiece" data-k="'+ki+'" data-pid="'+esc(k)+'">تسجيل لكل قطع هذا الصنف</button></div>'+
      st.parts.filter(function(p){return p.pieceId===k;}).map(function(p){return partRow(st,p);}).join('')+'</details>';}).join('');
  pop('متابعة الإنتاج','<input id="nvpQ" placeholder="بحث برقم القطعة أو اسمها" style="width:100%;margin-bottom:6px">'+h);
  var q=$('#nvpQ');q.addEventListener('input',function(){var v=q.value.trim().toLowerCase();$$('#nvsPop details.nvs-pgrp').forEach(function(d){var any=false;d.querySelectorAll('.nvs-prow').forEach(function(r){var on=!v||r.dataset.k.indexOf(v)>-1;r.style.display=on?'':'none';if(on)any=true;});d.style.display=any?'':'none';if(v&&any)d.open=true;});});
}
function prodRefresh(id){
  var st=E.prodState(),p=st&&st.parts.filter(function(x){return x.id===id;})[0];
  var row=root.querySelector('#nvsPop .nvs-prow[data-pid="'+id+'"]');
  if(row&&p){var t=document.createElement('div');t.innerHTML=partRow(st,p);row.replaceWith(t.firstChild);}
  var sc=$('#nvqR');if(sc&&p)sc.innerHTML=scanCard(st,p);
  toast(p?(p.id+': '+(p.s>=st.stages.length?'منتهية من كل المراحل':(p.s?'✓ '+st.stages[p.s-1]:'عادت إلى البداية'))):'');
}
function stagesDlg(){
  var st=E.prodState();
  if(!st){pop('مراحل الإنتاج','<p class="nvs-note">تُحدَّد المراحل عند بدء متابعة الإنتاج. الافتراضي: '+esc(PRD.STAGES.join('، '))+'.</p><div class="nvs-acts"><button type="button" class="nvs-btn pri" data-cmd="prod.track">متابعة الإنتاج…</button></div>');return;}
  var locked=E.verState().prodStarted;
  pop('مراحل الإنتاج',locked?'<p class="nvs-note">المراحل: '+esc(st.stages.join(' ← '))+'</p><div class="nvs-warn">لا تُغيَّر المراحل بعد تسجيل أي تقدّم (حتى لا تختلط الحالات المسجلة). أعد ضبط المتابعة لتغييرها.</div>':
    '<p class="nvs-note">مرحلة في كل سطر، من 1 إلى 12 مرحلة بالترتيب:</p><textarea id="nvsgS" rows="7" style="width:100%">'+esc(st.stages.join('\n'))+'</textarea><div class="nvs-acts"><button type="button" class="nvs-btn pri" data-m12="sstage">حفظ</button></div>');
}

/* ---------- مسح QR ---------- */
var cam={stream:null,det:null,t:0,last:'',lastT:0};
function camOk(){return !!(window.BarcodeDetector&&navigator.mediaDevices&&navigator.mediaDevices.getUserMedia);}
function stopCam(){clearTimeout(cam.t);if(cam.stream){cam.stream.getTracks().forEach(function(t){try{t.stop();}catch(e){}});}cam.stream=null;}
function scanDlg(code){
  stopCam();
  pop('مسح QR',(camOk()?'<div class="nvs-cam"><video id="nvqV" playsinline muted></video></div><div class="nvs-acts"><button type="button" class="nvs-btn pri" data-m12="scancam">📷 تشغيل الكاميرا</button></div>':
      '<div class="nvs-warn">قراءة QR بالكاميرا من داخل الصفحة غير مدعومة في هذا المتصفح (تعمل في Chrome على أندرويد). أدخل رقم القطعة المطبوع بجانب الرمز، أو امسح الرمز بتطبيق الكاميرا وانسخ النص هنا.</div>')+
    '<div class="nvs-row2"><input id="nvqM" dir="ltr" placeholder="WR1-08 أو نص الرمز" autocapitalize="characters" style="flex:1"><button type="button" class="nvs-btn" data-m12="scango">بحث</button></div><div id="nvqR"></div>');
  var m=$('#nvqM');m.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();scanHandle(m.value);}});
  if(code){m.value=code;scanHandle(code);}
}
function camStart(){
  var v=$('#nvqV');if(!v)return;
  try{cam.det=new window.BarcodeDetector({formats:['qr_code']});}catch(e){toast('قارئ QR غير متاح في هذا المتصفح');return;}
  navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false}).then(function(s){
    if(!$('#nvqV')){s.getTracks().forEach(function(t){t.stop();});return;}
    cam.stream=s;v.srcObject=s;v.play().catch(function(){});tick();
  },function(e){toast('تعذّر فتح الكاميرا: '+(e&&e.name==='NotAllowedError'?'لم يُسمح بالوصول إلى الكاميرا':(e&&e.message||e)));});
  function tick(){
    if(!cam.stream||!$('#nvqV'))return stopCam();
    cam.det.detect(v).then(function(r){
      if(r&&r.length){var c=r[0].rawValue;if(c&&(c!==cam.last||Date.now()-cam.lastT>3000)){cam.last=c;cam.lastT=Date.now();$('#nvqM').value=c;scanHandle(c);if(navigator.vibrate)navigator.vibrate(60);}}
      cam.t=setTimeout(tick,250);
    },function(){cam.t=setTimeout(tick,500);});
  }
}
/* V42: العامل الذي يسجّل (من سجل العمال في التطبيق) — يُحفظ اختياره على هذا الجهاز */
var DUPMS=120000;
function workers(){var b=br();try{return b&&b.workers?b.workers():[];}catch(e){return [];}}
function curWorker(){var w=$('#nvqW');return w?w.value:'';}
function savedWorker(){try{return localStorage.getItem('nvqWorker')||'';}catch(e){return '';}}
function logTxt(st,x){var to=x[1],from=x[0];return (to>from?'✓ '+esc(st.stages[to-1]||''):'↶ تراجع إلى '+(to?esc(st.stages[to-1]):'البداية'))+' — '+(x[3]?esc(x[3]):'بدون اسم')+' — '+new Date(x[2]).toLocaleString('ar',{dateStyle:'short',timeStyle:'short'});}
function scanExtra(st,p,stale){
  var W=workers(),cw=$('#nvqW')?$('#nvqW').value:savedWorker(),h='';
  if(stale)h+='<div class="nvs-warn">⚠ ملصق قديم من الإصدار '+stale.label+' — الإصدار المعتمد الآن '+stale.cur+' والقطعة لم تتغير. اطبع ملصقًا جديدًا.</div>';
  if(W.length)h+='<label class="nvs-f"><span>العامل الذي يسجّل</span><select id="nvqW"><option value="">— اختر العامل —</option>'+W.map(function(w){return '<option'+(w.name===cw?' selected':'')+'>'+esc(w.name)+'</option>';}).join('')+'</select></label>';
  var lg=(p.log||[]).slice(-5).reverse();
  if(lg.length)h+='<details class="nvs-plog"'+(Date.now()-lg[0][2]<DUPMS?' open':'')+'><summary>سجل القطعة ('+(p.log||[]).length+')</summary><ul>'+lg.map(function(x){return '<li>'+logTxt(st,x)+'</li>';}).join('')+'</ul></details>';
  return h;
}
function scanCard(st,p,stale){
  var n=st.stages.length;
  return '<div class="nvs-card nvs-scan"><b style="font-size:1.3em">'+esc(p.id)+'</b> — '+esc(p.name)+'<br><small>'+esc(p.piece)+' · '+p.L+'×'+p.W+'×'+p.T+' مم · الإصدار '+st.ver+'</small>'+scanExtra(st,p,stale)+
    '<div class="nvs-pst big">'+st.stages.map(function(s,i){return '<i class="'+(i<p.s?'on':'')+'"><span>'+esc(s)+'</span></i>';}).join('')+'</div>'+
    '<div class="nvs-acts"><button type="button" class="nvs-btn" data-m12="pback" data-id="'+esc(p.id)+'"'+(p.s?'':' disabled')+'>↶ تراجع</button><button type="button" class="nvs-btn pri" data-m12="pnext" data-src="scan" data-id="'+esc(p.id)+'"'+(p.s>=n?' disabled':'')+'>'+(p.s>=n?'منتهية من كل المراحل':'تسجيل: '+esc(st.stages[p.s])+' ✓')+'</button></div></div>';
}
document.addEventListener('change',function(e){if(e.target&&e.target.id==='nvqW'){try{localStorage.setItem('nvqWorker',e.target.value);}catch(x){}}});
function scanHandle(code){
  var out=$('#nvqR');if(!out)return;code=String(code||'').trim();
  if(/^NVX1\|/i.test(code)){var bx=window.NVBridge&&NVBridge.exFind?NVBridge.exFind(code):null;
    out.innerHTML=bx&&!bx.missing?'<div class="nvs-card">طلب تصنيع خارجي '+esc(bx.no)+' — '+esc(bx.kind)+' — '+esc(bx.st)+'<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-exopen="'+esc(code)+'">فتح في «التصنيع الخارجي»</button></div></div>':'<div class="nvs-warn">رمز طلب تصنيع خارجي غير موجود على هذا الجهاز.</div>';return;}
  if(!/^NV[PO][12]\|/.test(code))code=code.toUpperCase();
  if(!code){out.innerHTML='';return;}
  var r=E.prodFind(code);
  if(r.order){
    out.innerHTML='<div class="nvs-card">رمز الطلب '+esc(r.no||'')+'<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-m12="scanorder" data-oid="'+esc(r.order)+'">فتح تصميم الطلب</button></div></div>';return;}
  if(r.other){
    out.innerHTML='<div class="nvs-warn">القطعة '+esc(r.part)+' من مشروع آخر.</div>';
    NV.Store.get(r.other).then(function(d){if(!$('#nvqR'))return;out.innerHTML=d?'<div class="nvs-warn">القطعة '+esc(r.part)+' من مشروع «'+esc(d.name)+'».<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-m12="scanopen" data-pid="'+esc(r.other)+'" data-code="'+esc(code)+'">فتح المشروع ومتابعة القطعة</button></div></div>':'<div class="nvs-warn bad">القطعة '+esc(r.part)+' من مشروع غير موجود على هذا الجهاز.</div>';});
    return;}
  if(r.err){out.innerHTML='<div class="nvs-warn bad">'+esc(r.err)+'</div>';return;}
  var st=E.prodState(),p=st.parts.filter(function(x){return x.id===r.part;})[0];
  out.innerHTML=scanCard(st,p,r.stale);
}

/* ---------- فتح تصميم طلب من التطبيق ---------- */
function openOrderProj(oid){
  var b0=br();if(b0&&b0.scopeOf&&NV.FLOW){NV.FLOW.orderView&&window.NVS.orderView(oid);return;}
  var b=br(),o=b&&b.orderGet?b.orderGet(oid):null;
  if(!o){toast('الطلب غير موجود');return;}
  var tries=0;
  (function wait(){
    if(!E.project()){if(++tries>100){toast('الاستوديو لم يجهز بعد — أعد المحاولة');return;}setTimeout(wait,100);return;}
    var cur=E.link();if(cur&&cur.oid===oid){closePop();toast('تصميم الطلب '+o.no+' مفتوح');return;}
    E.findByOrder(oid).then(function(a){
      closePop();
      if(a.length){E.openProject(a[0].id);if(a.length>1)toast('للطلب '+a.length+' مشاريع — فُتح الأحدث. البقية في «فتح مشروع»');return;}
      E.newProject((o.no?o.no+' — ':'')+(o.cust||'تصميم'));
      setTimeout(function(){E.setLink({oid:o.id,no:o.no,cust:o.cust});toast('أُنشئ مشروع تصميم جديد مرتبط بالطلب '+o.no);},50);
    });
  })();
}

/* ---------- بطاقة متابعة الإنتاج (طباعة) ---------- */
function printTraveler(){
  var s=E.verState(),st=E.prodState(),L,stages,ver,draft=false;
  if(st){L=st.parts;stages=st.stages;ver=st.ver;}
  else if(s.approved){var sc=E.verScene(s.approved);L=PRD.flat(PRD.parts(sc,NVM,NV.MFG)).map(function(p){p.s=0;return p;});stages=PRD.STAGES;ver=s.approved;}
  else{var cur=JSON.parse(E.serScene());L=PRD.flat(PRD.parts(cur,NVM,NV.MFG)).map(function(p){p.s=0;return p;});stages=PRD.STAGES;ver=0;draft=true;}
  if(!L.length){toast('لا توجد قطع تصنيع (قوالب الأثاث) في '+(ver?'الإصدار المعتمد':'المشروع'));return;}
  var pid=E.projId(),l=E.link(),o=l?E.linkOrder():null,pr=E.project(),G={},order=[];
  L.forEach(function(p){if(!G[p.pieceId]){G[p.pieceId]=[];order.push(p.pieceId);}G[p.pieceId].push(p);});
  var css='<style>.tv h1{font-size:15pt;margin:0 0 4px}.tv .hd{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;border-bottom:2px solid #000;padding-bottom:6px;margin-bottom:8px}.tv .hd svg{width:30mm;height:30mm}.tv table{width:100%;border-collapse:collapse;font-size:8.5pt;margin-bottom:8px;page-break-inside:auto}.tv tr{page-break-inside:avoid}.tv td,.tv th{border:1px solid #000;padding:2px 3px;text-align:center}.tv td.q svg{width:17mm;height:17mm;display:block;margin:auto}.tv td.n{text-align:right}.tv .bx{font-size:13pt}.tv h2{font-size:11pt;margin:8px 0 3px}.tv .dr{color:#c00;font-weight:bold}</style>';
  var h='<div class="tv">'+css+'<div class="hd"><div><h1>بطاقة متابعة الإنتاج</h1>'+
    '<div>المشروع: <b>'+esc(pr.name)+'</b></div>'+
    (o?'<div>الطلب: <b>'+esc(o.no)+'</b> — '+esc(o.cust)+(o.delivery?' · التسليم: '+esc(o.delivery):'')+'</div>':l?'<div>الطلب: '+esc(l.no)+' (غير موجود في التطبيق)</div>':'<div>غير مرتبط بطلب</div>')+
    (draft?'<div class="dr">مسودة — لا يوجد إصدار معتمد. الأرقام قد تتغير.</div>':'<div>الإصدار المعتمد: <b>'+ver+'</b>'+(s.changed&&!st?'':'')+'</div>')+
    '<div>المراحل: '+esc(stages.join(' ← '))+' · '+L.length+' قطعة · طُبعت '+dt(Date.now())+'</div></div>'+
    (o?'<div style="text-align:center">'+QR.svg(QR.orderCode(o.id,o.no),{margin:4})+'<div style="font-size:7pt">'+esc(o.no)+'</div></div>':'')+'</div>';
  order.forEach(function(k){var ps=G[k];
    h+='<h2>'+esc(ps[0].piece)+' ('+ps.length+' قطعة)</h2><table><thead><tr><th>QR</th><th>الرقم</th><th>القطعة</th><th>الطول × العرض × السُمك مم</th>'+stages.map(function(x){return '<th>'+esc(x)+'</th>';}).join('')+'</tr></thead><tbody>'+
      ps.map(function(p){return '<tr><td class="q">'+QR.svg(QR.partCode(pid,p.id,draft?null:ver),{margin:4})+'</td><td><b>'+esc(p.id)+'</b></td><td class="n">'+esc(p.name)+'</td><td>'+p.L+' × '+p.W+' × '+p.T+'</td>'+
        stages.map(function(x,i){return '<td class="bx">'+(i<p.s?'☑':'☐')+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table>';});
  h+='</div>';
  var b=br();setFull(false);if(b&&b.sheet)b.sheet(h);else{var w=window.open('','_blank');if(w){w.document.write('<html dir="rtl"><body>'+h+'</body></html>');w.document.close();w.print();}else toast('تعذّر فتح نافذة الطباعة');}
}
function qrWarn(){var s=E.verState&&E.verState();return s&&s.approved&&s.changed?'<div class="nvs-warn">التصميم الحالي يختلف عن الإصدار المعتمد '+s.approved+' — رموز QR وأرقام القطع هنا تخص التصميم الحالي، والإنتاج يتابع الإصدار المعتمد.</div>':'';}

/* ================= V13: التصميم الحر ومحرر الأثاث 2D ================= */
cmd('create.cab','تصميم حر — خزانة / دولاب…','Free Design Cabinet…',function(){if(need())cabDlg();});
cmd('cab.edit','محرر الأثاث 2D (أمامي/جانبي/علوي)','Furniture 2D Editor',function(){if(!need())return;if(NV.FE)NV.FE.open();});
function cabDlg(){
  pop('تصميم حر — خزانة أو دولاب',
    '<p class="nvs-note">ابدأ من جسم فارغ وقسّمه كما تريد، أو من بداية جاهزة تعدّلها بالكامل. الأبعاد بالملليمتر.</p>'+
    fld('البداية','<select id="ncS"><option value="empty">جسم فارغ (بدون تقسيم)</option><option value="wardrobe">دولاب مبدئي (تعليق + أدراج + أرفف + أبواب)</option><option value="open">رف مفتوح بأرفف</option>'+divOpts()+'</select>')+
    '<div class="nvs-row3"><b>الأبعاد (مم)</b>'+fld('العرض',numIn('ncW',2000,1,' min="200"'))+fld('الارتفاع',numIn('ncH',2200,1,' min="200"'))+fld('العمق الكلي',numIn('ncD',600,1,' min="150"'))+'</div>'+
    fld('سماكة الألواح (مم)','<select id="ncT"><option>16</option><option selected>18</option><option>19</option><option>25</option></select>')+
    fld('الخامة','<input id="ncM" value="MDF">')+fld('الاسم','<input id="ncN" value="دولاب — تصميم حر">')+
    '<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-m13="cabnew">إنشاء وفتح المحرر</button></div>');
  /* V68: بداية حسب الصنف من المحرك الموحد — تملأ الأبعاد والاسم المقترحين (قابلة للتعديل) */
  var sS=$('#ncS');if(sS)sS.onchange=function(){var v=sS.value;if(v.indexOf('kind:')!==0||!NV.DIV)return;var t=v.slice(5),p=NV.DIV.prof(t);if(!p)return;
    var d=p.dims||[100,60,100];$('#ncW').value=d[0]*10;$('#ncD').value=d[1]*10;$('#ncH').value=d[2]*10;$('#ncN').value=t+' — تصميم حر';};
}
function divOpts(){if(!NV.DIV)return '';return '<optgroup label="بداية حسب الصنف (التقسيم الموحد)">'+NV.DIV.FT.filter(function(t){return NV.DIV.divisible(t);}).map(function(t){var p=NV.DIV.prof(t);
  return '<option value="kind:'+esc(t)+'">'+esc(t)+(p.div==='part'?' — '+esc(p.part):p.div==='module'?' — وحدة تخزين':'')+'</option>';}).join('')+'</optgroup>';}
function cabForm(s){
  var R=null;try{R=NV.CAB.gen(s);}catch(e){}
  var nP=R?R.panels.filter(function(p){return p.cut;}).length:0,nF=(s.fronts||[]).length;
  return '<div class="nvs-sec"><h4>تصميم حر <small>'+Math.round(s.W)+' × '+Math.round(s.H)+' × '+Math.round(s.D)+' مم · '+esc((s.mat&&s.mat.body)||'')+' '+s.t+' مم</small></h4>'+
    '<p class="nvs-note">'+nP+' لوحًا للقص · '+nF+' واجهات'+(R&&R.warn.length?' · <b>'+R.warn.length+' تنبيهات</b>':'')+'</p>'+
    '<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-cmd="cab.edit">فتح محرر الأثاث 2D</button><button type="button" class="nvs-btn" data-cmd="mfg.parts">القطع والتخريم</button></div></div>';
}
function m13Act(a){
  if(a==='cabnew'){
    var W=+$('#ncW').value,H=+$('#ncH').value,D=+$('#ncD').value,t=+$('#ncT').value;
    if(!(W>=200&&H>=200&&D>=150)){toast('الأبعاد: العرض والارتفاع 200 مم على الأقل والعمق 150 مم');return;}
    var sv=$('#ncS').value,sp=sv.indexOf('kind:')===0&&NV.DIV?NV.DIV.preset(sv.slice(5),W,H,D,{t:t,name:$('#ncN').value||'تصميم حر'}):NV.CAB.preset(sv,W,H,D,{t:t,name:$('#ncN').value||'تصميم حر'});
    if(!sp){toast('هذا الصنف لا يُقسَّم');return;}sp.mat.body=sp.mat.front=$('#ncM').value||'MDF';
    closePop();var o=E.addMfg('cab',sp);if(!o){toast('تعذّر إنشاء القطعة');return;}
    setTimeout(function(){if(NV.FE)NV.FE.open();},30);
  }
}

