/* ---------------- القوائم المنسدلة ---------------- */
function buildMenus(){
  $('#nvsMenu').innerHTML=MENUS.map(function(m){return '<button type="button" class="nvs-mb" data-menu="'+m[0]+'" title="'+esc(m[2])+'">'+esc(S.lang==='en'?m[2]:m[1])+'</button>';}).join('');
}
function openDrop(id,btn){
  var m=MENUS.filter(function(x){return x[0]===id;})[0],d=$('#nvsDrop');if(!m)return;
  if(d.dataset.open===id&&d.style.display==='block'){closeDrop();return;}
  d.innerHTML='<div class="nvs-dh">'+esc(m[1])+' · '+esc(m[2])+'</div>'+m[3].map(function(cid){
    if(cid==='-')return '<div class="nvs-sep"></div>';
    if(cid[0]==='#')return '<div class="nvs-dg">'+esc(cid.slice(1))+'</div>';
    var c=C[cid];if(!c)return '';
    var chk=checked(cid);
    return '<button type="button" class="nvs-di'+(c.v?' fut':'')+'" data-cmd="'+cid+'"'+(c.v?' aria-disabled="true"':'')+'>'+
      '<span class="nvs-dl">'+(chk?'<i class="nvs-ck">✓</i>':'')+esc(L(c))+(S.lang!=='en'?'<small>'+esc(c.en)+'</small>':'')+'</span>'+
      (c.v?'<em class="nvs-vt">'+c.v+'</em>':(c.o.k?'<kbd>'+esc(c.o.k)+'</kbd>':''))+'</button>';
  }).join('');
  d.dataset.open=id;d.style.display='block';
  var rr=root.getBoundingClientRect(),br=btn.getBoundingClientRect(),w=Math.min(300,rr.width-12);
  d.style.width=w+'px';
  var right=rr.right-br.right;right=Math.max(6,Math.min(rr.width-w-6,right));
  d.style.right=right+'px';d.style.left='auto';d.style.top=(br.bottom-rr.top+2)+'px';
  $$('.nvs-mb').forEach(function(b){b.classList.toggle('on',b.dataset.menu===id);});
}
function closeDrop(){var d=$('#nvsDrop');d.style.display='none';d.dataset.open='';$$('.nvs-mb').forEach(function(b){b.classList.remove('on');});}
function checked(cid){
  var m=E.ready?E.mode():'';
  if(cid==='view.cad')return S.layout==='cad';if(cid==='view.cad3d')return S.layout==='cad3d';
  if(cid==='cad.ortho')return S.cadOrtho;if(cid==='cad.osnap')return S.cadSnap;if(cid==='cad.grid')return S.cadGrid;if(cid==='cad.gsnap')return S.cadGridSnap;if(cid==='cad.lwt')return S.cadLwt;if(cid==='cad.len')return S.cadShowLen;if(cid==='cad.multi')return CAD&&CAD.multi;
  if(cid.indexOf('cad.')===0&&CAD&&CAD.tool&&CAD.tool()===cid.slice(4))return true;
  if(cid==='view.3d')return S.layout==='3d';if(cid==='view.2d')return S.layout==='2d';if(cid==='view.split')return S.layout==='split';
  if(cid==='view.grid')return S.grid;if(cid==='view.axes')return S.axes;if(cid==='view.ortho')return E.ready&&E.ortho();
  if(cid==='light.shadows')return S.shadows;if(cid==='light.marks')return S.lightMarks!==false;if(cid==='set.snap')return S.snap;if(cid==='set.autosave')return S.autosave;
  if(cid.indexOf('set.u')===0)return 'set.u'+S.units===cid;if(cid.indexOf('light.')===0)return 'light.'+S.light===cid;
  if(cid.indexOf('view2.')===0)return E.ready&&S.layout!=='3d'&&E.view2()===cid.slice(6);
  if(cid==='mod.multi')return E.ready&&E.multiMode();if(cid==='set.snapobj')return S.snapObj;if(cid==='create.pushpull')return m==='pushpull';if(cid==='mod.closegroup')return !!(E.ready&&E.ctx());
  if(cid==='mod.select')return m==='select';if(cid==='mod.move')return m==='move';if(cid==='mod.rotate')return m==='rotate';if(cid==='mod.scale')return m==='scale';if(cid==='tool.measure')return m==='measure';
  return false;
}

