    '<div class="nvs-row3"><b>العرض × الارتفاع × العمق ('+un+')</b>'+fld('W',numIn('nvdW',U.to(d[0]),U.step(),bed?' disabled':''))+fld('H',numIn('nvdH',U.to(d[1]),U.step(),bed?' disabled':''))+fld('D',numIn('nvdD',U.to(d[2]),U.step(),bed?' disabled':''))+'</div>'+
    (bed?'<p class="nvs-note">مقاس السرير يُحدَّد من مقاس المرتبة في «خصائص».</p>':'<button type="button" class="nvs-btn pri" data-act="dims-apply">تطبيق الأبعاد</button>')+
    (u.kind==='mfg'?'<p class="nvs-note">لقطع التصنيع تُغيّر هذه القيم المواصفات نفسها، فتُعاد القطع وقائمة القطع بأبعاد حقيقية — لا يُستخدم التحجيم.</p>':'')+
    '</div><div class="nvs-sec"><h4>الحيز في المشهد <small>بعد الدوران</small></h4><div class="nvs-kv">'+
    kv('عرض الحيز X',U.fmt(inf.world[0]))+kv('ارتفاع الحيز Y',U.fmt(inf.world[1]))+kv('عمق الحيز Z',U.fmt(inf.world[2]))+kv('الموضع',[0,1,2].map(function(i){return U.to(inf.pos[i]);}).join(' ، ')+' '+un)+'</div></div>';
  var ms=E.measList();
  h+='<div class="nvs-sec"><h4>القياسات <small>'+ms.length+'</small></h4>'+(ms.length?'<div class="nvs-kv">'+ms.map(function(m,i){return kv('قياس '+(i+1),U.fmt(m.len)+' <small>(ΔX '+U.to(m.dx)+' · ΔY '+U.to(m.dy)+' · ΔZ '+U.to(m.dz)+')</small>');}).join('')+'</div><button type="button" class="nvs-btn" data-cmd="tool.measclear">مسح القياسات</button>':'<p class="nvs-note">استخدم أداة «قياس» ثم اضغط على نقطتين.</p>')+'</div>';
  return h;
