function kv(k,v){return '<div><span>'+esc(k)+'</span><b>'+v+'</b></div>';}
var matRole='all',ROLES=[['all','الكل'],['front','الواجهات'],['body','الهيكل'],['inner','الداخل'],['fabric','التنجيد'],['top','السطح']];
var thumbC={};
function matThumb(d){
  var sig=JSON.stringify([d.c,d.tex]);if(thumbC[sig])return thumbC[sig];
  var url='',k=d.tex&&d.tex.k||'solid';
  try{if(k==='img'){url=E.matAssetUrl(d.tex.img)||'';}
    else if(k==='solid')url='';
    else{var N=64,g=NV.MAT.gen(k,N,{c:d.c,c2:d.tex.c2,seed:d.tex.seed||7}),c=document.createElement('canvas');c.width=c.height=N;var x=c.getContext('2d'),im=x.createImageData(N,N);im.data.set(g.rgb);x.putImageData(im,0,0);url=c.toDataURL('image/png');}}catch(e){url='';}
  thumbC[sig]=url;return url;
}
function swatch(d){var u=matThumb(d);return '<i class="nvs-msw" style="background:'+d.c+(u?' url('+u+') center/cover':'')+(d.op&&d.op<1?';opacity:'+Math.max(0.35,d.op):'')+'"></i>';}
function pMat(){
  var o=E.sel(),L=E.mats(),h='';
  if(o){
    var mi=E.matInfo(o),isM=o.userData.kind==='mfg'||o.userData.kind==='group',cur=matRole!=='all'&&mi.rl&&mi.rl[matRole]?mi.rl[matRole]:mi.lib;
    h+='<div class="nvs-sec"><h4>خامة '+esc(o.name)+' <small>'+(mi.libName?'«'+esc(mi.libName)+'»':(mi.rl?'خامات حسب الجزء':'لون سريع بدون مكتبة'))+'</small></h4>';
    var pres={all:1};o.traverse(function(x){if(x.isMesh&&x.userData.role)pres[x.userData.role]=1;});var RL=ROLES.filter(function(r){return pres[r[0]];});if(RL.length<3)isM=o.userData.kind==='group';
    if(isM)h+='<div class="nvs-seg" role="group" aria-label="الجزء">'+(o.userData.kind==='group'?ROLES:RL).map(function(r){return '<button type="button" data-mrole="'+r[0]+'" class="'+(matRole===r[0]?'on':'')+'">'+r[1]+'</button>';}).join('')+'</div>'+
      (mi.rl?'<p class="nvs-note">'+RL.slice(1).map(function(r){var id=mi.rl[r[0]],d=id&&L.filter(function(x){return x.id===id;})[0];return r[1]+': '+(d?esc(d.name):'—');}).join(' · ')+'</p>':'');
    h+=L.length?'<div class="nvs-mlib">'+L.map(function(d){return '<button type="button" data-mapply="'+d.id+'" class="'+(d.id===cur?'on':'')+'" title="'+esc(d.name)+'">'+swatch(d)+'<span>'+esc(d.name)+'</span></button>';}).join('')+'</div>'
      :'<p class="nvs-note">مكتبة المشروع فارغة. أنشئ خامة، أو أضف خامات العرض الجاهزة، أو خذ خامة من دليل خامات التطبيق.</p>';
    h+='<div class="nvs-acts"><button type="button" class="nvs-btn" data-cmd="mat.new">＋ خامة جديدة</button>'+(cur?'<button type="button" class="nvs-btn" data-medit="'+cur+'">تعديل الخامة</button>':'')+'<button type="button" class="nvs-btn" data-cmd="lib.mats">المكتبة العامة</button><button type="button" class="nvs-btn" data-cmd="mat.fromcat">من دليل الخامات</button>'+(L.length?'':'<button type="button" class="nvs-btn" data-cmd="mat.starter">خامات عرض جاهزة</button>')+'</div></div>';
    var m=E.matOf(o);
    if(m)h+='<details class="nvs-sec"><summary>لون سريع (بدون مكتبة)</summary>'+
      fld('اللون الأساسي Base Color','<input type="color" id="nvmC" value="'+m.c+'">')+
      fld('الخشونة Roughness <output id="nvmRo">'+Math.round(m.r*100)+'</output>','<input type="range" id="nvmR" min="0" max="100" value="'+Math.round(m.r*100)+'">')+
      fld('معدنية Metallic <output id="nvmMo">'+Math.round(m.m*100)+'</output>','<input type="range" id="nvmM" min="0" max="100" value="'+Math.round(m.m*100)+'">')+
      '<div class="nvs-sw">'+PRESETS.map(function(p,i){return '<button type="button" data-cmd="mat.p'+i+'" title="'+esc(p[0])+'"><i style="background:'+p[1]+'"></i>'+esc(p[0])+'</button>';}).join('')+'</div>'+
      '<p class="nvs-note">اللون السريع يفصل العنصر عن خامة المكتبة.'+(o.userData.kind==='mfg'?' الظهر والمعادن والزجاج تبقى كما هي.':'')+'</p></details>';
  }else h+='<div class="nvs-sec">'+noSel()+'</div>';
  h+='<div class="nvs-sec"><h4>مكتبة خامات المشروع <small>'+L.length+'</small></h4>'+(L.length?L.map(function(d){
    return '<div class="nvs-node">'+swatch(d)+'<span class="nvs-nn">'+esc(d.name)+' <small>'+esc(d.tex&&d.tex.k&&d.tex.k!=='solid'?(d.tex.k==='img'?'صورة':E.MATKINDS[d.tex.k]):'سادة')+(d.cc?' · لامع':'')+(d.op?' · شفاف':'')+' · '+d.uses+' عنصر'+(d.src?' · من الدليل':'')+(d.gl?' · من المكتبة العامة':'')+(d.th&&d.th.length?' · '+d.th.join('/')+' مم':'')+'</small></span>'+
      '<button type="button" class="nvs-ic" data-medit="'+d.id+'" aria-label="تعديل">✎</button><button type="button" class="nvs-ic" data-mdup="'+d.id+'" aria-label="نسخ">⧉</button><button type="button" class="nvs-ic" data-mdel="'+d.id+'" aria-label="حذف">🗑</button></div>';}).join(''):'<p class="nvs-note">لا توجد خامات بعد.</p>')+
    '<p class="nvs-note">الصور الخامية (خشب، رخام، قماش، خرسانة) مولّدة رياضيًا وقابلة للتكرار بلا فواصل، أو من صورة تلتقطها لعينة حقيقية. حجم التكرار بالسنتيمتر الحقيقي، والألياف تتبع الضلع الأطول لكل قطعة.</p></div>';
  return h;
}
