function cadTree(){
  var all=CAD.all(),by={},bl={},ls={};E.layers().forEach(function(l){ls[l.id]=l;});
  var TN={line:'خطوط',pline:'خطوط متعددة',circle:'دوائر',arc:'أقواس',text:'نصوص',dim:'أبعاد'};
  all.forEach(function(e){by[e.t]=(by[e.t]||0)+1;bl[e.layer]=(bl[e.layer]||0)+1;});
  if(!all.length)return '<div class="nvs-empty">لوحة الرسم فارغة.<br><small>ابدأ بأداة من الشريط، أو اكتب في سطر الأوامر: line ثم 0,0 ثم @100,0</small></div>';
  return '<div class="nvs-sec"><h4>عناصر الرسم <small>'+all.length+'</small></h4><div class="nvs-kv">'+Object.keys(by).map(function(t){return '<div><span>'+(TN[t]||t)+'</span><b>'+by[t]+'</b></div>';}).join('')+'</div></div>'+
    '<div class="nvs-sec"><h4>حسب الطبقة <small>اضغط لتحديد عناصر الطبقة</small></h4>'+Object.keys(bl).map(function(id){var l=ls[id]||{name:id,color:'#999'};return '<div class="nvs-node"><button type="button" class="nvs-nn" data-cselL="'+id+'"><i style="background:'+l.color+'"></i>'+esc(l.name)+' <small>'+bl[id]+'</small></button></div>';}).join('')+'</div>'+
    '<div class="nvs-sec"><h4>المجسمات 3D <small>'+E.rawCount()+'</small></h4><p class="nvs-note">لعرض المجسمات انتقل إلى 3D من شريط العرض.</p></div>';
}
function pTree(){
  var list=E.list(),s=E.sel(),ls={};E.layers().forEach(function(l){ls[l.id]=l;});
  if(list.length)return pTree6(ls);
  if(!list.length)return '<div class="nvs-empty">المشهد فارغ.<br><small>أنشئ عنصرًا من قائمة «إنشاء».</small></div>';
  return '<div class="nvs-sec"><h4>عناصر المشهد <small>'+list.length+'</small></h4>'+list.map(function(o){
    var u=o.userData,l=ls[u.layer]||{name:'0',color:'#999'},inf=u.kind==='mfg'?E.info(o):null;
    return '<div class="nvs-node'+(o===s?' on':'')+'"><button type="button" class="nvs-nn" data-osel="'+u.id+'"><i style="background:'+l.color+'"></i>'+esc(o.name)+
      ' <small>'+esc(l.name)+(inf?' · '+inf.parts+' قطعة':'')+(u.locked?' · مقفل':'')+'</small></button>'+
      '<button type="button" class="nvs-ic'+(u.hidden?' off':'')+'" data-ohide="'+u.id+'" aria-label="إظهار أو إخفاء">'+(u.hidden?'🚫':'👁')+'</button>'+
      '<button type="button" class="nvs-ic" data-olock="'+u.id+'" aria-label="قفل">'+(u.locked?'🔒':'🔓')+'</button></div>';
  }).join('')+'</div>';
}
function pTree6(ls){
  var T=E.tree(),cx=E.ctx(),n=0,KN={group:'▣',mfg:'▤',prim:'◆'};
  function row(t,d){n++;var l=ls[t.layer]||{name:'0',color:'#999'},open=cx&&cx.userData.id===t.id;
    var h='<div class="nvs-node'+(t.sel?' on':'')+(open?' ctx':'')+'" style="padding-inline-start:'+(d*14)+'px">'+
      (t.children?'<button type="button" class="nvs-ic" data-ogrp="'+t.id+'" title="'+(open?'إنهاء التحرير':'تحرير المحتوى')+'" aria-label="تحرير المجموعة">'+(open?'▾':'▸')+'</button>':'')+
      '<button type="button" class="nvs-nn" data-osel="'+t.id+'"><i style="background:'+l.color+'"></i>'+KN[t.kind]+' '+esc(t.name)+
      ' <small>'+(t.comp?'مكوّن · ':'')+(t.children?t.children.length+' عنصر · ':'')+esc(l.name)+(t.locked?' · مقفل':'')+'</small></button>'+
      '<button type="button" class="nvs-ic'+(t.hidden?' off':'')+'" data-ohide="'+t.id+'" aria-label="إظهار أو إخفاء">'+(t.hidden?'🚫':'👁')+'</button>'+
      '<button type="button" class="nvs-ic" data-olock="'+t.id+'" aria-label="قفل">'+(t.locked?'🔒':'🔓')+'</button>'+
      '<button type="button" class="nvs-ic" data-oren="'+t.id+'" aria-label="إعادة تسمية" title="إعادة تسمية">✎</button></div>';
    if(t.children&&(open||d>0||(cx&&isAnc(t,cx.userData.id))))t.children.forEach(function(c){h+=row(c,d+1);});
    return h;}
  function isAnc(t,id){return (t.children||[]).some(function(c){return c.id===id||isAnc(c,id);});}
  var body=T.map(function(t){return row(t,0);}).join(''),cl=E.compList();
  return (cx?'<div class="nvs-warn">✎ تحرير «'+esc(cx.name)+'» <button type="button" class="nvs-btn" data-cmd="mod.closegroup">إنهاء التحرير</button></div>':'')+
    '<div class="nvs-sec"><h4>عناصر المشهد Hierarchy <small>'+T.length+'</small></h4>'+body+
    '<div class="nvs-acts"><button type="button" class="nvs-btn" data-cmd="mod.multi">تحديد متعدد'+(E.multiMode()?' ✓':'')+'</button><button type="button" class="nvs-btn" data-cmd="mod.selall">تحديد الكل</button><button type="button" class="nvs-btn" data-cmd="mod.showall">إظهار الكل</button></div></div>'+
    '<div class="nvs-sec"><h4>المكوّنات Components <small>'+cl.length+'</small></h4>'+(cl.length?cl.map(function(c){return '<div class="nvs-node"><span class="nvs-nn">'+esc(c.name)+' <small>'+c.n+' نسخة · '+c.parts+' عنصر</small></span><button type="button" class="nvs-btn" data-cins="'+c.id+'">＋ نسخة</button></div>';}).join(''):'<p class="nvs-note">حدد مجموعة ثم «تحويل إلى مكوّن»؛ أي تعديل داخل نسخة يُطبَّق على كل النسخ.</p>')+'</div>';
}
function pInsp(){
  var o=E.sel();if(!o)return noSel();
  var i=E.info(o),p=E.project();
  return '<div class="nvs-sec"><h4>فاحص العنصر Object Inspector</h4><div class="nvs-kv">'+
    kv('المعرّف',esc(i.id))+kv('النوع',i.kind==='mfg'?'قطعة تصنيع ('+esc(NVM.KINDS[o.userData.mfg.kind]||'')+')':i.kind==='group'?(i.comp?'مكوّن: '+esc(i.comp):'مجموعة')+' ('+i.children+' عنصر)':'شكل ('+esc(o.userData.prim.k)+(i.op?' · '+i.op:'')+(i.bev?' · '+(i.bev.k==='round'?'تدوير':'شطف')+' '+U.fmt(i.bev.r):'')+')')+kv('الطبقة',esc(i.layer))+
    kv('عدد الأجزاء المرسومة',i.meshes)+(i.kind==='mfg'?kv('قطع التصنيع',i.parts)+kv('أبواب/أدراج متحركة',i.movers):'')+kv('المثلثات',i.tri.toLocaleString('en-US'))+
    kv('الحيز',[0,1,2].map(function(k){return U.to(i.world[k]);}).join(' × ')+' '+U.name())+kv('الحالة',(i.hidden?'مخفي':'ظاهر')+' · '+(i.locked?'مقفل':'غير مقفل'))+
    '</div></div><div class="nvs-sec"><h4>المشروع</h4><div class="nvs-kv">'+kv('الاسم',esc(p?p.name:''))+kv('العناصر',E.list().length)+kv('التخزين',NV.Store.mode==='idb'?'IndexedDB على هذا الجهاز':'localStorage (مساحة محدودة)')+'</div></div>';
}

/* ---------------- تبويب التصنيع (قائمة القطع والإكسسوارات) ---------------- */
var lastCut=null;
function pMfg(){
  var d=E.cutData();lastCut=d;lastParts=d?E.mfgParts():null;
  if(!d)return '<div class="nvs-empty">لا توجد قطع تصنيع ظاهرة في المشهد.<br><small>أضف دولابًا أو سريرًا أو كومدينو أو تسريحة أو طاولة تلفزيون أو جزامة من «إنشاء».</small></div>';
  var h='<div class="nvs-sec"><h4>قائمة القطع <small>'+esc(d.single?d.names[0]:'كل قطع التصنيع الظاهرة ('+d.names.length+')')+'</small></h4>';
  h+='<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-cmd="mfg.list">الجدول التفصيلي والتعديل اليدوي</button><button type="button" class="nvs-btn" data-cmd="mfg.hinges">المفصلات والأدراج والسحاب</button></div>';
  if(d.manual)h+='<div class="nvs-warn bm-man">✎ القائمة تشمل تعديلاتك اليدوية (مقاسات/استبعاد/قطع إضافية) — التفاصيل في الجدول التفصيلي.</div>';
  try{var bc=E.bom();if(bc&&bc.conflicts)h+='<div class="nvs-warn">⚠ تغيّر التصميم بعد تعديلات يدوية: '+bc.conflicts+' تعارض بانتظار قرارك — <button type="button" class="nvs-btn" data-cmd="mfg.list">مراجعة</button></div>';}catch(e){}
  d.warn.forEach(function(w){h+='<div class="nvs-warn">⚠ '+esc(w)+'</div>';});
  h+='<div class="nvs-chips">'+d.tot.map(function(t){return '<span>ألواح '+NVM.R1(t.t)+' مم: <b>'+t.area+' م²</b> ≈ <b>'+t.sheets+'</b> لوح 244×122 · '+t.pieces+' قطعة</span>';}).join('')+'<span>شريط حواف: <b>'+d.edgeM+' م</b></span></div>';
  h+='<div class="nvs-tw"><table class="nvs-tbl"><thead><tr><th>م</th><th>القطعة</th><th>الطول سم</th><th>العرض سم</th><th>السمك مم</th><th>العدد</th><th>الألياف</th><th>الأرقام</th></tr></thead><tbody>'+
    d.rows.map(function(r,i){return '<tr><td>'+(i+1)+'</td><td>'+esc(r.name)+'</td><td>'+r.L+'</td><td>'+r.W+'</td><td>'+r.t+'</td><td><b>'+r.q+'</b></td><td>'+(r.lock?'ثابتة':'تدور')+'</td><td class="nvs-ids">'+esc(idsFor(r).join(' '))+'</td></tr>';}).join('')+'</tbody></table></div>';
  var br=window.NVBridge,mats=br?br.mats():[],map=br?br.mapGet():{};
  h+='<h4>الإكسسوارات'+(br?' <small>اربط كل بند بخامة من دليل الخامات</small>':'')+'</h4><div class="nvs-tw"><table class="nvs-tbl"><thead><tr><th>البند</th><th>العدد</th>'+(br?'<th>الخامة في الدليل</th>':'')+'</tr></thead><tbody>'+
    d.hw.map(function(x,i){var cur=map[x.name]||'';return '<tr><td>'+esc(x.name)+'</td><td><b>'+x.qty+'</b> '+esc(x.unit)+'</td>'+(br?'<td><select data-hwi="'+i+'"><option value="">— غير مربوط —</option>'+mats.map(function(m){return '<option value="'+esc(m.id)+'"'+(m.id===cur?' selected':'')+'>'+esc(m.label)+'</option>';}).join('')+'</select></td>':'')+'</tr>';}).join('')+'</tbody></table></div><div class="nvs-acts">';
  if(br)h+=sendVerNote();
  if(br)h+='<select id="nvsPcTh" aria-label="سُمك الألواح">'+d.tot.map(function(t){return '<option value="'+t.t+'">سُمك '+NVM.R1(t.t)+' مم ('+t.area+' م²)</option>';}).join('')+'</select><button type="button" class="nvs-btn pri" id="nvsPcSend">إرسال إلى حاسبة الألواح</button><button type="button" class="nvs-btn" id="nvsBomSend">إضافة الإكسسوارات إلى الحصر</button>'+(br.bomAddItem&&E.link&&E.link()&&E.link().ik!=null?'<button type="button" class="nvs-btn pri" id="nvsBomItem">إضافة الإكسسوارات إلى حصر البند في الطلب '+esc(E.link().no||'')+'</button>':'');
  if(br&&br.exFromStudio&&d.hw.some(function(x){return x.k==='glass'||x.k==='mirror';}))h+='<button type="button" class="nvs-btn pri" id="nvsExSend">طلب تصنيع خارجي للزجاج والمرايا</button>';
  if(br)h+='<button type="button" class="nvs-btn" data-cmd="lib.automap">ربط تلقائي من مكتبة الإكسسوارات</button><button type="button" class="nvs-btn" data-cmd="lib.acc">مكتبة الإكسسوارات</button>';
  h+='<button type="button" class="nvs-btn" data-cmd="mfg.csv">CSV</button><button type="button" class="nvs-btn" data-cmd="mfg.print">طباعة</button><button type="button" class="nvs-btn" data-cmd="mfg.doors">فتح/إغلاق الأبواب</button></div>'+
    '<p class="nvs-note">الحسابات من هندسة القطع المولّدة (سُمك اللوح، خلوص الأبواب 3 مم، مجاري أدراج قياسية).</p></div>'+mfgSec();
  return h;
}
/* V43: هل الحصر المرسَل من الإصدار المعتمد؟ */
function sendVer(){var v=E.verState&&E.verState();return {ap:v&&v.approved?v.approved:0,changed:!!(v&&v.approved&&v.changed)};}
function sendVerNote(){var v=sendVer();
  if(v.ap&&!v.changed)return '<div class="nvs-note nvs-good nvs-sver">✓ الحصر مطابق للإصدار المعتمد '+v.ap+' — البنود المرسلة تحمل رقمه.</div>';
  if(v.ap)return '<div class="nvs-warn bad nvs-sver">⚠ التصميم الحالي تغيّر بعد اعتماد الإصدار '+v.ap+' — الحصر أدناه ليس حصر الإصدار المعتمد. الإرسال يحتاج تأكيدًا، أو أعد المشروع للإصدار المعتمد من «الإصدارات».</div>';
  return '<div class="nvs-note nvs-sver">لا يوجد إصدار معتمد بعد — الحصر من التصميم الحالي (مسودة).</div>';}
function verGuard(btn){var v=sendVer();if(!v.changed||btn.dataset.ok)return true;btn.dataset.ok='1';btn.textContent='تأكيد الإرسال رغم الاختلاف عن الإصدار '+v.ap;toast('التصميم الحالي يختلف عن الإصدار المعتمد '+v.ap+' — اضغط مرة أخرى للتأكيد');return false;}
function verTag(){var v=sendVer();return v.ap&&!v.changed?' (الإصدار '+v.ap+')':(v.ap?' (معدّل بعد الإصدار '+v.ap+')':' (مسودة)');}
function bindMfg(){
  var d=lastCut,br=window.NVBridge;if(!d||!br)return;
  $$('#nvsTab [data-hwi]').forEach(function(s){s.onchange=function(){br.mapSet(d.hw[+s.dataset.hwi].name,s.value);toast(s.value?'رُبط البند بالخامة':'أُلغي الربط');};});
  var ps=$('#nvsPcSend');if(ps)ps.onclick=function(){
    if(!verGuard(ps))return;
    var th=parseFloat($('#nvsPcTh').value),pcs=d.rows.filter(function(r){return r.t===th;}).map(function(r){return {n:r.name,l:r.L,w:r.W,q:r.q,lock:!!r.lock};});
    if(br.pcSet(pcs,th))setFull(false);
  };
  var bi=$('#nvsBomItem');if(bi)bi.onclick=function(){
    if(!verGuard(bi))return;var l=E.link(),m2=br.mapGet(),rows=[],un=[];
    d.hw.forEach(function(x){if(m2[x.name])rows.push({mat:m2[x.name],qty:x.qty,note:'من الاستوديو: '+x.name});else un.push(x.name);});
    if(!rows.length){toast('اربط بنود الإكسسوارات بخامات الدليل أولًا من عمود «الخامة في الدليل»');return;}
    var r=br.bomAddItem(l.oid,l.ik,rows,'الاستوديو'+verTag());if(typeof r==='string'){toast(r);return;}
    toast('أُضيف '+r.added+' بند إلى حصر «'+(l.iname||'البند')+'» في الطلب '+l.no+' — إصدار الحصر '+r.n+(un.length?' — '+un.length+' بند غير مربوط':''));
  };
  var bx=$('#nvsExSend');if(bx)bx.onclick=function(){
    if(!verGuard(bx))return;var l=E.link&&E.link(),items=[];
    d.hw.forEach(function(x){if(x.k!=='glass'&&x.k!=='mirror')return;var m=/([\d.]+)\s*×\s*([\d.]+)\s*سم/.exec(x.name),t=/(\d+(?:\.\d+)?)\s*مم/.exec(x.name);
      items.push({kind:x.k,desc:m?x.name.slice(0,m.index).replace(/\s*\d+(?:\.\d+)?\s*مم\s*$/,'').trim():x.name,w:m?m[1]:'',h:m?m[2]:'',thk:m&&t?t[1]:'',qty:x.qty,proc:''});});
    var r=br.exFromStudio({items:items,oid:l?l.oid:'',iname:l?(l.iname||''):'',ver:verTag()});if(typeof r==='string'){toast(r);return;}
    toast('أُنشئ '+r.join('، ')+' في «التصنيع الخارجي» (شاشة المشتريات) — يحتاج قياسًا بالموقع ومراجعة قبل الاعتماد');
  };
  var bs=$('#nvsBomSend');if(bs)bs.onclick=function(){
    if(!verGuard(bs))return;
    var m2=br.mapGet(),rows=[],un=[],tg=verTag();
    d.hw.forEach(function(x){if(m2[x.name])rows.push({mat:m2[x.name],qty:x.qty,note:'من الاستوديو: '+x.name+tg});else un.push(x.name);});
    if(!rows.length){toast('اربط بنودًا بخامات الدليل أولًا من عمود «الخامة في الدليل»');return;}
    var r=br.bomAdd(rows);if(typeof r==='string'){toast(r);return;}
    setFull(false);toast('أُضيف '+r+' بند إلى الحصر'+(un.length?' — '+un.length+' بند غير مربوط':''));
  };
}
function csvOf(d){
  var q=function(x){x=String(x==null?'':x);return /[",\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x;};
  var Ls=[['القطعة','الطول (سم)','العرض (سم)','السمك (مم)','العدد','الألياف','طول الحواف للقطعة (سم)'].map(q).join(',')];
  d.rows.forEach(function(r){Ls.push([r.name,r.L,r.W,r.t,r.q,r.lock?'ثابتة':'تدور',NVM.R1(r.eb)].map(q).join(','));});
  Ls.push('');Ls.push(['الإكسسوار','العدد','الوحدة'].map(q).join(','));
  d.hw.forEach(function(h){Ls.push([h.name,h.qty,h.unit].map(q).join(','));});
  return '﻿'+Ls.join('\r\n');
}
function printCut(d){
  lastParts=E.mfgParts();
  var t='<h2>قائمة القطع — '+esc(d.single?d.names[0]:d.names.join('، '))+'</h2><table><thead><tr><th>م</th><th>القطعة</th><th>الطول (سم)</th><th>العرض (سم)</th><th>السمك (مم)</th><th>العدد</th><th>الألياف</th><th>الأرقام</th></tr></thead><tbody>'+
    d.rows.map(function(r,i){return '<tr><td>'+(i+1)+'</td><td>'+esc(r.name)+'</td><td>'+r.L+'</td><td>'+r.W+'</td><td>'+r.t+'</td><td><b>'+r.q+'</b></td><td>'+(r.lock?'ثابتة':'تدور')+'</td><td class="nvs-ids">'+esc(idsFor(r).join(' '))+'</td></tr>';}).join('')+'</tbody></table>'+
    '<p>'+d.tot.map(function(x){return 'ألواح '+NVM.R1(x.t)+' مم: '+x.area+' م² ≈ '+x.sheets+' لوح';}).join(' — ')+' — شريط حواف: '+d.edgeM+' م</p>'+
    '<h3>الإكسسوارات</h3><table><thead><tr><th>البند</th><th>العدد</th></tr></thead><tbody>'+d.hw.map(function(x){return '<tr><td>'+esc(x.name)+'</td><td><b>'+x.qty+'</b> '+esc(x.unit)+'</td></tr>';}).join('')+'</tbody></table>';
  var br=window.NVBridge;setFull(false);if(br&&br.sheet)br.sheet(t);else window.print();
}

/* ---------------- أحداث اللوحة ---------------- */
function onPanelClick(e){
  var b=e.target.closest('button,[data-osel]');if(!b)return;
  if(cadOn()&&b.dataset.cact)return;
  var a=b.dataset.act,o=E.sel();
  if(b.dataset.cmd){runCmd(b.dataset.cmd);return;}
  if(m7Panel(b))return;
  if(b.dataset.cselL){CAD.selectIds(CAD.all().filter(function(e){return e.layer===b.dataset.cselL;}).map(function(e){return e.id;}));return;}
  if(b.dataset.cact||b.closest('[data-cact]'))return;
  if(a==='props-apply'&&o){
    var p=[NV.num($('#nvpPx').value),NV.num($('#nvpPy').value),NV.num($('#nvpPz').value)].map(function(v,i){return isNaN(v)?o.position.getComponent(i):U.from(v);});
    var r=[NV.num($('#nvpRx').value),NV.num($('#nvpRy').value),NV.num($('#nvpRz').value)].map(function(v,i){return isNaN(v)?o.rotation.toArray()[i]:v*Math.PI/180;});
    E.setProps({name:$('#nvpName').value,layer:$('#nvpLayer').value,p:p,r:r,hidden:$('#nvpHid').checked,locked:$('#nvpLock').checked},'خصائص '+o.name);toast('طُبّقت الخصائص');return;
  }
  if(a==='spec-apply'){var sp=readSpec();if(sp){E.setSpec(sp);toast('أُعيد بناء القطعة وقائمة القطع');}return;}
  if(a==='unit-add'||a==='unit-del'){
    var s3=readSpec();if(!s3||!s3.units)return;
    if(a==='unit-add')s3.units.push({k:'door',w:60,n:1});else{if(s3.units.length<2){toast('يلزم وحدة واحدة على الأقل');return;}s3.units.splice(+b.dataset.i,1);}
    s3.W=s3.units.reduce(function(x,u){return x+u.w;},0);E.setSpec(s3,a==='unit-add'?'إضافة وحدة مطبخ':'حذف وحدة مطبخ');return;
  }
  if(a==='mod-add'||a==='mod-del'){
    var s2=readSpec();if(!s2)return;
    if(a==='mod-add')s2.modules.push({k:'door',n:1,w:1});else{if(s2.modules.length<2){toast('يلزم وحدة واحدة على الأقل');return;}s2.modules.splice(+b.dataset.i,1);}
    E.setSpec(s2,a==='mod-add'?'إضافة وحدة':'حذف وحدة');return;
  }
  if(a==='dims-apply'&&o){
    var w=NV.num($('#nvdW').value),h=NV.num($('#nvdH').value),dd=NV.num($('#nvdD').value);
    if([w,h,dd].some(isNaN)){toast('أدخل أرقامًا صحيحة');return;}E.setDims(U.from(w),U.from(h),U.from(dd));return;
  }
  if(a==='layer-add'){var n=prompt('اسم الطبقة:','طبقة جديدة');if(n&&n.trim())E.layerAdd(n.trim());return;}
  if(b.dataset.lren){var L0=E.layers().filter(function(l){return l.id===b.dataset.lren;})[0],nn=prompt('اسم الطبقة:',L0?L0.name:'');if(nn&&nn.trim())E.layerSet(b.dataset.lren,{name:nn.trim()});return;}
  if(b.dataset.lvis){var l1=E.layers().filter(function(l){return l.id===b.dataset.lvis;})[0];E.layerSet(l1.id,{visible:!l1.visible});return;}
  if(b.dataset.llock){var l2=E.layers().filter(function(l){return l.id===b.dataset.llock;})[0];E.layerSet(l2.id,{locked:!l2.locked});return;}
  if(b.dataset.lmove&&o){E.setProps({layer:b.dataset.lmove},'نقل '+o.name+' إلى طبقة');return;}
  if(b.dataset.ldel){if(confirm('حذف الطبقة؟ ستُنقل عناصرها إلى الطبقة 0.'))E.layerDel(b.dataset.ldel);return;}
  if(b.dataset.osel){var t0=E.byId(b.dataset.osel);if(t0&&E.multiMode())E.toggleSel(t0);else selTree(b.dataset.osel);return;}
  if(b.dataset.ogrp){var g0=E.byId(b.dataset.ogrp);if(E.ctx()===g0)E.closeGroup();else{selTree(b.dataset.ogrp);E.openGroup(E.byId(b.dataset.ogrp));}renderPanel(true);return;}
  if(b.dataset.oren){selTree(b.dataset.oren);var r0=E.sel(),nn0=prompt('الاسم:',r0.name);if(nn0&&nn0.trim())E.setProps({name:nn0.trim()},'إعادة تسمية '+nn0.trim());return;}
  if(b.dataset.cins){E.compInsert(b.dataset.cins);return;}
  if(b.dataset.ohide){selTree(b.dataset.ohide);var x=E.sel();E.setProps({hidden:!x.userData.hidden},(x.userData.hidden?'إظهار ':'إخفاء ')+x.name);return;}
  if(b.dataset.olock){selTree(b.dataset.olock);var y=E.sel();E.setProps({locked:!y.userData.locked},(y.userData.locked?'فك قفل ':'قفل ')+y.name);return;}
}
function selTree(id){
  var o=E.byId(id);if(!o)return;var p=o.parent;
  if(p&&p.userData&&p.userData.kind==='group'){if(E.ctx()!==p)E.openGroup(p);}
  else if(E.ctx()){while(E.ctx())E.closeGroup();}
  E.select(E.byId(id));
}
function onPanelInput(e){
  var t=e.target;
  if(t.id==='nvmC'){E.setMat({c:t.value},null,true);}
  else if(t.id==='nvmR'){$('#nvmRo').textContent=t.value;E.setMat({r:t.value/100},null,true);}
  else if(t.id==='nvmM'){$('#nvmMo').textContent=t.value;E.setMat({m:t.value/100},null,true);}
  else if(t.id==='nvlK'){$('#nvlKo').textContent=t.value+'%';NV.set('lightK',+t.value);}
  else if(t.id==='nveExp'){$('#nveExpo').textContent=(+t.value).toFixed(2);E.setEnv({exp:+t.value},true);}
  else if(t.id==='nveRot'){$('#nveRoto').textContent=t.value+'°';}
  else if(t.id==='nveAz'){$('#nveAzo').textContent=t.value+'°';E.setEnv({az:+t.value},true);}
  else if(t.id==='nveEl'){$('#nveElo').textContent=t.value+'°';E.setEnv({el:+t.value},true);}
  else if(t.id==='nveBg'){E.setEnv({bg:t.value},true);}
  else if(t.id==='nvkL'){$('#nvkLo').textContent=t.value+' مم';E.lens(+t.value);}
}
function onPanelChange(e){
  var t=e.target,o=E.sel();
  if((t.id==='nvmC'||t.id==='nvmR'||t.id==='nvmM')&&o){E.commit('خامة '+o.name);}
  else if(t.id==='nvlSh'){NV.set('shadows',t.checked);}
  else if(t.id==='nveExp'||t.id==='nveAz'||t.id==='nveEl'||t.id==='nveBg'){E.commit(t.id==='nveBg'?'لون الخلفية':t.id==='nveExp'?'التعريض':'اتجاه الشمس');}
  else if(t.id==='nveTone'){E.setEnv({tone:t.checked?'aces':'none'});}
  else if(t.id==='nveRot'){E.setEnv({hdrRot:+t.value});}
  else if(t.id==='nveHdrBg'){E.setEnv({hdrBg:t.checked});}
  else if(t.id==='nveHdrF'){E.hdrLoad(t.files&&t.files[0]);t.value='';}
  else if(t.id==='nveRefl'){E.setEnv({refl:t.checked});if(t.checked)toast('الانعكاسات تُحمَّل مرة واحدة وقد تبطئ الهواتف الضعيفة قليلًا');}
  else if(t.dataset.lact){E.activeLayer(t.dataset.lact);}
  else if(t.dataset.lcol){E.layerSet(t.dataset.lcol,{color:t.value});}
  else if(t.dataset.llw){E.layerSet(t.dataset.llw,{lw:+t.value});}
}

