function m3Act(a,b){
  if(a==='ext-go'){var h=val('nvxH',NaN);if(isNaN(h)||h<=0){toast('أدخل مسافة بثق صحيحة');return;}var n=doExtrude(U.from(h),$('#nvxPl').value,U.from(val('nvxB',0)),!!($('#nvxLk')&&$('#nvxLk').checked));if(n)closePop();return;}
  if(a==='arr-go'){var n2=Math.round(val('nvaN',0));if(!(n2>=2&&n2<=200)){toast('العدد بين 2 و 200');return;}
    var made=$('#nvaK').value==='pol'?E.array('polar',{n:n2,angle:val('nvaA',360),c:[U.from(val('nvaCx',0)),U.from(val('nvaCz',0))]}):E.array('linear',{n:n2,d:[U.from(val('nvaX',0)),U.from(val('nvaY',0)),U.from(val('nvaZ',0))]});
    if(made){closePop();toast('أُنشئت '+made+' نسخة');}return;}
  if(a==='purge'){var np=E.compPurge();if(np)toast('حُذف '+np+' مكوّن غير مستخدم');showComps();return;}
  if(a==='al'){E.align(+b.dataset.ax,b.dataset.w);return;}
  if(a==='dist'){E.distribute(+b.dataset.ax);return;}
  if(a==='bev-go'){var k=$('#nvbK').value,r=U.from(val('nvbR',0));if(k!=='none'&&!(r>0)){toast('أدخل مقدارًا أكبر من صفر');return;}E.setBevel(k,r);if(k==='none'||E.sel().userData.prim.bev)closePop();return;}
  if(a==='mv-go'||a==='mv-copy'){var d=[U.from(val('nvmvX',0)),U.from(val('nvmvY',0)),U.from(val('nvmvZ',0))];if(a==='mv-copy')E.copyMove(d);else E.moveBy(d);closePop();return;}
}
