      pg.text(b1.x+b1.w/2,bx.y+bx.h-2,3,'واجهة أمامية',{align:'c'});pg.text(b2.x+b2.w/2,bx.y+bx.h-2,3,'قطاع جانبي',{align:'c'});
      pg.ops.forEach(function(op){if(op.t==='text'&&op.str&&/^Scale/.test(op.str))op.str='Scale 1:'+sc;});pg._scale=sc;
      pg.ops.push({t:'text',x:bx.x,y:bx.y+bx.h-2,s:2.6,str:'Scale 1:'+sc+'  (cm)'});pages.push(pg);
