      for(var i=0;i<rows.length;i+=36){var pg2=new SH.Page(210,297),b3=SH.frame(pg2,{title:x.name,sub:'جدول القطع (مم) — الشريط: طول1 طول2 عرض1 عرض2',date:date,n:0,N:0});
        SH.table(pg2,b3.x,b3.y+b3.h,[['الرقم',22],['القطعة',40],['الطول',18],['العرض',18],['السمك',14],['مقاس القص',26],['ألياف',12],['شريط',16],['ثقوب',14]],rows.slice(i,i+36),{fs:2.6,rh:6});pages.push(pg2);}
