        ps.slice(j,j+6).forEach(function(p,q){SH.partBox(pg3,p,{x:b4.x+(q%2)*b4.w/2,y:b4.y+b4.h-(Math.floor(q/2)+1)*b4.h/3,w:b4.w/2-3,h:b4.h/3-3,qr:(o.qr&&E.projId())?NV.QR.partCode(E.projId(),p.id,E.labelVer()):null});pg3.rect(b4.x+(q%2)*b4.w/2,b4.y+b4.h-(Math.floor(q/2)+1)*b4.h/3,b4.w/2-3,b4.h/3-3,{lw:0.1,col:'#bbb'});});
