  if(!cat.length)h+='<div class="nvs-warn bad">دليل الخامات في التطبيق فارغ — أضف خاماتك وأسعارها من قسم «الخامات» ثم اربطها هنا.</div>';
  if(R.incomplete)h+='<div class="nvs-warn bad">⚠ '+R.incomplete+' بند غير مسعّر (غير مربوط، أو بلا سعر في الدليل، أو بوحدة لا تناسب). الإجمالي ناقص ولا يصلح عرض سعر قبل إكماله.</div>';
  var sm=R.sums;
  h+='<table class="nvs-tbl nvs-sum"><tbody>'+
    '<tr><td>المواد (من أسعار الدليل)</td><td>'+money(sm.mat)+'</td></tr><tr><td>التشغيل (أجورك × الكميات الفعلية)</td><td>'+money(sm.labor)+'</td></tr>'+
    '<tr><td><b>التكلفة المباشرة</b></td><td><b>'+money(sm.direct)+'</b></td></tr><tr><td>مصاريف غير مباشرة '+S.overhead+'%</td><td>'+money(sm.overhead)+'</td></tr>'+
    '<tr><td><b>إجمالي تكلفة التصنيع</b></td><td><b>'+money(sm.cost)+'</b></td></tr>'+
    '<tr class="hl"><td><b>'+(sm.mode==='sale'?'سعر البيع المتفق عليه':'سعر البيع المقترح')+' (قبل الضريبة)</b></td><td><b>'+money(sm.price)+'</b>'+(R.incomplete?' <small class="bad">ناقص</small>':'')+'</td></tr>'+
    '<tr><td>'+esc(NV.COST.profitLabel(R))+'</td><td class="'+(sm.profit<0?'bad':'')+'">'+money(sm.profit)+'</td></tr>'+
    '<tr><td>نسبة الإضافة على التكلفة · هامش الربح من البيع</td><td class="'+(sm.profit<0?'bad':'')+'">'+sm.markupPct+'% · '+sm.marginPct+'%</td></tr></tbody></table>'+
    (sm.profit<0?'<div class="nvs-warn bad">سعر البيع أقل من تكلفة التصنيع — خسارة '+money(-sm.profit)+'.</div>':'')+(sm.badMargin?'<div class="nvs-warn bad">هامش الربح من سعر البيع يجب أن يكون أقل من 100%.</div>':'')+
    '<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-cmd="cost.send">إرسال إلى بطاقة تكلفة طلب</button><button type="button" class="nvs-btn" data-cmd="cost.print">طباعة</button><button type="button" class="nvs-btn" data-cmd="cost.csv">CSV</button></div></div>';
  var catById={};cat.forEach(function(m){catById[m.id]=m;});
  h+=frozenCost(R);
  function row(l){
    var cm=catById[map[l.key]],pd=cm&&cm.pt?cm.pt:'',old=pd&&(Date.now()-Date.parse(pd))>90*864e5;
    var calc=l.status==='ok'?l.qty+' '+esc(l.matUnit||'')+' × '+money(l.price)+'<br><b>'+money(l.total)+'</b>'+(cm?'<br><small class="'+(old?'bad':'nvs-mu')+'">'+(pd?'سعر الدليل بتاريخ '+esc(pd)+(old?' — أقدم من 90 يومًا، راجعه':''):'سعر الدليل بلا تاريخ')+'</small>':''):'<span class="bad">✗ '+esc(NV.COST.STATN[l.status])+'</span>'+(l.qty!=null?'<br><small>'+l.qty+' '+esc(l.matUnit||'')+'</small>':'');
    return '<tr><td><b>'+esc(l.name)+'</b><br><small>'+l.sq+' '+esc(l.su)+(l.note?' · '+esc(l.note):'')+'</small></td><td><select data-ck="'+esc(l.key)+'" aria-label="الخامة في الدليل">'+matOpts(map[l.key])+'</select></td><td class="nvs-calc">'+calc+'</td></tr>';
  }
  var G=[['boards','الألواح'],['bands','شريط الحواف'],['hw','الإكسسوارات والتنجيد والأسطح']];
