/* ---------------- V7: محرر الخامات، الأضواء، الإخراج ---------------- */
var MED=null,LED=null,lastRender=null;
function m7Panel(b){
  var d=b.dataset;
  if(d.mrole){matRole=d.mrole;renderPanel(true);return true;}
  if(d.mapply){if(needSel())E.matApply(d.mapply,matRole);return true;}
  if(d.medit){matEditor(d.medit);return true;}
  if(d.mdup){E.matDup(d.mdup);return true;}
  if(d.mdel){var md=E.matGet(d.mdel);if(md&&confirm('حذف الخامة «'+md.name+'» من مكتبة المشروع؟'))E.matDel(d.mdel);return true;}
  if(d.lon){var L=E.lights().filter(function(x){return x.id===d.lon;})[0];if(L)E.lightSet(L.id,{on:L.on===false});return true;}
  if(d.ledit){lightEditor(d.ledit);return true;}
  if(d.ldel){E.lightDel(d.ldel);return true;}
  if(d.kgo){E.camGo(d.kgo);return true;}
  if(d.kup){E.camUpdate(d.kup);toast('حُدّثت الكاميرا من العرض الحالي');return true;}
  if(d.kren){var c=E.cams().filter(function(x){return x.id===d.kren;})[0],n=c&&prompt('اسم الكاميرا:',c.name);if(n&&n.trim())E.camRename(d.kren,n.trim());return true;}
  if(d.kdel){E.camDel(d.kdel);return true;}
  if(d.m7==='bgreset'){E.setEnv({bg:''});return true;}
  if(d.m7==='hdroff'){E.setEnv({hdr:'',hdrName:'',hdrBg:false});return true;}
  return false;
}
