function fxIn(id,v,ph){return '<input id="'+id+'" dir="ltr" value="'+esc(v||'')+'" placeholder="'+esc(ph)+'">';}
var FXN='<p class="fe-note">المعادلات بالمليمتر: W H D (أبعاد الجسم)، t (السماكة)، L (المتاح في التقسيم)، h (ارتفاع القسم)، ومتغيراتك. مثال: W/3 · L/2-10 · h-350. السحب أو المقاس اليدوي يلغي معادلة التقسيم.</p>';
function nin2(id,v){return '<input id="'+id+'" type="number" inputmode="numeric" min="0" max="12" step="1" value="'+v+'">';}
function kv(o){return Object.keys(o).map(function(k){return [k,o[k]];});}
function val(id){var e=$('#'+id);return e?e.value:'';}
function chk(id){var e=$('#'+id);return !!(e&&e.checked);}
function list(){
  var b=$('#feList');if(!b)return;var s=st.spec,h='<ul class="fe-tree"><li><button type="button" data-fsel="body" class="'+(st.sel==='body'?'on':'')+'">▣ '+esc(s.name||'الجسم')+' — '+U(s.W)+'×'+U(s.H)+'×'+U(s.D)+'</button>';
  (function w(n,lab){
    h+='<ul><li><button type="button" data-fsel="zone:'+n.id+'" class="'+(st.sel==='zone:'+n.id?'on':'')+'">'+(n.dir?(n.dir==='v'?'⫴ تقسيم رأسي':'☰ تقسيم أفقي'):'□ قسم')+' '+lab+'</button>';
    n.items.forEach(function(it){h+='<ul><li><button type="button" data-fsel="item:'+it.id+'" class="'+(st.sel==='item:'+it.id?'on':'')+'">• '+esc(CAB.itemLabel(it))+' @ '+U(it.y)+'</button></li></ul>';});
    n.kids.forEach(function(k,i){if(i>0)h+='<ul><li><button type="button" data-fsel="div:'+n.id+':'+(i-1)+'" class="'+(st.sel==='div:'+n.id+':'+(i-1)?'on':'')+'">'+(n.dir==='v'?'┃ فاصل':'━ لوح ثابت')+'</button></li></ul>';w(k,(i+1));});
    h+='</li></ul>';
  })(s.root,'');
  h+='</li></ul><h5>الواجهات ('+s.fronts.length+')</h5><ul class="fe-tree">'+s.fronts.map(function(f,i){return '<li><button type="button" data-fsel="front:'+f.id+'" class="'+(st.sel==='front:'+f.id?'on':'')+'">▯ '+(i+1)+'. '+esc(CAB.FK[f.k])+(f.style&&f.style!=='flat'?' · '+esc(CAB.FS[f.style]):'')+(f.bind?'':' (حر)')+'</button></li>';}).join('')+'</ul>';
  b.innerHTML=h;
}
function warns(w){
  var b=$('#feWarn');if(!b)return;if(!w){try{w=CAB.gen(st.spec).warn;}catch(e){w=['تعذّر التوليد: '+(e&&e.message||e)];}}
  if(NV.CLASH){try{var cw=NV.CLASH.warns(CAB.gen(st.spec).panels).filter(function(x){return w.indexOf(x)<0;});if(cw.length)w=w.concat(cw);}catch(e){}}
  var n=$('#feWn');if(n)n.textContent=w.length?w.length:'';
  b.innerHTML=w.length?'<ul class="fe-wl">'+w.map(function(x){return '<li>'+esc(x)+'</li>';}).join('')+'</ul>':'<p class="fe-ok">لا توجد تنبيهات هندسية.</p>';
}

/* ---------- 3D والخامات (المرحلة 3) ---------- */
var WOOD=[['ميلامين أبيض','#efede7',0.45,'solid'],['MDF خام','#c9b48f',0.8,'solid'],['بلوط فاتح','#d8b88a',0.55,'wood','#b08756'],['جوز','#6e4a31',0.5,'wood','#4a2c1b'],
  ['ماهوجني','#8a4b33',0.45,'wood2','#5e2c1d'],['زان','#d9b38c',0.55,'wood2','#bb8d60'],['رمادي مطفي','#8e9399',0.7,'solid'],['أسود لامع','#1f2023',0.15,'solid']];
function v3(){
  var b=$('#feV3');if(!b||b.hidden&&st.view!=='3d')return;var e=E();if(!e||!e.ready){b.innerHTML='<p class="fe-note">محرك العرض 3D غير جاهز.</p>';return;}
  var s=st.spec,os=e.openState(),vs=e.mfgView()||{},rl=e.matRoles(),mats=e.mats(),R=null;try{R=CAB.gen(s);}catch(x){}
  function msel(id,cur){return '<select id="'+id+'"><option value="">— لون فقط —</option>'+mats.map(function(m){return '<option value="'+esc(m.id)+'"'+(m.id===cur?' selected':'')+'>'+esc(m.name)+'</option>';}).join('')+'</select>';}
  var miss=WOOD.filter(function(w){return !mats.some(function(m){return m.name===w[0];});}).length;
  var h='<h4>الحركة في المجسم</h4><div class="fe-acts">'+
    btn3('doors',(os.dOpen&&os.dOpen===os.doors?'إغلاق':'فتح')+' الأبواب ('+os.doors+')')+btn3('drawers',(os.wOpen&&os.wOpen===os.drawers?'إرجاع':'سحب')+' الأدراج ('+os.drawers+')')+btn3('all','فتح/إغلاق الكل')+
    (/^(front|item):/.test(st.sel)?btn3('one','فتح/إغلاق العنصر المحدد'):'')+'</div>'+
    '<p class="fe-note">مفتوح الآن: '+os.open+' من '+(os.doors+os.drawers)+'. يمكن أيضًا الضغط على باب أو درج في المجسم لفتحه.</p>'+
    '<h4>العرض</h4><label class="fe-c"><input type="checkbox" id="f3Nf"'+(vs.nofront?' checked':'')+'> إخفاء الأبواب والواجهات (رؤية التقسيم الداخلي)</label>'+
    '<label class="fe-c"><input type="checkbox" id="f3Nh"'+(vs.nohw?' checked':'')+'> إخفاء الإكسسوارات (مقابض، مواسير)</label>'+
    '<div class="fe-acts">'+btn3('before','قبل الأبواب')+btn3('after','بعد الأبواب')+btn3('show3d','عرض 3D','pri')+'</div>'+
    '<h4>الخامات</h4><div class="fe-row">'+fld('خشب الهيكل والداخل',msel('f3Wb',rl.body||''))+fld('لون الهيكل','<input type="color" id="f3Cb" value="'+(s.col||'#b98c5b')+'">')+'</div>'+
    '<div class="fe-row">'+fld('خشب الواجهات',msel('f3Wf',rl.front||''))+fld('لون الواجهات','<input type="color" id="f3Cf" value="'+(s.fcol||s.col||'#b98c5b')+'">')+'</div>'+
    (miss?'<div class="fe-acts">'+btn3('presets','إضافة '+miss+' خامات جاهزة إلى مكتبة المشروع')+'</div><p class="fe-note">بلوط، جوز، ماهوجني، زان، ميلامين، MDF خام، رمادي، أسود — ملمس إجرائي للعرض فقط؛ الأسعار من دليلك في التكلفة.</p>':'')+
    '<h4>السماكات (مم)</h4><div class="fe-row">'+fld('الهيكل',sel('f3T',[[16,'16'],[18,'18'],[19,'19'],[25,'25']].concat([16,18,19,25].indexOf(s.t)<0?[[s.t,String(s.t)]]:[]),s.t))+
      fld('الواجهات',sel('f3Ft',[[16,'16'],[18,'18'],[19,'19'],[22,'22'],[25,'25']],s.ft))+fld('الظهر',sel('f3Bt',[[3,'3'],[4,'4'],[6,'6'],[8,'8'],[18,'18']],s.bt))+btn3('thick','تطبيق')+'</div>'+
    '<h4>الإكسسوارات ('+(R?R.hw.length:0)+')</h4>'+(R&&R.hw.length?'<table class="fe-hw">'+R.hw.map(function(x){return '<tr><td>'+esc(x.name)+'</td><td>'+x.qty+' '+esc(x.unit)+'</td></tr>';}).join('')+'</table>':'<p class="fe-note">لا توجد.</p>');
  b.innerHTML=h;
}
function btn3(a,t,c){return '<button type="button" class="nvs-btn'+(c?' '+c:'')+'" data-f3="'+a+'">'+t+'</button>';}
function hi3d(){var e=E();if(e&&e.ready&&e.hiSrc)try{e.hiSrc(st.sel);}catch(x){}}
function show3d(){if(st.view!=='3d'){st.view='3d';var l=document.querySelector('.nvs-viewbar [data-lay="3d"]');if(l)l.click();render();}}
function act3(a){
  var e=E();
  if(a==='doors'||a==='drawers'||a==='all'){var n=e.openWhat(a);if(n){st.o3=st.o3||{};var os=e.openState();st.o3.doors=os.dOpen>0;st.o3.drawers=os.wOpen>0;}v3();return;}
  if(a==='one'){e.openWhat(st.sel);v3();return;}
  if(a==='before'){e.mfgView({nofront:true});show3d();v3();return;}
  if(a==='after'){e.mfgView({nofront:false});show3d();v3();return;}
  if(a==='show3d'){show3d();return;}
  if(a==='thick'){var t=+val('f3T'),ft=+val('f3Ft'),bt=+val('f3Bt');run(function(s){s.t=t;s.ft=ft;s.bt=bt;if(s.back==='none')s.back='over';return {ok:true};},'تغيير السماكات');return;}
  if(a==='presets'){var have=e.mats().map(function(m){return m.name;}),n=0;
    WOOD.forEach(function(w){if(have.indexOf(w[0])>-1)return;var d={name:w[0],c:w[1],r:w[2],m:0,tex:{k:w[3]}};if(w[4])d.tex.c2=w[4];if(e.matSave(d,'خامة جاهزة '+w[0]))n++;});
    toast('أُضيفت '+n+' خامات إلى مكتبة المشروع');reload();v3();return;}
}
/* بعد كل إعادة بناء: إعادة فتح ما كان مفتوحًا فورًا */
function keep3d(){var e=E();if(!st.o3||!e||!e.ready)return;if(st.o3.doors)e.openWhat('doors',1,true);if(st.o3.drawers)e.openWhat('drawers',1,true);}

/* ---------- الأحداث ---------- */
function zoneAt(wx,wy){var s=st.prev||st.spec,L=CAB.layout(clone(s)),hit=null;CAB.leaves(s.root).forEach(function(n){var z=L.zones[n.id];if(wx>=z.x0&&wx<=z.x1&&wy>=z.y0&&wy<=z.y1)hit={n:n,z:z};});return hit;}
function onClick(e){
  var b=e.target.closest('button');if(!b)return;
  if(b.dataset.fv){st.view=b.dataset.fv;st.fitDone=false;st.meas=null;if(st.view==='3d'){var l=document.querySelector('.nvs-viewbar [data-lay="3d"]');if(l)l.click();}render();return;}
  if(b.dataset.ft){st.tool=b.dataset.ft;st.meas=null;if(st.tool!=='sel'&&st.view!=='front'&&st.tool!=='meas'){st.view='front';st.fitDone=false;}render(true);return;}
  if(b.dataset.fs){$$('.fe-tabs button').forEach(function(x){x.classList.toggle('on',x===b);});['props','list','v3','warn'].forEach(function(k){$('#fe'+(k==='v3'?'V3':k.charAt(0).toUpperCase()+k.slice(1))).hidden=k!==b.dataset.fs;});if(b.dataset.fs==='v3')v3();return;}
  if(b.dataset.fsel){st.sel=b.dataset.fsel;st.tool='sel';render();return;}
  if(b.dataset.fa)return act(b.dataset.fa);
  if(b.dataset.fp)return pact(b.dataset.fp);
  if(b.dataset.f3)return act3(b.dataset.f3);
}
function onChange(e){
  var t=e.target;
  if(t.id==='feGs'){st.gsz=+t.value;render(true);}
  else if(t.id==='feDr'){st.doors=t.value;render();}
  else if(t.id==='feUn'){st.units=t.value;NV.set('units',t.value);render();}
  else if(t.id==='f3Nf'){E().mfgView({nofront:t.checked});hi3d();}
  else if(t.id==='f3Nh'){E().mfgView({nohw:t.checked});}
  else if(t.id==='f3Wb'||t.id==='f3Wf'){var roles=t.id==='f3Wb'?['body','inner']:['front'];if(t.value)E().matApplyRoles(t.value,roles);else E().matClearRoles(roles);setTimeout(function(){reload();v3();},20);}
  else if(t.id==='f3Cb'||t.id==='f3Cf'){var cb=t.id==='f3Cb';run(function(s){if(cb)s.col=t.value;else s.fcol=t.value;return {ok:true};},cb?'لون الهيكل':'لون الواجهات');}
}
/* لوحة المفاتيح أثناء فتح المحرر: نلتقطها قبل اختصارات الاستوديو حتى لا يحذف Delete القطعة كلها ولا يلغي Escape تحديدها.
   تراجع/إعادة/حفظ (Ctrl) تمر إلى الاستوديو ويُحدَّث المحرر من حدث المشهد. */
function onKey(e){
  if(!st.open)return;var t=e.target;if(t&&t.closest&&t.closest('input,select,textarea,#nvsPop'))return;
  if(e.ctrlKey||e.metaKey||e.altKey)return;
  if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();e.stopPropagation();act('del');}
  else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();st.tool='sel';st.meas=null;render(true);}
  else if(e.key.length===1){e.stopPropagation();var m={v:'sel',s:'shelf',d:'drw',r:'rail',m:'meas'}[e.key.toLowerCase()];if(m){st.tool=m;render(true);}}
}
document.addEventListener('keydown',onKey,true);
function act(a){
  if(a==='close')return close();
  if(a==='undo'||a==='redo'){E()[a]();setTimeout(function(){if(!reload()){toast('لم تعد القطعة محددة بعد التراجع — حددها من المشهد ثم افتح المحرر');close();return;}if(!exists(st.sel))st.sel='body';render();},30);return;}
  if(a==='dims'){st.dims=!st.dims;st.fitDone=false;render(true);return;}
  if(a==='grid'){st.grid=!st.grid;render(true);return;}
  if(a==='fit'){st.fitDone=false;render(true);return;}
  if(a==='zin'||a==='zout'){var c=$('#feCv');zoomAt(c.clientWidth/2,c.clientHeight/2,a==='zin'?1.25:0.8);return;}
  var m=(st.sel||'').split(':');
  if(a==='del'){
    if(m[0]==='item')return run(function(s){return CAB.OP.delItem(s,m[1]);},'حذف عنصر من التصميم');
    if(m[0]==='front')return run(function(s){return CAB.OP.delFront(s,m[1]);},'حذف واجهة');
    if(m[0]==='div')return run(function(s){return CAB.OP.removeDiv(s,m[1],+m[2]);},'حذف فاصل');
    if(m[0]==='zone'){var r=CAB.findNode(st.spec,m[1]);if(r&&!r.n.dir&&r.n.items.length){if(!confirm('حذف كل العناصر داخل هذا القسم؟'))return;return run(function(s){CAB.findNode(s,m[1]).n.items=[];return {ok:true};},'تفريغ قسم');}}
    toast('حدد رفًا أو درجًا أو ماسورة أو فاصلًا أو بابًا لحذفه');return;
  }
  if(a==='copy'){
    if(m[0]==='item'){var res=run(function(s){return CAB.OP.copyItem(s,m[1]);},'نسخ عنصر');if(res&&res.id){st.sel='item:'+res.id;render();}return;}
    if(m[0]==='front'){var rf=run(function(s){return CAB.OP.copyFront(s,m[1]);},'نسخ واجهة');if(rf&&rf.id){st.sel='front:'+rf.id;render();}return;}
    toast('النسخ متاح للرفوف والأدراج والمواسير والواجهات');return;
  }
}
/* V37: المواضع التلقائية للمفصلات (نفس حساب التخريم في nv-mfg) — للعرض كإرشاد فقط */
function feAutoHinges(h){
  var R={};try{R=(NV.E&&NV.E.mfgRules&&NV.E.mfgRules())||{};}catch(e){}
  var he=+R.hingeEnd||100,cd=+R.cupD||35,need=cd+5,n=(NV.MFG&&NV.MFG.hingesFor)?NV.MFG.hingesFor(h/10):(h<=900?2:h<=1600?3:h<=2000?4:5),o=[];
  if(!(h>0))return o;if(h-2*he<need*(n-1))he=Math.max(cd/2+3,(h-need*(n-1))/2);
  for(var i=0;i<n;i++)o.push(Math.round((he+i*(h-2*he)/(n-1))*10)/10);return o;
}
