      s.base.k=val('fpBk');s.base.h=s.base.k==='none'?0:(isFinite(bh)?Math.max(0,bh):80);s.mat={body:val('fpMb'),front:val('fpMf'),back:val('fpMk')};s.col=val('fpCol');s.handleT=val('fpHt');s.hcc=+val('fpHc');s.slideT=val('fpSl');
