  return c.map(function(p,i){var px=p[0]/1000+(cx-p[0]/1000)*0.12,pz=p[1]/1000+(cz-p[1]/1000)*0.12;return {name:'زاوية '+(i+1),p:[px,h,pz],t:[cx,0.9,cz],fov:65};});
