function shotsDlg(){
  var cams=E().cams?E().cams():[];
  pop('صور التصميم من الزوايا',
    '<p class="nvs-note">تُلتقط الصور من الكاميرات المحفوظة (تبويب «إضاءة وكاميرا»). إن لم تحفظ زوايا بعد، أنشئ 4 زوايا من أركان الغرفة.</p>'+
    '<p>الكاميرات المحفوظة: <b>'+cams.length+'</b></p><div class="nvs-acts"><button type="button" class="nvs-btn" data-rs="auto">حفظ 4 زوايا من الأركان</button>'+
    '<label class="nvs-f"><span>المقاس</span><select id="rsS"><option value="1280x800">1280×800</option><option value="1920x1080">1920×1080</option><option value="1080x1350">1080×1350 (هاتف)</option></select></label>'+
    '<button type="button" class="nvs-btn pri" data-rs="go"'+(cams.length?'':' disabled')+'>التقاط الصور</button></div><div id="rsOut" class="ro-shots"></div>');
  var P=$('#nvsPop');
  P.querySelector('[data-rs="auto"]').onclick=function(){var A=autoCams();A.forEach(function(c){E().camAdd(c,true);});E().commit('حفظ 4 زوايا للغرفة');shotsDlg();};
  P.querySelector('[data-rs="go"]').onclick=function(){var sz=$('#rsS').value.split('x').map(Number),out=[],errs=[];
    (E().cams()||[]).forEach(function(c){var r=E().render({w:sz[0],h:sz[1],cam:c.id,type:'image/jpeg',ss:1});if(r.err)errs.push(c.name+': '+r.err);else out.push({name:c.name,url:r.url});});
    st.shots=out;var box=$('#rsOut');
    box.innerHTML=(errs.length?'<div class="nvs-warn bad">'+errs.map(esc).join('<br>')+'</div>':'')+out.map(function(s,i){return '<figure><img src="'+s.url+'" alt="'+esc(s.name)+'"><figcaption>'+esc(s.name)+' <button type="button" class="nvs-btn" data-sd="'+i+'">تحميل</button></figcaption></figure>';}).join('')+
      (out.length?'<div class="nvs-acts"><button type="button" class="nvs-btn pri" data-sz="1">تحميل الكل ZIP</button>'+(navigator.canShare?'<button type="button" class="nvs-btn" data-sh="1">مشاركة</button>':'')+'</div>':'');
    $$('[data-sd]',box).forEach(function(b){b.onclick=function(){var s=st.shots[+b.dataset.sd];dl(s.url,fname(s.name)+'.jpg');};});
    var z=box.querySelector('[data-sz]');if(z)z.onclick=function(){var files=st.shots.map(function(s){return {name:fname(s.name)+'.jpg',data:b64(s.url)};});var blob=new Blob([NV.MFG.zip(files)],{type:'application/zip'});dl(URL.createObjectURL(blob),fname(E().project().name)+'-صور.zip');};
    var sh=box.querySelector('[data-sh]');if(sh)sh.onclick=function(){var fs=st.shots.map(function(s){return new File([b64(s.url)],fname(s.name)+'.jpg',{type:'image/jpeg'});});
      if(navigator.canShare({files:fs}))navigator.share({files:fs,title:E().project().name}).catch(function(e){if(e&&e.name!=='AbortError')toast('تعذّرت المشاركة: '+(e.message||e));});else toast('المتصفح لا يدعم مشاركة الصور — استخدم «تحميل»');};
    toast('التُقطت '+out.length+' صورة');};
}
function b64(url){var s=atob(url.split(',')[1]),a=new Uint8Array(s.length);for(var i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return a;}
function fname(s){return String(s||'صورة').replace(/[\\\/:*?"<>|]+/g,'-').slice(0,60);}
function dl(url,name){var a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();setTimeout(function(){a.remove();},100);}

