function walkPad(on){
  var st0=document.getElementById('nvsStage'),p=document.getElementById('roPad');
  if(!on){if(p)p.remove();return;}
  if(p)return;p=document.createElement('div');p.id='roPad';p.className='ro-pad';
  p.innerHTML='<button type="button" data-w="tl" aria-label="التفات لليسار">⟲</button><button type="button" data-w="f" aria-label="للأمام">▲</button><button type="button" data-w="tr" aria-label="التفات لليمين">⟳</button>'+
    '<button type="button" data-w="l" aria-label="خطوة لليسار">◀</button><button type="button" data-w="b" aria-label="للخلف">▼</button><button type="button" data-w="r" aria-label="خطوة لليمين">▶</button><button type="button" data-w="x" class="x">إنهاء التجول</button>';
  st0.appendChild(p);
  var rep=0;function go(k){var e=E();if(k==='x'){e.walk(false);return;}var m={f:[0.25,0,0],b:[-0.25,0,0],l:[0,-0.25,0],r:[0,0.25,0],tl:[0,0,-15],tr:[0,0,15]}[k];if(m)e.walkMove(m[0],m[1],m[2]);}
  p.addEventListener('pointerdown',function(e){var b=e.target.closest('[data-w]');if(!b)return;e.preventDefault();go(b.dataset.w);clearInterval(rep);if(b.dataset.w!=='x')rep=setInterval(function(){go(b.dataset.w);},180);});
  ['pointerup','pointerleave','pointercancel'].forEach(function(ev){p.addEventListener(ev,function(){clearInterval(rep);});});
}
document.addEventListener('keydown',function(e){var x=E();if(!x||!x.walking||!x.walking())return;var t=e.target;if(t&&t.closest&&t.closest('input,select,textarea'))return;
  var m={ArrowUp:[0.25,0,0],w:[0.25,0,0],ArrowDown:[-0.25,0,0],s:[-0.25,0,0],a:[0,-0.25,0],d:[0,0.25,0],ArrowLeft:[0,0,-15],q:[0,0,-15],ArrowRight:[0,0,15],e:[0,0,15]}[e.key];
  if(m){e.preventDefault();e.stopPropagation();x.walkMove(m[0],m[1],m[2]);}else if(e.key==='Escape'){e.stopPropagation();x.walk(false);}},true);
NV.on('walk',function(on){walkPad(on);});

