  st.view='form';var r=root();r.innerHTML='<div class="lb-ed"><h4>حفظ «'+esc(o.name)+'» في مكتبة الأثاث</h4>'+fld('الاسم','<input id="lfN" maxlength="80" value="'+esc(o.name)+'">')+fld('الفئة','<select id="lfC">'+opts(LIB.FCATS,'other')+'</select>')+fld('ملاحظات','<input id="lfNote" maxlength="300">')+
    '<div class="nvs-acts"><button type="button" class="nvs-btn pri" id="lfGo">حفظ</button><button type="button" class="nvs-btn" data-la="back">رجوع</button></div></div>';
