/* ---------- الربط ---------- */
function bind(){
  var r=root();if(!r)return;
  $$('[data-lt]',r).forEach(function(b){b.onclick=function(){st.tab=b.dataset.lt;st.view='list';st.cat='';st.q='';draw();};});
  $$('[data-lc]',r).forEach(function(b){b.onclick=function(){st.cat=b.dataset.lc;draw();};});
  var q=$('#lbQ',r);if(q)q.oninput=function(){st.q=q.value;var pos=q.selectionStart;draw();var q2=$('#lbQ');if(q2){q2.focus();try{q2.setSelectionRange(pos,pos);}catch(e){}}};
  $$('[data-lm]',r).forEach(function(b){b.onclick=function(){st.ed=LIB.mat(b.dataset.lm);if(!st.ed)return;st.view='edit';draw();};});
  $$('[data-la2]',r).forEach(function(b){b.onclick=function(){st.ed=LIB.acc(b.dataset.la2);if(!st.ed)return;st.view='edit';draw();};});
  $$('[data-lf]',r).forEach(function(b){b.onclick=function(){var id=b.dataset.id,a=b.dataset.lf;
    if(a==='ins')furnInsert(id);
    else if(a==='ren'){var d=LIB.furn(id),n=d&&prompt('اسم القطعة:',d.name);if(n&&n.trim())LIB.furnRename(id,n).then(draw,err);}
    else if(a==='del'){var d2=LIB.furn(id);if(d2&&confirm('حذف «'+d2.name+'» من مكتبة الأثاث؟ (لا يؤثر على المشاريع التي أُدرجت فيها)'))LIB.furnDel(id).then(draw,err);}};});
  $$('[data-la]',r).forEach(function(b){b.onclick=function(){act(b.dataset.la);};});
  /* محرر الخامة: معاينة حية */
  if(st.view==='edit'&&st.tab==='mats'){
    ['lbR','lbM','lbCC','lbO','lbB'].forEach(function(id){var e=$('#'+id);if(e)e.oninput=function(){$('#'+id+'o').textContent=e.value;};});
    var k=$('#lbK');if(k)k.onchange=function(){readMat();draw();};
    var kc=$('#lbCat');if(kc)kc.onchange=function(){readMat();draw();};
    ['lbC','lbC2'].forEach(function(id){var e=$('#'+id);if(e)e.onchange=function(){readMat();var s=$('.lb-edh .lb-sw');if(s)s.outerHTML=sw(st.ed,true);};});
    var f=$('#lbF');if(f)f.onchange=function(){var fl=f.files&&f.files[0];if(!fl)return;readImg(fl).then(function(url){readMat();st.ed.tex={k:'img',url:url,sc:st.ed.tex.sc||0.6};draw();},err);};
    var rl=$('#lbRole'),th=$('#lbTh');if(rl){rl.onchange=thNote;if(th)th.onchange=thNote;thNote();}
    bindCatSelect('lbApp');
  }
  if(st.view==='edit'&&st.tab==='acc')bindCatSelect('laApp');
  var imp=$('#lbImp',r);if(imp)imp.onchange=function(){var fl=imp.files&&imp.files[0];if(!fl)return;var fr=new FileReader();fr.onload=function(){var o;try{o=JSON.parse(fr.result);}catch(e){toast('الملف ليس JSON صالحًا');return;}
    LIB.importData(o).then(function(n){toast('استُورد: '+n.mats+' خامة، '+n.acc+' إكسسوار، '+n.furn+' قطعة أثاث'+(n.bad?' — تُجوهل '+n.bad+' عنصر غير صالح':''));draw();},err);};fr.readAsText(fl);};
}
function readImg(file){
  return new Promise(function(res,rej){if(!/^image\//.test(file.type)){rej(new Error('اختر ملف صورة'));return;}
    var fr=new FileReader();fr.onerror=function(){rej(new Error('تعذّر قراءة الصورة'));};fr.onload=function(){var im=new Image();im.onerror=function(){rej(new Error('الصورة غير صالحة'));};
      im.onload=function(){var M=1024,s=Math.min(1,M/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*s));c.height=Math.max(1,Math.round(im.height*s));c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',0.86));};im.src=fr.result;};fr.readAsDataURL(file);});
}
function act(a){
  if(a==='back'){st.view='list';draw();return;}
  if(a==='mnew'){st.ed={name:'',cat:st.cat||'mdf',th:[18],c:'#c8a27a',r:0.6,m:0,tex:{k:'solid'}};st.view='edit';draw();return;}
  if(a==='anew'){st.ed={name:'',cat:st.cat||'handle',hk:[],hn:''};st.view='edit';draw();return;}
  if(a==='mfromp'){matFromProj();return;}
  if(a==='msave'){readMat();LIB.matSave(st.ed).then(function(id){st.ed=LIB.mat(id);var pl=LIB.projectLink(id);if(pl&&E().ready){try{LIB.toProject(id);}catch(x){}}toast('حُفظت الخامة في المكتبة العامة'+(pl?' وحُدّثت في المشروع':''));draw();},err);return;}
  if(a==='mdup'){LIB.matDup(st.ed.id).then(function(id){st.ed=LIB.mat(id);toast('أُنشئت نسخة');draw();},err);return;}
  if(a==='mdel'){if(!confirm('حذف «'+st.ed.name+'» من المكتبة العامة؟ (تبقى نسختها في المشاريع التي استخدمتها)'))return;LIB.matDel(st.ed.id).then(function(){st.view='list';draw();},err);return;}
  if(a==='mapply'){applyMat();return;}
  if(a==='mtoproj'){try{var id=LIB.toProject(st.ed.id);if(id)toast('أُضيفت «'+st.ed.name+'» إلى مكتبة المشروع');}catch(x){err(x);}return;}
  if(a==='asave'){readAcc();LIB.accSave(st.ed).then(function(id){st.ed=LIB.acc(id);toast('حُفظ الإكسسوار في المكتبة');draw();},err);return;}
  if(a==='adup'){LIB.accDup(st.ed.id).then(function(id){st.ed=LIB.acc(id);toast('أُنشئت نسخة');draw();},err);return;}
  if(a==='adel'){if(!confirm('حذف «'+st.ed.name+'» من المكتبة؟'))return;LIB.accDel(st.ed.id).then(function(){st.view='list';draw();},err);return;}
  if(a==='aapply'){applyAcc();return;}
  if(a==='automap'){autoMap();draw();return;}
  if(a==='fsave'){furnSaveDlg();return;}
  if(a==='export'){exportLib();return;}
  if(a==='seeds'){LIB.restoreSeeds().then(function(n){toast(n?'استُعيد '+n+' عنصر أساسي':'كل العناصر الأساسية موجودة');draw();},err);return;}
}
function exportLib(){
  var o=LIB.exportData(),txt=JSON.stringify(o),d=new Date(),nm='مكتبة-الاستوديو-'+d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2)+'.json';
  try{var u=URL.createObjectURL(new Blob([txt],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=nm;document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(u);a.remove();},1500);toast('صُدّرت المكتبة: '+nm);}catch(e){err(e);}
  return txt;
}

