function opts(list,cur){return list.map(function(x){return '<option value="'+esc(x[0])+'"'+(String(x[0])===String(cur)?' selected':'')+'>'+esc(x[1])+'</option>';}).join('');}
function n1(v){return v==null||v===''?'':String(Math.round(+v*10)/10);}
var TABS=[['parts','القطع'],['hinge','المفصلات'],['drw','الأدراج'],['sd','أبواب السحاب'],['hw','الإكسسوارات'],['lu','الإضاءة والتنجيد'],['mat','ملخص الخامات']];
