var DEFDIM={'صندوق عام':[100,50,100],'دولاب / خزانة':[200,60,240],'سرير':[210,180,110],'غرفة نوم كاملة':[500,400,260],'طاولة تلفزيون':[200,45,55],'طاولة / سفرة':[180,90,76],'مكتب':[140,65,76],'كنبة':[220,95,85],'كرسي':[48,55,92],'تسريحة':[120,45,150],'كومدينو':[50,40,50],'مكتبة / رف':[120,35,185],'تصميم مخصص حر':[100,60,100],'جزامة / خزانة أحذية':[90,35,110],'مطبخ (وحدات)':[300,60,215],'بوفيه / نيش / فاترينة':[180,45,160],'كونسول / مدخل':[120,35,80],'بوف / دكة':[50,50,45],'ستارة':[240,15,260]};
