  if(st==='roman'){k.tag('القماش');var folds=5,fh=(H-16)*(1-op*0.7)/folds;for(var i=0;i<folds;i++){k.B(2,D*0.4+(i%2?0:1.2),H-16-(i+1)*fh,L-4,1.6,fh,i%2?fc:sh(fc,0.95));}return;}
