function mansView(){
  var ms=ML.mans();
  return '<div class="nvs-acts"><button type="button" class="nvs-btn" data-ml="back">→ المكتبة</button></div>'+
    '<p class="nvs-note">الفهرس ملف JSON تضيفه أنت (من موقع مورّد أو مكتبة مرخّصة توفّر فهرسًا، أو من جهازك). يُقرأ الفهرس فقط، ولا يُنزَّل أي مجسم إلا عند معاينته أو استخدامه. كل مجسم يجب أن يحمل ترخيصه، والمجسمات بلا ترخيص أو بترخيص غير تجاري تبقى محجوبة.</p>'+
    '<div class="ml-bar"><input type="url" id="mlManUrl" placeholder="https://…/manifest.json" aria-label="رابط الفهرس"><button type="button" class="nvs-btn pri" data-ml="manget">جلب الفهرس</button>'+
    '<label class="nvs-btn">فهرس من الجهاز…<input type="file" id="mlManFile" accept=".json,application/json" hidden></label></div>'+
    (ms.length?'<table class="nvs-tbl"><thead><tr><th>الفهرس</th><th>المجسمات</th><th></th></tr></thead><tbody>'+ms.map(function(m){return '<tr><td>'+esc(m.name)+'<br><small>'+esc(m.src||'ملف محلي')+'</small></td><td>'+m.n+'</td><td><button type="button" class="nvs-btn" data-ml="mandel" data-v="'+esc(m.src)+'">إزالة</button></td></tr>';}).join('')+'</tbody></table>':'<div class="nvs-empty">لا توجد فهارس.</div>')+
    '<details><summary>صيغة الفهرس</summary><pre class="ml-pre">'+esc(JSON.stringify({name:'فهرس المورّد',models:[{id:'sofa-01',name:'كنبة مودرن',cat:'sofa',url:'https://example.com/models/sofa-01.glb',thumb:'https://example.com/models/sofa-01.jpg',dims:[220,85,95],license:{type:'CC-BY-4.0',author:'اسم المصمم',url:'https://example.com/sofa-01'}}]},null,1))+'</pre><small>dims بالسنتيمتر [عرض، ارتفاع، عمق] — تُستخدم لضبط المقياس الحقيقي. الترخيص: CC0، CC-BY، CC-BY-SA، purchased، vendor، own، other.</small></details>';
}
