  h+='<label class="nvd-f"><span>الطلب</span><select id="mlOrd" data-ml="oselect"><option value="">— اختر —</option>'+os.map(function(o){return '<option value="'+esc(o.id)+'"'+(o.id===st.order?' selected':'')+'>'+esc(o.no+' — '+o.cust)+'</option>';}).join('')+'</select></label>';
  if(st.order){var sc=b.scopeOf(st.order);
    if(sc){h+='<p>مراجعة النطاق: <b class="'+(sc.approved?'nvs-good':'nvs-bad')+'">'+esc(sc.status)+'</b></p><div class="fl-items">'+sc.items.map(function(it){return '<div class="fl-it"><div><b>'+esc(it.name)+'</b> <small>'+esc(it.type)+'</small></div><button type="button" class="nvs-btn pri" data-ml="ordgo" data-ik="'+esc(it.ik)+'"'+(sc.approved?'':' disabled')+'>إضافة إلى هذا البند</button></div>';}).join('')+'</div>';}
  }
