  if(s.hingeT&&N.HINGEN)R.push(['المفصلات',N.HINGEN[s.hingeT]||s.hingeT]);
  if(s.slideT&&N.SLIDEN&&(s.modules||s.units||s.ped))R.push(['مجاري الأدراج',N.SLIDEN[s.slideT]||s.slideT]);
