  function nm(id){var d=e.matGet(id);return d?d.name:null;}
  if(m.lib){var n=nm(m.lib);if(n){var d=e.matGet(m.lib);R.push(['الخامة',n,d&&hexOk(d.c)?d.c:null]);}}
  Object.keys(m.rl||{}).forEach(function(r){var n2=nm(m.rl[r]);if(n2){var d2=e.matGet(m.rl[r]);R.push(['خامة '+(ROLE_N[r]||r),n2,d2&&hexOk(d2.c)?d2.c:null]);}});
