    if(!o.visible)return;var u=o.userData,k=u.kind,it=null;
    if(k==='room'){var sp=u.room;room={name:sp.name,area:NV.ROOM.areaM2(sp),H:R0(sp.H)};return;}
    if(k==='group'){o.children.forEach(function(c){if(c.userData&&c.userData.kind)f(c);});return;}
    if(k==='fvp')it={type:u.fvp.t,rows:fvpRows(u.fvp)};
    else if(k==='mfg'){var N=window.NVM;it={type:(N&&N.KINDS[u.mfg.kind])||u.mfg.kind,rows:mfgRows(u.mfg)};}
    else if(k==='model'){var m=u.model||{},L=NV.MLIB&&NV.MLIB.LIC[(m.lic||{}).type];it={type:'مجسم من مكتبة NIVEEN 3D',rows:[['الترخيص',(L?L.n:'')+((m.lic||{}).author?' — '+m.lic.author:'')]]};
      if(Math.abs(o.scale.x-1)>1e-3||Math.abs(o.scale.y-1)>1e-3||Math.abs(o.scale.z-1)>1e-3)it.rows.push(['المقاس','مقاس عرض (ليس المقاس الحقيقي)']);}
