var V82_MAP=[['إجمالي','all'],['مفتوحة','open'],['جاهزة','ready'],['متأخرة','late'],['قيمة','value'],['المتبقي','rem'],['خامات','mrp'],['شراء','pr']];
function v82Dash(){
  var v=document.getElementById('v-dash');if(!v)return;
  [].forEach.call(v.querySelectorAll('#kpis .kpi'),function(k){if(k.querySelector('.v82-kt'))return;var s=(k.querySelector('span')||{}).textContent||'',key='all';
    V82_MAP.some(function(m){if(s.indexOf(m[0])>=0){key=m[1];return true;}return false;});
    var i=document.createElement('i');i.className='v82-kt';i.setAttribute('aria-hidden','true');i.innerHTML=V82_KI[key]||V82_KI.all;k.insertBefore(i,k.firstChild);});
  [].forEach.call(v.querySelectorAll('table.rec'),function(t){var hs=[].map.call(t.querySelectorAll('thead th'),function(th){return th.textContent.trim();});if(!hs.length)return;
    [].forEach.call(t.querySelectorAll('tbody tr'),function(tr){[].forEach.call(tr.children,function(td,i){if(!td.hasAttribute('data-l')&&hs[i])td.setAttribute('data-l',hs[i]);});});});
  var d=document.getElementById('v82Date');if(d&&!d.textContent){try{d.textContent=new Date().toLocaleDateString('ar',{weekday:'long',day:'numeric',month:'long',year:'numeric'});}catch(e){}}
}
(function(){var v=document.getElementById('v-dash');if(!v||!window.MutationObserver)return;var t;
  new MutationObserver(function(){clearTimeout(t);t=setTimeout(v82Dash,30);}).observe(v,{childList:true,subtree:true});setTimeout(v82Dash,0);})();

